_SCRIPT = Path(__file__).resolve().parents[1] / "live-verify-fi-loop.py"
_spec = importlib.util.spec_from_file_location("live_verify_fi_loop", _SCRIPT)
_mod = importlib.util.module_from_spec(_spec)  # type: ignore[arg-type]
_spec.loader.exec_module(_mod)  # type: ignore[union-attr]

Results = _mod.Results
check = _mod.check
main = _mod.main
GuardViolation = _mod.GuardViolation
_ALLOWED_STAGE = _mod._ALLOWED_STAGE
_PARTS = _mod._PARTS

# ── loopback guard ────────────────────────────────────────────────────────────


@pytest.fixture(autouse=True)
def _loopback_guard(monkeypatch: pytest.MonkeyPatch) -> None:
    """Refuse any TCP connection that leaves loopback — all AWS is moto or mocked."""
    real_connect = socket.socket.connect

    def _connect(sock: socket.socket, address: Any) -> Any:
        host = address[0] if isinstance(address, tuple) else str(address)
        # 127.0.0.1:1 is the dead endpoint used in guard tests
        if host not in ("127.0.0.1", "::1", "localhost"):
            raise AssertionError(f"test tried to reach {address!r}")
        return real_connect(sock, address)

    monkeypatch.setattr(socket.socket, "connect", _connect)


# ── session reset fixture ─────────────────────────────────────────────────────


@pytest.fixture(autouse=True)
def _reset_session() -> Any:
    """Reset the singleton guarded session between tests (brief §Guard)."""
    yield
    _mod._SESSION = None
    _mod._SIGNAL_STATE.clear()


# ── signal reset fixture ──────────────────────────────────────────────────────


@pytest.fixture(autouse=True)
def _restore_signals() -> Any:
    """Restore SIGINT/SIGTERM/SIGHUP to their default after each test."""
    old_int = signal.getsignal(signal.SIGINT)
    old_term = signal.getsignal(signal.SIGTERM)
    old_hup = signal.getsignal(signal.SIGHUP)
    yield
    signal.signal(signal.SIGINT, old_int)
    signal.signal(signal.SIGTERM, old_term)
    signal.signal(signal.SIGHUP, old_hup)


# ── manifest directory redirect (W4 fix) ─────────────────────────────────────


@pytest.fixture(autouse=True)
def _redirect_manifest_dir(monkeypatch: pytest.MonkeyPatch, tmp_path: Path) -> None:
    """Patch _MANIFEST_DIR to tmp_path so no test writes to ~/.fi-loop-manifests/.

    W4 fix: tests were writing into the live durable manifest directory (e.g.
    test_k1_manifest_stage_mismatch_fails wrote a stage=prod manifest; test_gg10
    wrote and re-read a manifest from an earlier foreground run, making its outcome
    depend on leftover state).  Redirecting to tmp_path gives every test a clean,
    isolated manifest directory that is discarded after the test.
    """
    monkeypatch.setattr(_mod, "_MANIFEST_DIR", str(tmp_path))


# ── helpers ───────────────────────────────────────────────────────────────────


def _make_boto3_mock() -> Any:
    """Return a mock boto3 module that records calls and raises on use."""
    mock_b3 = MagicMock()

    def _refuse(*a: object, **k: object) -> None:
        raise AssertionError(f"boto3 called: args={a!r} kwargs={k!r}")

    mock_b3.Session.side_effect = _refuse
    mock_b3.client.side_effect = _refuse
    mock_b3.resource.side_effect = _refuse
    return mock_b3


def _dead_client(service: str, region: str = "us-west-2", part: str = "pre") -> Any:
    """Build a client through the guarded session pointed at a dead endpoint.

    Used in guard tests to confirm an operation passes the guard and reaches
    the network layer (EndpointConnectionError, not GuardViolation).
    endpoint_url is passed to the client constructor, not to Config (which
    does not accept it).  Brief §Guard.
    """
    import boto3  # noqa: PLC0415
    from botocore.config import Config  # noqa: PLC0415

    allowed = _mod._PART_ALLOWLISTS.get(part, frozenset())
    bc = _mod._make_guarded_bcsession(allowed)
    sess = boto3.Session(
        botocore_session=bc,
        aws_access_key_id="testing",
        aws_secret_access_key="testing",
        region_name=region,
    )
    cfg = Config(connect_timeout=1, retries={"total_max_attempts": 1})
    return sess.client(service, region_name=region,
                       endpoint_url="http://127.0.0.1:1", config=cfg)


# ── G1: stage guard before any AWS call ──────────────────────────────────────


def test_g1_stage_guard_refuses_prod() -> None:
    """G1: --stage prod returns exit 1 before creating any AWS client."""
    mock_b3 = _make_boto3_mock()
    with patch.dict(sys.modules, {"boto3": mock_b3}):
        rc = main(["--stage", "prod", "--part", "pre"])
    assert rc == 1
    mock_b3.Session.assert_not_called()
    mock_b3.client.assert_not_called()


def test_g1_stage_guard_accepts_staging(monkeypatch: pytest.MonkeyPatch) -> None:
    """G1: --stage staging passes the guard (and then the part runs)."""
    # Patch _run_part to skip to avoid real AWS calls
    monkeypatch.setattr(_mod, "_run_part", lambda *a, **k: None)
    rc = main(["--stage", "staging", "--part", "pre"])
    assert rc in (0, 1, 2)  # ran past the guard


