def test_g4_allowlist_service_name_not_endpoint_prefix() -> None:
    """G4: guard uses service_model.service_name (brief §Guard).

    CloudWatch's endpoint_prefix is 'monitoring'; its service_name is
    'cloudwatch'.  An op on cloudwatch that is not in the allowlist must
    raise GuardViolation using the service_name, not the endpoint_prefix.
    """
    cw = _dead_client("cloudwatch")
    exc_info: list[GuardViolation] = []
    try:
        cw.put_metric_data(Namespace="test", MetricData=[])
    except GuardViolation as e:
        exc_info.append(e)
    except Exception:
        pass  # connection error is also acceptable (guard passed — but cloudwatch
              # is NOT in _PRE_ALLOWLIST, so GuardViolation is expected)
    if exc_info:
        assert "cloudwatch" in str(exc_info[0]).lower(), (
            f"GuardViolation should mention 'cloudwatch' service_name, "
            f"not 'monitoring' endpoint_prefix; got: {exc_info[0]}"
        )
    else:
        # cloudwatch.PutMetricData is not in _PRE_ALLOWLIST → GuardViolation required
        pytest.fail("cloudwatch.PutMetricData should raise GuardViolation in pre part")


# ── X1/X2/X3: exit code mapping ──────────────────────────────────────────────


def test_x1_exit_0_all_pass() -> None:
    """X1: all PASS → exit 0."""
    res = Results()
    check(res, "a", True, "ok")
    check(res, "b", True, "ok")
    assert not res.has_any_fail
    assert not res.has_any_skip


def test_x2_exit_1_any_fail() -> None:
    """X2: any FAIL → has_any_fail."""
    res = Results()
    check(res, "a", True, "ok")
    check(res, "b", False, on_fail="bad")
    assert res.has_any_fail


def test_x3_exit_2_any_skip_no_fail() -> None:
    """X3: SKIP but no FAIL → has_any_skip."""
    res = Results()
    check(res, "a", True, "ok")
    res.skip("b", "why")
    assert res.has_any_skip
    assert not res.has_any_fail


def test_x_exit_1_over_2_when_both() -> None:
    """FAIL overrides SKIP: has_any_fail is checked first in main()."""
    res = Results()
    res.skip("a", "why")
    check(res, "b", False, on_fail="bad")
    assert res.has_any_fail
    assert res.has_any_skip


# ── C1: check() detail vs on_fail selection ───────────────────────────────────


def test_c1_check_pass_shows_detail() -> None:
    """C1: on PASS, detail is shown (not on_fail)."""
    res = Results()
    check(res, "row", True, "good detail", on_fail="should not appear")
    row = {r[0]: (r[1], r[2]) for r in res.rows}
    assert row["row"] == ("PASS", "good detail")


def test_c1_check_fail_shows_on_fail() -> None:
    """C1: on FAIL with on_fail, on_fail text is shown."""
    res = Results()
    check(res, "row", False, "ok detail", on_fail="fail detail")
    row = {r[0]: (r[1], r[2]) for r in res.rows}
    assert row["row"] == ("FAIL", "fail detail")


def test_c1_check_fail_shows_detail_when_no_on_fail() -> None:
    """C1: on FAIL without on_fail, detail is shown."""
    res = Results()
    check(res, "row", False, "the detail")
    row = {r[0]: (r[1], r[2]) for r in res.rows}
    assert row["row"] == ("FAIL", "the detail")


