# ── S2: _defer_signals_for_restore holds signals ─────────────────────────────


def test_s2_defer_holds_sigint_and_redelivers() -> None:
    """S2: SIGINT sent during _defer_signals_for_restore is re-delivered after.

    Sets up a counting handler, enters the defer context, sends SIGINT, verifies
    it is held during the context, then verifies it arrives after the context exits.
    Brief §Signals.
    """
    delivered: list[int] = []

    def _count(sig: int, _frame: object) -> None:
        delivered.append(sig)

    # Install the counting handler for SIGINT before entering the defer context
    old = signal.getsignal(signal.SIGINT)
    signal.signal(signal.SIGINT, _count)
    try:
        with _mod._defer_signals_for_restore():
            os.kill(os.getpid(), signal.SIGINT)
            # Signal must be held inside the context
            assert not delivered, "SIGINT should be held inside _defer_signals_for_restore"
        # After the context, the original _count handler is restored and the pending
        # SIGINT is re-sent via os.kill; _count increments delivered
        assert signal.SIGINT in delivered, (
            "SIGINT should be re-delivered after _defer_signals_for_restore exits"
        )
    finally:
        signal.signal(signal.SIGINT, old)


def test_s2_defer_holds_sighup() -> None:
    """S2: SIGHUP sent during _defer_signals_for_restore is re-delivered after."""
    delivered: list[int] = []

    def _count(sig: int, _frame: object) -> None:
        delivered.append(sig)

    old = signal.getsignal(signal.SIGHUP)
    signal.signal(signal.SIGHUP, _count)
    try:
        with _mod._defer_signals_for_restore():
            os.kill(os.getpid(), signal.SIGHUP)
            assert not delivered, "SIGHUP should be held inside _defer_signals_for_restore"
        assert signal.SIGHUP in delivered, (
            "SIGHUP should be re-delivered after _defer_signals_for_restore exits"
        )
    finally:
        signal.signal(signal.SIGHUP, old)


# ── S3: subprocess rc 143 via runpy.run_path ─────────────────────────────────


def test_s3_subprocess_sigint_rc_143(tmp_path: Path) -> None:
    """S3: runpy.run_path loads the module; SIGINT → rc 143 (brief §Signals).

    The helper script loads the module globals via runpy.run_path (without
    triggering __main__), calls _install_signal_handlers(), then sends SIGINT
    to itself.  The installed handler raises SystemExit(143) → rc 143.
    """
    helper = tmp_path / "helper.py"
    helper.write_text(
        f"import sys, os, signal, runpy\n"
        f"ns = runpy.run_path({str(_SCRIPT)!r})\n"
        f"ns['_install_signal_handlers']()\n"
        f"os.kill(os.getpid(), signal.SIGINT)\n"
    )
    result = subprocess.run(
        [sys.executable, str(helper)],
        capture_output=True,
        timeout=5,
    )
    assert result.returncode == 143, (
        f"expected rc 143 (SIGINT → SystemExit(143)), "
        f"got {result.returncode}; "
        f"stderr={result.stderr[-200:]!r}"
    )


# ── I1: subprocess import test ────────────────────────────────────────────────


def test_i1_subprocess_import_no_pythonpath(tmp_path: Path) -> None:
    """I1: run script from a temp cwd with PYTHONPATH stripped; verify it starts.

    With no PYTHONPATH, repo root is not on sys.path; the script prepends it
    itself (_REPO_ROOT).  The test checks that the script exits with code 1
    (stage 'prod' refused) rather than ImportError, proving lazy imports work.
    Brief §Imports.
    """
    env = {k: v for k, v in os.environ.items() if k not in ("PYTHONPATH",)}
    result = subprocess.run(
        [sys.executable, "-I", str(_SCRIPT), "--stage", "prod", "--part", "pre"],
        capture_output=True,
        cwd=str(tmp_path),
        env=env,
    )
    # Stage check refuses before any import; exits 1
    assert result.returncode == 1, (
        f"expected exit 1 (stage refused), got {result.returncode}; "
        f"stderr={result.stderr[-200:]!r}"
    )


# ── W helpers: world setup ────────────────────────────────────────────────────

def _make_zip_with_9_3_code() -> bytes:
    """Return a Lambda zip that passes the 9.3 code check (brief §Tier 2 code)."""
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w") as zf:
        # readers.py: must NOT contain 'rcr.name'
        zf.writestr(
            "agents/fi_quality/readers.py",
            "def select_campaigns():\n    return 'SELECT * FROM recall_campaigns_issued'\n",
        )
        # select_recalls.sql: must contain 'recall_campaigns_issued'
        zf.writestr(
            "agents/fi_recall_warranty/sql/select_recalls.sql",
            "SELECT * FROM adp_staging_engineering.recall_campaigns_issued i\n"
            "JOIN recall_campaigns r ON r.campaign_id = i.campaign_id\n",
        )
    buf.seek(0)
    return buf.read()


def _make_zip_with_old_code_readers() -> bytes:
    """Return a zip where readers.py still has rcr.name (pre-9.3)."""
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w") as zf:
        zf.writestr(
            "agents/fi_quality/readers.py",
            "# old code: SELECT rcr.name FROM recall_campaigns rcr\n",
        )
        zf.writestr(
            "agents/fi_recall_warranty/sql/select_recalls.sql",
            "SELECT * FROM adp_staging_engineering.recall_campaigns_issued i\n",
        )
    buf.seek(0)
    return buf.read()


def _make_zip_with_missing_sql_join() -> bytes:
    """Return a zip where select_recalls.sql has no recall_campaigns_issued join."""
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w") as zf:
        zf.writestr(
            "agents/fi_quality/readers.py",
            "def select_campaigns():\n    return 'clean'\n",
        )
        zf.writestr(
            "agents/fi_recall_warranty/sql/select_recalls.sql",
            "SELECT * FROM adp_staging_engineering.recall_campaigns r\n",
        )
    buf.seek(0)
    return buf.read()


def _glue_stub(
    recall_table_exists: bool = True,
    view_has_issued: bool = True,
) -> Any:
    """Return a stub Glue client for pre tests.

    Brief §Preconditions: recall_campaigns_issued and received view checks.
    F6a fix: views return Presto View envelope format (base64-encoded JSON
    wrapping originalSql), not plain SQL.
    """
    import base64, json as _json  # noqa: E401,PLC0415
    from botocore.exceptions import ClientError  # noqa: PLC0415

    stub = MagicMock()

    def _make_presto_view_text(sql: str) -> str:
        """Encode SQL as a Presto View envelope: /* Presto View: <base64> */"""
        payload = {"originalSql": sql, "catalog": "awsdatacatalog", "schema": "default",
                   "columns": [], "owner": "123456789012", "runAsInvoker": False,
                   "properties": {}, "isProtected": False, "isMultiDialect": False}
        b64 = base64.b64encode(_json.dumps(payload).encode()).decode()
        return f"/* Presto View: {b64} */"

    _received_sql = (
        "SELECT * FROM adp_staging_fleet_recall.recall_campaigns "
        "UNION ALL SELECT * FROM adp_staging_engineering.recall_campaigns_issued"
        if view_has_issued else
        "SELECT * FROM adp_staging_fleet_recall.recall_campaigns"
    )
    _status_sql = (
        "SELECT vin FROM adp_staging_engineering.recall_campaigns_issued i "
        "CROSS JOIN UNNEST(i.component_lots) t (lot)"
        if view_has_issued else
        "SELECT vin FROM adp_staging_fleet_recall.recall_campaigns r"
    )

    def _get_table(DatabaseName: str, Name: str, **_kw: Any) -> dict:
        if Name == "recall_campaigns_issued":
            if not recall_table_exists:
                raise ClientError(
                    {"Error": {"Code": "EntityNotFoundException", "Message": "not found"}},
                    "GetTable",
                )
            return {"Table": {"Name": "recall_campaigns_issued",
                              "DatabaseName": DatabaseName}}
        if Name == "recall_campaigns_received":
            return {"Table": {"Name": "recall_campaigns_received",
                              "DatabaseName": DatabaseName,
                              "ViewOriginalText": _make_presto_view_text(_received_sql)}}
        if Name == "recall_vehicle_status":
            return {"Table": {"Name": "recall_vehicle_status",
                              "DatabaseName": DatabaseName,
                              "ViewOriginalText": _make_presto_view_text(_status_sql)}}
        raise ClientError(
            {"Error": {"Code": "EntityNotFoundException", "Message": "not found"}},
            "GetTable",
        )

    stub.get_table.side_effect = _get_table
    return stub


