def _ddb_stub(
    *,
    inv_items: list[dict] | None = None,
    pattern_items: list[dict] | None = None,
    corpus_item: dict | None = None,
    use_attribute_values: bool = False,
) -> Any:
    """Return a stub DynamoDB (low-level) client for pre tests.

    *inv_items*: items in the investigations table (default: empty).
    *pattern_items*: items in the fault-patterns table.
    *corpus_item*: the engineering-corpus item for the failure mode.

    F6a fix: default pattern has code_family, pattern_group_id==pattern_id,
    candidate_rank=1 (no failure_mode_id); default corpus has cause_dimension,
    component_id, symptom_codes for _rules_match_failure_mode to work.
    """
    stub = MagicMock()

    _inv = inv_items if inv_items is not None else []
    _patterns = pattern_items if pattern_items is not None else [{
        # F6a: real producer shape — no failure_mode_id
        "pattern_id":       {"S": "pat-supplier-lot-001"},
        "pattern_group_id": {"S": "pat-supplier-lot-001"},  # rule 2: must equal pattern_id
        "candidate_rank":   {"N": "1"},
        "code_family":      {"S": "P1AB"},                  # maps to FM-CHG-01-like via corpus
        "cohort_dimension": {"S": "supplier_lot"},
        "cohort_value":     {"S": "SUP-A/LOT-001"},
        "affected_vins": {"L": [
            {"S": "1MRDNA0A4MA000001"},
            {"S": "1MRDNA0A5MA000002"},
        ]},
    }]
    _corpus = corpus_item if corpus_item is not None else {
        "pk": {"S": "fm#fm-susp-bushing-001"},
        "failure_mode_id": {"S": "fm-susp-bushing-001"},
        "component_name": {"S": "Front Suspension Bushing"},
        "component_id": {"S": "suspension_bushing"},
        # F6a: cause_dimension="supplier_lot" + do_not_drive=False → safe rule passes
        "cause_dimension": {"S": "supplier_lot"},
        # F6a: symptom_codes with P1AB prefix → _rules_match_failure_mode picks this FM
        "symptom_codes": {"L": [{"S": "P1AB0"}, {"S": "P1AB1"}]},
        # C10 fix: do_not_drive is a failure-mode field, not an option field.
        "do_not_drive": {"BOOL": False},
        "park_outside": {"BOOL": False},
        # K3: default corpus includes a hardware_recall option with valid K3 criteria
        "options": {"L": [
            {"M": {
                "remedy_option_id": {"S": "opt-recall-001"},
                "remedy_type": {"S": "hardware_recall"},
                "lead_time_weeks": {"N": "8"},
            }},
            {"M": {
                "remedy_option_id": {"S": "opt-monitor-001"},
                "remedy_type": {"S": "monitor"},
                "lead_time_weeks": {"N": "0"},
            }},
        ]},
    }

    def _scan(TableName: str, **kw: Any) -> dict:
        if "investigations" in TableName:
            return {"Items": _inv, "Count": len(_inv)}
        if "fault-patterns" in TableName:
            return {"Items": _patterns, "Count": len(_patterns)}
        if "engineering-corpus" in TableName:
            # Return the single corpus item for the full-corpus scan in _pick_pattern
            return {"Items": [_corpus], "Count": 1}
        return {"Items": [], "Count": 0}

    def _get_item(TableName: str, Key: dict, **_kw: Any) -> dict:
        if "engineering-corpus" in TableName:
            return {"Item": _corpus}
        return {"Item": None}

    stub.scan.side_effect = _scan
    stub.get_item.side_effect = _get_item
    return stub


