def _athena_stub_returning_vins(vins: list[str]) -> Any:
    """Return a stub Athena client whose GetQueryResults serves multiple query types:
    - Component-count queries (from _pick_pattern rule 4): GROUP BY bc.component_id →
      returns one row per component with the VIN count.
    - VIN queries (from _compute_expected_vins): returns the VIN list.

    F6a fix: distinguishes new GROUP BY query (component_id in SELECT) from VIN query.
    K2: the VINs come from vehicle_build_components, not from pattern.affected_vins.
    """
    stub = MagicMock()
    _query_sql: dict[str, str] = {}  # qeid → sql

    def _start(QueryString: str = "", **kw: Any) -> dict:
        qeid = f"qe-test-{len(_query_sql):03d}"
        _query_sql[qeid] = QueryString
        return {"QueryExecutionId": qeid}

    stub.start_query_execution.side_effect = _start
    stub.get_query_execution.side_effect = lambda QueryExecutionId, **kw: {
        "QueryExecution": {
            "QueryExecutionId": QueryExecutionId,
            "Status": {"State": "SUCCEEDED"},
        }
    }

    # F6a: component count rows — default component is "suspension_bushing" with 2 VINs
    # (matching the default corpus item's component_id and the default VIN list)
    comp_count_rows = [
        {"Data": [{"VarCharValue": "component_id"}, {"VarCharValue": "cnt"}]},
        {"Data": [{"VarCharValue": "suspension_bushing"}, {"VarCharValue": str(len(vins))}]},
    ]
    vin_rows = [{"Data": [{"VarCharValue": "vin"}]}] + [
        {"Data": [{"VarCharValue": v}]} for v in vins
    ]

    def _get_results(QueryExecutionId: str = "", **kw: Any) -> dict:
        sql = _query_sql.get(QueryExecutionId, "")
        # F6a: new GROUP BY query has "component_id" in SELECT; old count had "COUNT"
        if "component_id" in sql.lower() and "group by" in sql.lower():
            rows = comp_count_rows
        else:
            rows = vin_rows
        return {"ResultSet": {"Rows": rows}}

    stub.get_query_results.side_effect = _get_results
    return stub


