class _FakeClientFactory:
    """Intercepts _client(service, region) and returns appropriate stubs.

    Can be configured per test to inject specific stub variants.
    """

    def __init__(
        self,
        *,
        code_zip: bytes | None = None,
        esm_state: str = "Enabled",
        recall_table_exists: bool = True,
        view_has_issued: bool = True,
        dlq_messages: int = 0,
        inv_items: list[dict] | None = None,
        pattern_items: list[dict] | None = None,
        corpus_item: dict | None = None,
        now_hour: int = 10,  # 10:00 UTC — well outside windows
        has_livetest_user: bool = False,  # K6: inject a leftover Cognito temp user
    ) -> None:
        self.code_zip = code_zip if code_zip is not None else _make_zip_with_9_3_code()
        self.esm_state = esm_state
        self.recall_table_exists = recall_table_exists
        self.view_has_issued = view_has_issued
        self.dlq_messages = dlq_messages
        self.inv_items = inv_items
        self.pattern_items = pattern_items
        self.corpus_item = corpus_item
        self.now_hour = now_hour
        self.has_livetest_user = has_livetest_user

    def make_client(self, service: str, region: str, **_kw: Any) -> Any:
        if service == "sts":
            return _sts_stub()
        if service == "scheduler":
            return _scheduler_stub()
        if service == "lambda":
            return _lambda_stub(
                self.code_zip, self.esm_state
            )
        if service == "glue":
            return _glue_stub(self.recall_table_exists, self.view_has_issued)
        if service == "sqs":
            return _sqs_stub(self.dlq_messages)
        if service == "cognito-idp":
            return (
                _cognito_stub_with_livetest_user()
                if self.has_livetest_user
                else _cognito_stub_clean()
            )
        if service == "athena":
            # K2: stub returns 2 fixed VINs (matching the default pattern's lot)
            return _athena_stub_returning_vins(
                ["1MRDNA0A4MA000001", "1MRDNA0A5MA000002"]
            )
        if service == "dynamodb":
            return _ddb_stub(
                inv_items=self.inv_items,
                pattern_items=self.pattern_items,
                corpus_item=self.corpus_item,
            )
        raise AssertionError(f"unexpected service {service!r} in test")


def _run_pre(factory: _FakeClientFactory, tmp_path: Path) -> Results:
    """Drive main() --part pre with stubs from *factory*; return Results."""
    import datetime as _dt  # noqa: PLC0415

    fixed_now = _dt.datetime(2026, 10, 21, factory.now_hour, 0, 0,
                             tzinfo=_dt.timezone.utc)

    code_zip = factory.code_zip

    def _fake_download(url: str) -> bytes:
        return code_zip

    res_holder: list[Results] = []
    real_results_class = _mod.Results

    class _CapResults(real_results_class):  # type: ignore[misc,valid-type]
        def __init__(self) -> None:
            super().__init__()
            res_holder.append(self)

    with (
        patch.object(_mod, "_client", factory.make_client),
        patch.object(_mod, "_download_code_zip", _fake_download),
        patch.object(_mod, "_utc_now", lambda: fixed_now),
        patch.object(_mod, "Results", _CapResults),
        patch.object(_mod, "_manifest_path",
                     lambda rid: str(tmp_path / f"{rid}-manifest.json")),
    ):
        main(["--stage", "staging", "--part", "pre"])

    assert res_holder, "Results was never instantiated"
    return res_holder[0]


# ── W1: pre pass — all preconditions satisfied ────────────────────────────────


def test_w1_pre_pass_all(tmp_path: Path) -> None:
    """W1: all preconditions satisfied → all PASS, manifest written at 0600."""
    factory = _FakeClientFactory()
    res = _run_pre(factory, tmp_path)

    fails = [(r[0], r[2]) for r in res.rows if r[1] == "FAIL"]
    assert not fails, f"unexpected FAILs: {fails}"
    skips = [(r[0], r[2]) for r in res.rows if r[1] == "SKIP"]
    assert not skips, f"unexpected SKIPs: {skips}"

    # Manifest written: any file matching the pattern in tmp_path
    manifests = list(tmp_path.glob("fi-loop-*-manifest.json"))
    assert manifests, f"no manifest file in {tmp_path}"
    manifest_file = manifests[0]
    st = manifest_file.stat()
    assert stat.S_IMODE(st.st_mode) == 0o600, (
        f"manifest perms should be 0600, got {oct(stat.S_IMODE(st.st_mode))}"
    )
    data = json.loads(manifest_file.read_text())
    assert data["stage"] == "staging"
    assert data["part"] == "pre"
    assert "run_id" in data


