    _status_fixture = _load_fixture("glue-get-table-recall_vehicle_status.json")

    def _get_table(DatabaseName: str, Name: str, **_kw: Any) -> dict:
        if Name == "recall_campaigns_issued":
            return {"Table": {"Name": "recall_campaigns_issued", "DatabaseName": DatabaseName}}
        if Name == "recall_campaigns_received":
            return _received_fixture
        if Name == "recall_vehicle_status":
            if not both_views_present:
                raise ClientError(
                    {"Error": {"Code": "EntityNotFoundException", "Message": "not found"}},
                    "GetTable",
                )
            return _status_fixture
        raise ClientError(
            {"Error": {"Code": "EntityNotFoundException", "Message": "not found"}},
            "GetTable",
        )
    stub.get_table.side_effect = _get_table
    return stub


