def test_a5_invalid_base64_names_step() -> None:
    """S7/b64-no-validate: non-base64 characters in the payload raise ValueError naming 'base64'.

    The b64-no-validate mutant accepts arbitrary payloads without validation (validate=False),
    which silently strips non-base64 characters and may decode a corrupt payload successfully.
    This test ensures non-base64 characters are caught before decoding, and the error
    names the 'base64' step.

    Key: with validate=False, a leading '!' is silently stripped and decoding succeeds
    (returning the underlying JSON), but the function then returns the wrong SQL without
    any error. With validate=True, the '!' is rejected immediately with 'base64 decode failed'.
    """
    import base64 as _b64  # noqa: PLC0415
    # Build a valid base64 payload (a JSON object with originalSql) and prefix with '!'
    # validate=False: strips '!', decodes correctly, returns SQL (no error!) → mutant passes
    # validate=True: raises "Only base64 data is allowed" → wrapped as ValueError("base64 ...")
    valid_sql = "SELECT * FROM adp_staging_engineering.recall_campaigns_issued"
    payload = json.dumps({"originalSql": valid_sql, "catalog": "awsdatacatalog",
                          "schema": "staging", "columns": [], "owner": "123456789012",
                          "runAsInvoker": False, "properties": {},
                          "isProtected": False, "isMultiDialect": False})
    b64 = "!" + _b64.b64encode(payload.encode()).decode()
    view_text = f"/* Presto View: {b64} */"
    with pytest.raises(ValueError, match="base64"):
        _mod._decode_presto_view_text(view_text)


def test_a5_missing_originalSql_names_step() -> None:
    """S7/origsql-fallback: valid base64 + JSON but no 'originalSql' key → ValueError naming the field.

    The origsql-fallback mutant uses the raw JSON string when 'originalSql' is absent;
    this test ensures the strict check fires and names the missing key.
    """
    import base64 as _b64  # noqa: PLC0415
    # Valid base64 of a JSON object that lacks 'originalSql'
    payload = json.dumps({"catalog": "awsdatacatalog", "schema": "staging", "columns": []})
    b64 = _b64.b64encode(payload.encode()).decode()
    view_text = f"/* Presto View: {b64} */"
    with pytest.raises(ValueError, match="originalSql"):
        _mod._decode_presto_view_text(view_text)


def test_a5_word_boundary_required() -> None:
    """S7/no-word-boundary: '..._issued_v2' must NOT match the stage-qualified check.

    The no-word-boundary mutant uses a non-word-bounded pattern and would match
    recall_campaigns_issued_v2 as if it were recall_campaigns_issued.
    """
    import base64 as _b64  # noqa: PLC0415
    # SQL references 'recall_campaigns_issued_v2' — no word boundary after 'issued'
    wrong_sql = (
        "SELECT * FROM adp_staging_engineering.recall_campaigns_issued_v2 "
        "JOIN adp_staging_fleet_recall.recall_vehicle_status USING (campaign_id)"
    )
    payload = json.dumps({"originalSql": wrong_sql, "catalog": "awsdatacatalog",
                          "schema": "staging", "columns": [], "owner": "123456789012",
                          "runAsInvoker": False, "properties": {},
                          "isProtected": False, "isMultiDialect": False})
    b64 = _b64.b64encode(payload.encode()).decode()
    view_text = f"/* Presto View: {b64} */"

    res = _mod.Results()
    stub = MagicMock()

    def _get_table_wrong_boundary(DatabaseName: str, Name: str, **_kw: Any) -> dict:
        if Name in ("recall_campaigns_received", "recall_vehicle_status"):
            return {"Table": {"Name": Name, "DatabaseName": DatabaseName,
                              "ViewOriginalText": view_text}}
        return {"Table": {"Name": Name, "DatabaseName": DatabaseName}}
    stub.get_table.side_effect = _get_table_wrong_boundary

    ok = _mod._check_view_sql_unions_issued(res, stub, "staging")
    labels = {r[0]: r[1] for r in res.rows}
    # Must FAIL because recall_campaigns_issued_v2 ≠ recall_campaigns_issued (word-bounded)
    assert (labels.get("pre-view-sql-received") == "FAIL"
            or labels.get("pre-view-sql-status") == "FAIL"), (
        f"S7: 'recall_campaigns_issued_v2' must NOT match word-bounded pattern; "
        f"rows={res.rows}"
    )
    assert not ok, "should return False for non-word-bounded match"


# ── F6a: pick-logic break tests (b1-b5, b9) ─────────────────────────────────


def _make_pick_pattern_items(
    *,
    pid: str = "pat-001",
    pgid: str | None = None,   # None → same as pid (default: group-top)
    code_family: str = "P1AB",
    cohort_dimension: str = "supplier_lot",
    cohort_value: str = "SUP-A/LOT-001",
    candidate_rank: int = 1,
) -> list[dict]:
    """Build a minimal DDB pattern row list for pick tests."""
    return [{
        "pattern_id":       {"S": pid},
        "pattern_group_id": {"S": pgid if pgid is not None else pid},
        "candidate_rank":   {"N": str(candidate_rank)},
        "code_family":      {"S": code_family},
        "cohort_dimension": {"S": cohort_dimension},
        "cohort_value":     {"S": cohort_value},
        "affected_vins": {"L": [{"S": "1MRDNA0A4MA000001"}, {"S": "1MRDNA0A5MA000002"}]},
    }]


def _make_corpus_item(
    *,
    fm_id: str = "fm-test-001",
    cause_dimension: str = "supplier_lot",
    component_id: str = "test_component",
    do_not_drive: bool = False,
    symptom_codes: list[str] | None = None,
    lead_time_weeks: float = 8.0,
    has_component_name: bool = True,
) -> dict:
    """Build a minimal DDB corpus item for pick tests."""
    sc = symptom_codes if symptom_codes is not None else ["P1AB0", "P1AB1"]
    item: dict[str, Any] = {
        "pk": {"S": f"fm#{fm_id}"},
        "failure_mode_id": {"S": fm_id},
        "cause_dimension": {"S": cause_dimension},
        "component_id": {"S": component_id},
        "do_not_drive": {"BOOL": do_not_drive},
        "park_outside": {"BOOL": False},
        "symptom_codes": {"L": [{"S": c} for c in sc]},
        "options": {"L": [{"M": {
            "remedy_option_id": {"S": "opt-recall-001"},
            "remedy_type": {"S": "hardware_recall"},
            "lead_time_weeks": {"N": str(lead_time_weeks)},
        }}]},
    }
    if has_component_name:
        item["component_name"] = {"S": "Test Component"}
    return item


def _run_pick_pattern_with(
    pattern_items: list[dict],
    corpus_item: dict,
    athena_vins: list[str] | None = None,
) -> tuple[Any, Any]:
    """Run _pick_pattern with the given items; return (res, pick_result_tuple)."""
    ddb = _ddb_stub(pattern_items=pattern_items, corpus_item=corpus_item)
    athena = _athena_stub_returning_vins(athena_vins or ["1MRDNA0A4MA000001"]) if athena_vins is not None else None
    res = _mod.Results()
    result = _mod._pick_pattern(res, ddb, "staging", athena=athena)
    return res, result


def test_b1_group_top_rule_required() -> None:
    """b1: pattern_id != pattern_group_id → pre-pattern-pick FAIL (not group-top row)."""
    items = _make_pick_pattern_items(pid="pat-rank2", pgid="pat-rank1")
    corpus = _make_corpus_item()
    res, result = _run_pick_pattern_with(items, corpus, athena_vins=["1MRDNA0A4MA000001"])
    assert result == (None, None, None, None, None), "b1: should fail rule 2"
    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("pre-pattern-pick") == "FAIL", f"b1: expected FAIL; rows={res.rows}"
    # The skip reason should mention the group-top rule
    fail_row = next(r for r in res.rows if r[0] == "pre-pattern-pick")
    assert "group" in fail_row[2].lower(), f"b1: skip reason should mention group; got {fail_row[2]!r}"


def test_b2_unsafe_rules_choice_rejected() -> None:
    """b2: rules-path choice is unsafe (cause_dimension!=supplier_lot) → FAIL."""
    items = _make_pick_pattern_items(code_family="P1AB")
    # Corpus FM with cause_dimension="build_window" → not safe
    corpus = _make_corpus_item(cause_dimension="build_window")
    res, result = _run_pick_pattern_with(items, corpus, athena_vins=["1MRDNA0A4MA000001"])
    assert result == (None, None, None, None, None), "b2: unsafe FM should be rejected"
    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("pre-pattern-pick") == "FAIL", f"b2: expected FAIL; rows={res.rows}"
    # F6c: rejected for the safe rule, not by a later rule (a mutant dropping the
    # cause_dimension rule otherwise still fails at rule 4 and survives).
    fail_row = next(r for r in res.rows if r[0] == "pre-pattern-pick")
    assert "unsafe" in fail_row[2] and "build_window" in fail_row[2], (
        f"b2: skip reason must name the unsafe rules choice; got {fail_row[2]!r}"
    )


def test_b2_brief_unsafe_choice_with_safe_mode_in_pool() -> None:
    """b2-brief: rules choice is unsafe but pool contains a safe FM sorted after it → FAIL.

    The b2-brief mutant accepts any family with a safe FM anywhere in the pool,
    even when the rules-path choice is the unsafe FM.  This test guards that
    property: the pick must be refused when the rules choice is unsafe, even if
    the pool also holds a safe FM.

    Setup: two FMs with the same prefix (P1AB → P1AB0/P1AB1):
      - FM-UNSAFE-01: failure_mode_id sorts first, do_not_drive=True (unsafe)
      - FM-SAFE-01:   failure_mode_id sorts after, supplier_lot + dnd=False + hw_recall

    The rules choice (sorted by failure_mode_id) picks FM-UNSAFE-01.
    The safe pool also contains FM-SAFE-01.
    _pick_pattern must FAIL and the skip reason must name the unsafe choice.
    """
    items = _make_pick_pattern_items(code_family="P1AB")
    # Two corpus FMs in the same prefix tier for P1AB.
    unsafe_corpus = {
        "pk": {"S": "fm#FM-A-UNSAFE-01"},
        "failure_mode_id": {"S": "FM-A-UNSAFE-01"},   # sorts before FM-B-SAFE-01
        "cause_dimension": {"S": "supplier_lot"},
        "component_id": {"S": "test_component"},
        "component_name": {"S": "Test Component"},
        "do_not_drive": {"BOOL": True},              # unsafe
        "park_outside": {"BOOL": False},
        "symptom_codes": {"L": [{"S": "P1AB0"}]},
        "options": {"L": [{"M": {
            "remedy_option_id": {"S": "opt-unsafe-001"},
            "remedy_type": {"S": "hardware_recall"},
            "lead_time_weeks": {"N": "8"},
        }}]},
    }
    safe_corpus = {
        "pk": {"S": "fm#FM-B-SAFE-01"},
        "failure_mode_id": {"S": "FM-B-SAFE-01"},     # sorts after FM-A-UNSAFE-01
        "cause_dimension": {"S": "supplier_lot"},
        "component_id": {"S": "test_component"},
        "component_name": {"S": "Test Component"},
        "do_not_drive": {"BOOL": False},             # safe
        "park_outside": {"BOOL": False},
        "symptom_codes": {"L": [{"S": "P1AB0"}]},
        "options": {"L": [{"M": {
            "remedy_option_id": {"S": "opt-safe-001"},
            "remedy_type": {"S": "hardware_recall"},
            "lead_time_weeks": {"N": "8"},
        }}]},
    }
    # Two-corpus DDB stub
    from unittest.mock import MagicMock  # noqa: PLC0415
    ddb = MagicMock()
    def _scan2(TableName: str, **kw: Any) -> dict:
        if "fault-patterns" in TableName:
            return {"Items": items, "Count": 1}
        if "engineering-corpus" in TableName:
            return {"Items": [unsafe_corpus, safe_corpus], "Count": 2}
        return {"Items": [], "Count": 0}
    ddb.scan.side_effect = _scan2

    res = _mod.Results()
    result = _mod._pick_pattern(res, ddb, "staging", athena=None)
    assert result == (None, None, None, None, None), (
        "b2-brief: unsafe rules choice must cause FAIL even when pool has a safe FM"
    )
    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("pre-pattern-pick") == "FAIL", (
        f"b2-brief: expected FAIL; rows={res.rows}"
    )
    fail_row = next(r for r in res.rows if r[0] == "pre-pattern-pick")
    assert "unsafe" in fail_row[2] and "FM-A-UNSAFE-01" in fail_row[2], (
        f"b2-brief: skip reason must name the unsafe rules choice 'FM-A-UNSAFE-01'; "
        f"got {fail_row[2]!r}"
    )


def test_b3_absent_do_not_drive_treated_as_unsafe() -> None:
    """b3: absent do_not_drive is not treated as False → FAIL (brief §safe rule)."""
    items = _make_pick_pattern_items()
