def test_clock_fix_adp_writer_uses_world_clock() -> None:
    """Clock fix (F6b): world writer's _now uses world clock, not wall clock.

    Verifies the fix by patching the world to a date different from today
    and confirming received_date in the issued row matches the world clock date.
    Proves the suite passes at any wall-clock time.
    """
    import datetime as _dt  # noqa: PLC0415
    from scripts.tests.fi_loop_world.adp_writer import _ADP_ROOT  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415

    if not _ADP_ROOT.exists():
        import pytest as _pytest  # noqa: PLC0415
        _pytest.skip("ADP repo absent")

    # Use a fixed PAST date (not today) to prove clock independence
    FIXED_DATE = _dt.date(2026, 10, 22)

    # Create a world with a start date matching FIXED_DATE
    with FiLoopWorld(
        auto_pump=False,
        start=_dt.datetime(2026, 10, 22, 12, 0, 0, tzinfo=_dt.timezone.utc),
    ) as w:
        # Verify the writer's _now is patched to use the world clock
        now_from_writer = w._adp_writer_mod._now()
        assert now_from_writer.date() == FIXED_DATE, (
            f"Clock fix: writer._now() must return world clock date {FIXED_DATE!r}, "
            f"got {now_from_writer.date()!r}. "
            "If the writer uses the real wall-clock instead of the world clock, "
            "received_date will mismatch when today != {FIXED_DATE}"
        )


# ── F6c: Direct tests for _recheck_investigation_finding (b7 property) ────────
#
# test_b7 replaces _recheck_investigation_finding with a fake, so removing
# step 4 in the real function changes nothing.  These tests call the real
# function directly with Findings built by agents.fi_quality.write.build_
# investigation_finding (serialised to DynamoDB low-level form) and a
# corpus from the live-captured fixture.
#
# Breaks caught:
#   b7  — remove step 4 (quality.options check): test_recheck_option_*_fails
#   b6  — skip the entire recheck call: caught by test_b6 once the callers
#          use these FAIL outcomes (they assert ok=False and no approve)


def _make_recheck_finding_item(
    *,
    fm_id: str = "fm-recheck-safe-001",
    opt_id: str = "opt-recheck-recall-001",
    opt_remedy_type: str = "hardware_recall",
    include_root_cause: bool = True,
    include_options: bool = True,
) -> dict:
    """Build a Finding using the real agent; serialise to DynamoDB low-level form.

    Uses agents.fi_quality.write.build_investigation_finding so the evidence
    structure exactly matches what a live investigation would produce.  The
    item is in the form _read_ddb_item returns (simple-type wrappers unwrapped
    at the top level, nested L/M wrappers intact).
    """
    from boto3.dynamodb.types import TypeSerializer  # noqa: PLC0415
    from agents.fi_quality.write import build_investigation_finding  # noqa: PLC0415

    finding = build_investigation_finding(
        investigation_id="FIND-recheck-test-001",
        pattern_id="pat-recheck-test",
        bundle={
            "pattern": {
                "code_family": "P1AB",
                "pattern_id": "pat-recheck-test",
                "candidate_id": "cand-recheck",
                "p_value": 0.001,
                "method": "cohort",
                "first_detected": "2026-10-01",
                "trend": "stable",
                "vehicles_affected": 2,
                "affected_vins": [
                    {"vin": "1MRDNA0A4MA000001", "model": "Azimuth",
                     "model_year": "2024", "plant": "CGA",
                     "build_month": "2024-01", "component_lot": "SUP-A/LOT-001"},
                ],
            },
            "candidates": [
                {"candidate_id": "cand-recheck", "dimension": "supplier_lot",
                 "value": "SUP-A/LOT-001", "ratio": 0.85, "p_value": 0.001,
                 "rank": 1},
            ],
        },
        root_cause={
            "candidate_id": "cand-recheck",
            "failure_mode_id": fm_id,
            "evidence_refs": ["quality.pattern"],
            "diagnosis_source": "rules",
            "confidence": "high",
        },
        options=[{
            "remedy_option_id": opt_id,
            "remedy_type": opt_remedy_type,
            "recommended": True,
            "parts_cost_per_vehicle_usd": 120.0,
            "labor_hours_per_vehicle": 2.0,
            "lead_time_weeks": 8,
            "over_the_air": False,
            "tradeoffs": "",
        }],
        computed_at="2026-10-22T05:00:00Z",
    )
    # Optionally strip evidence items for edge-case tests
    if not include_root_cause:
        finding["evidence"] = [
            ev for ev in finding.get("evidence", [])
            if ev.get("kind") != "quality.root_cause"
        ]
    if not include_options:
        finding["evidence"] = [
            ev for ev in finding.get("evidence", [])
            if ev.get("kind") != "quality.options"
        ]
    ts = TypeSerializer()
    # TypeSerializer doesn't support float; convert recursively to Decimal.
    from decimal import Decimal as _Dec  # noqa: PLC0415

    def _to_decimal(obj: Any) -> Any:
        if isinstance(obj, float):
            return _Dec(str(obj))
        if isinstance(obj, dict):
            return {k: _to_decimal(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_to_decimal(v) for v in obj]
        return obj

    # Serialise the whole item; _read_ddb_item unwraps only S/N/BOOL/NULL at
    # top level — we replicate that here.
    raw = {k: ts.serialize(_to_decimal(v)) for k, v in finding.items()}
    # Unwrap top-level simple types as _read_ddb_item does
    def _ddb_v(x: Any) -> Any:
        if isinstance(x, dict) and len(x) == 1:
            k2, v2 = next(iter(x.items()))
            if k2 in ("S", "N", "BOOL", "NULL"):
                return v2
        return x
    return {k: _ddb_v(v) for k, v in raw.items()}


def _make_recheck_corpus_item(
    *,
    fm_id: str = "fm-recheck-safe-001",
    opt_id: str = "opt-recheck-recall-001",
    cause_dimension: str = "supplier_lot",
    do_not_drive: bool = False,
    opt_remedy_type: str = "hardware_recall",
    lead_time_weeks: float = 8.0,
) -> dict:
    """Return a safe corpus item in DDB low-level form for _recheck tests."""
    return {
        "pk": {"S": f"fm#{fm_id}"},
        "failure_mode_id": {"S": fm_id},
        "cause_dimension": {"S": cause_dimension},
        "component_id": {"S": "suspension_bushing"},
        "component_name": {"S": "Suspension Bushing"},
        "do_not_drive": {"BOOL": do_not_drive},
        "park_outside": {"BOOL": False},
        "symptom_codes": {"L": [{"S": "P1AB0"}, {"S": "P1AB1"}]},
        "options": {"L": [{"M": {
            "remedy_option_id": {"S": opt_id},
            "remedy_type": {"S": opt_remedy_type},
            "lead_time_weeks": {"N": str(lead_time_weeks)},
        }}]},
    }


def _run_recheck(
    finding_item: dict | None,
    corpus_item: dict | None,
    safe_fms: dict[str, str],
    *,
    finding_exc: Exception | None = None,
    corpus_exc: Exception | None = None,
    stage: str = "staging",
) -> tuple[Any, Any, bool, dict]:
    """Run the real _recheck_investigation_finding with stub DDB objects.

    Returns (chosen_fm_id, opt_id, ok, labels).
    """
    # Build stub ddb_avx (for findings table)
    ddb_avx = MagicMock()
    if finding_exc is not None:
        ddb_avx.get_item.side_effect = finding_exc
    else:
        ddb_avx.get_item.return_value = (
            {"Item": finding_item} if finding_item is not None else {}
        )

    # Build stub ddb_adp (for corpus table)
    ddb_adp = MagicMock()
    if corpus_exc is not None:
        ddb_adp.get_item.side_effect = corpus_exc
    else:
        ddb_adp.get_item.return_value = (
            {"Item": corpus_item} if corpus_item is not None else {}
        )

    finding_id = "FIND-recheck-test-001"
    res = Results()
    chosen_fm, opt_out, ok = _mod._recheck_investigation_finding(
        res, ddb_avx, ddb_adp, stage, finding_id, safe_fms
    )
    labels = {r[0]: r[1] for r in res.rows}
    return chosen_fm, opt_out, ok, labels


_RECHECK_FM_ID = "fm-recheck-safe-001"
_RECHECK_OPT_ID = "opt-recheck-recall-001"
_RECHECK_SAFE_FMS = {_RECHECK_FM_ID: _RECHECK_OPT_ID}


def test_recheck_finding_unreadable_fails() -> None:
    """F6c/b7 direct: step 1 — get_item raises → ok=False, FAIL row."""
    from botocore.exceptions import ClientError  # noqa: PLC0415
    exc = ClientError(
        {"Error": {"Code": "ResourceNotFoundException", "Message": "table not found"}},
        "GetItem",
    )
    _, _, ok, labels = _run_recheck(
        finding_item=None, corpus_item=None,
        safe_fms=_RECHECK_SAFE_FMS,
        finding_exc=exc,
    )
    assert not ok, "recheck: unreadable finding must return ok=False"
    assert labels.get("issue-recheck-finding-read") == "FAIL", (
        f"recheck: unreadable must produce FAIL on issue-recheck-finding-read; rows={labels}"
    )


