def test_b_tier_order_exact_beats_prefix() -> None:
    """F6c: an exact symptom-code match outranks a prefix match, as in the agent.

    Live code families are 4 chars and codes 5, so the captured fixtures never reach
    the exact tier; a mutant preferring the prefix tier survived them.  Here
    FM-A (prefix only) sorts before FM-Z (exact): the rules choice must be FM-Z,
    and the safe pool must be the exact tier only.
    """
    import importlib  # noqa: PLC0415
    fallback_mod = importlib.import_module("agents.fi_quality.fallback")
    fm_prefix = _mod._corpus_fm_to_dict(_make_corpus_item(
        fm_id="FM-A-PREFIX", symptom_codes=["P1AB1"]))
    fm_exact = _mod._corpus_fm_to_dict(_make_corpus_item(
        fm_id="FM-Z-EXACT", symptom_codes=["P1AB0"]))
    fms = [fm_prefix, fm_exact]
    agent = fallback_mod._match_failure_mode(fms, "P1AB0", {})
    script = _mod._rules_match_failure_mode(fms, "P1AB0")
    assert agent["failure_mode_id"] == "FM-Z-EXACT"
    assert script is not None and script["failure_mode_id"] == agent["failure_mode_id"], (
        f"script chose {script and script['failure_mode_id']!r}, agent FM-Z-EXACT"
    )
    assert sorted(_mod._safe_failure_modes_for_pool(fms, "P1AB0")) == ["FM-Z-EXACT"]


def test_b_rules_match_equals_fallback() -> None:
    """Matching-equivalence: _rules_match_failure_mode == fallback._match_failure_mode(fms, cf, {}).

    Tests every code_family in the captured patterns fixture plus edge cases.
    Verifies the script's inline implementation is equivalent to the agent code.
    """
    import importlib  # noqa: PLC0415
    fallback_mod = importlib.import_module("agents.fi_quality.fallback")

    fixture_data = json.loads(
        (_FIXTURES_DIR / "ddb-scan-adp-staging-fault-patterns.json").read_text()
    )
    corpus_data = json.loads(
        (_FIXTURES_DIR / "ddb-scan-adp-staging-engineering-corpus.json").read_text()
    )

    # Convert fixtures to the format both functions expect
    corpus_items = corpus_data["Items"]
    corpus_fms_ddb = [_mod._corpus_fm_to_dict(it) for it in corpus_items]

    # Build the FM list in the shape fallback expects (using plain dicts)
    corpus_fms_agent = corpus_fms_ddb  # same shape after _corpus_fm_to_dict

    # Collect all code_families from the patterns fixture
    def v(x: Any) -> Any:
        if isinstance(x, dict) and len(x) == 1:
            k, inner = next(iter(x.items()))
            return inner
        return x

    code_families = {
        str(v(it.get("code_family", {})))
        for it in fixture_data["Items"]
        if it.get("code_family")
    }

    # Add edge cases: pre-existing ones plus every 5-char code from the captured corpus.
    # The 5-char codes exercise the case where an FM has both a prefix-matching code and
    # an exact-matching code in its symptom_codes list (W1: the old script broke on
    # the first prefix hit and missed the exact code; adding P0AA7/P0AA8 demonstrates
    # the divergence between the old script and the agent).
    code_families |= {
        "",       # empty → None
        "P1AB0",  # 5-char exact for FM-CHG-01/FM-CHG-RECT-01
        "P1AB1",  # 5-char exact for FM-CHG-01
        "U0073",  # 5-char exact for FM-COMM-01/FM-COMM-ANT-01
        "U0074",  # 5-char exact for FM-COMM-01
        "P0AA6",  # 5-char shared by FM-HV-ELD-01 and FM-HV-ISO-01
        "P0AA7",  # 5-char exact for FM-HV-ISO-01 only → diverges between old/new matcher
        "P0AA8",  # 5-char exact for FM-HV-ISO-01 only → diverges
        "P1A0F",  # 5-char shared by FM-HV-ELD-01 and FM-BCP-01
        "P1A0E",  # 5-char exact for FM-BCP-01
        "P1B0F",  # 5-char shared by FM-DU-01 and FM-DU-RES-01 and FM-BCP-SEAL-01
        "P1B0E",  # 5-char exact for FM-DU-01
        "P0A0D",  # 5-char exact for FM-HV-ILK-01
        "P0A0E",  # 5-char exact for FM-HV-ILK-01
        "P0A7F",  # 5-char exact for FM-MCTRL-01
        "P0A7E",  # 5-char exact for FM-MCTRL-01
        "P1B16",  # 5-char shared by FM-THVLV-FLOW-01 and FM-THVLV-01
        "P1B17",  # 5-char exact for FM-THVLV-01
        "XXXX",   # no match
        "P0",     # short prefix
    }

    for cf in sorted(code_families):
        script_result = _mod._rules_match_failure_mode(corpus_fms_ddb, cf)
        agent_result = fallback_mod._match_failure_mode(corpus_fms_agent, cf, {})

        # Both should agree on None vs non-None
        if agent_result is None:
            assert script_result is None, (
                f"code_family={cf!r}: script returned {script_result!r} "
                f"but fallback returned None"
            )
        else:
            assert script_result is not None, (
                f"code_family={cf!r}: script returned None "
                f"but fallback returned {agent_result['failure_mode_id']!r}"
            )
            # Both should choose the same failure_mode_id
            assert script_result["failure_mode_id"] == agent_result["failure_mode_id"], (
                f"code_family={cf!r}: script chose {script_result['failure_mode_id']!r} "
                f"but fallback chose {agent_result['failure_mode_id']!r}"
            )


def test_b_safe_failure_modes_correct_for_captured_corpus() -> None:
    """Verify safe_failure_modes for P1AB and P1B0 against the captured corpus."""
    corpus_data = json.loads(
        (_FIXTURES_DIR / "ddb-scan-adp-staging-engineering-corpus.json").read_text()
    )
    corpus_fms = [_mod._corpus_fm_to_dict(it) for it in corpus_data["Items"]]

    # P1AB matches FM-CHG-01 (supplier_lot, dnd=False, hw_recall OPT-FM-CHG-01-B)
    safe_p1ab = _mod._safe_failure_modes_for_pool(corpus_fms, "P1AB")
    assert "FM-CHG-01" in safe_p1ab, f"P1AB: FM-CHG-01 should be safe; got {safe_p1ab}"
    assert safe_p1ab["FM-CHG-01"] == "OPT-FM-CHG-01-B", (
        f"P1AB: FM-CHG-01 should map to OPT-FM-CHG-01-B; got {safe_p1ab}"
    )

    # P1B0 matches FM-DU-01 (supplier_lot, dnd=False, hw_recall OPT-FM-DU-01-B)
    safe_p1b0 = _mod._safe_failure_modes_for_pool(corpus_fms, "P1B0")
    assert "FM-DU-01" in safe_p1b0, f"P1B0: FM-DU-01 should be safe; got {safe_p1b0}"
    assert safe_p1b0["FM-DU-01"] == "OPT-FM-DU-01-B", (
        f"P1B0: FM-DU-01 should map to OPT-FM-DU-01-B; got {safe_p1b0}"
    )


def test_b_eligible_candidates_from_fixture() -> None:
    """Verify the two eligible candidates (83c333de255473c3 and 1475eb51ef302264) pass all 4 rules."""
    patterns_data = json.loads(
        (_FIXTURES_DIR / "ddb-scan-adp-staging-fault-patterns.json").read_text()
    )
    corpus_data = json.loads(
        (_FIXTURES_DIR / "ddb-scan-adp-staging-engineering-corpus.json").read_text()
    )
    corpus_fms = [_mod._corpus_fm_to_dict(it) for it in corpus_data["Items"]]

    def v(x: Any) -> Any:
        if isinstance(x, dict) and len(x) == 1:
            k, inner = next(iter(x.items()))
            return inner
        return x

    all_patterns = patterns_data["Items"]

    def check_rules_123(pid: str) -> tuple[bool, str]:
        """Check rules 1-3 for a given pattern_id from the fixture."""
        it = next((p for p in all_patterns if v(p.get("pattern_id")) == pid), None)
        if it is None:
            return False, f"pattern {pid!r} not found in fixture"
        cdim = v(it.get("cohort_dimension", {}))
        cval = str(v(it.get("cohort_value", {})))
        pgid = str(v(it.get("pattern_group_id", {})))
        cf = str(v(it.get("code_family", {})))
        # Rule 1
        if cdim != "supplier_lot":
            return False, f"rule 1 fail: cdim={cdim!r}"
        if not _mod._LOT_RE.fullmatch(cval):
            return False, f"rule 1 fail: lot {cval!r} doesn't match regex"
        # Rule 2
        if pid != pgid:
            return False, f"rule 2 fail: pid={pid!r} != pgid={pgid!r}"
        # Rule 3
        fm = _mod._rules_match_failure_mode(corpus_fms, cf)
        if fm is None:
            return False, f"rule 3 fail: no FM match for cf={cf!r}"
        if not _mod._is_safe_fm(fm):
            return False, f"rule 3 fail: FM {fm['failure_mode_id']!r} is unsafe"
        return True, fm["failure_mode_id"]

    ok_83, fm_83 = check_rules_123("83c333de255473c3")
    assert ok_83, f"83c333de255473c3 should pass rules 1-3; got: {fm_83}"
    assert fm_83 == "FM-CHG-01", f"83c333de255473c3 should predict FM-CHG-01; got {fm_83}"

    ok_14, fm_14 = check_rules_123("1475eb51ef302264")
    assert ok_14, f"1475eb51ef302264 should pass rules 1-3; got: {fm_14}"
    assert fm_14 == "FM-DU-01", f"1475eb51ef302264 should predict FM-DU-01; got {fm_14}"

    # Rule 2 fails for 7490144238f0e429 (pgid != pid)
    ok_74, r_74 = check_rules_123("7490144238f0e429")
    assert not ok_74, f"7490144238f0e429 should fail rule 2; got ok={ok_74} r={r_74}"

    # Rule 2 fails for 63d776e8103fe504 (pgid != pid)
    ok_63, r_63 = check_rules_123("63d776e8103fe504")
    assert not ok_63, f"63d776e8103fe504 should fail rule 2; got ok={ok_63} r={r_63}"

    # Rule 3 fails for 8fb69b52c8016b66 (FM-CHG-01 rules choice, but must check rule 4 too)
    ok_8f, fm_8f = check_rules_123("8fb69b52c8016b66")
    assert ok_8f, f"8fb69b52c8016b66 should pass rules 1-3 (FM-CHG-01 is safe); got {fm_8f}"
    # Rule 4 would then fail (DUI lot but FM-CHG-01 needs OBC component)


def _make_full_fixture_athena() -> Any:
    """Fake Athena for test_pick_pattern_full_fixture.

    Returns component-count rows based on lot prefix:
      OBC lots  → onboard_charger VIN count = 2
      DUI lots  → drive_unit_inverter VIN count = 2
      (the cross: OBC lot + drive_unit_inverter, or DUI lot + onboard_charger → 0)

    This reflects the real captured facts (brief §Fix(b) rule 4):
      SUP-B/OBC-L01-B → onboard_charger has managed VINs
      SUP-B/DUI-L05-B → drive_unit_inverter has managed VINs
    """
    stub = MagicMock()
    _query_sql: dict[str, str] = {}

    def _start(QueryString: str = "", **kw: Any) -> dict:
        qeid = f"qe-full-{len(_query_sql):03d}"
        _query_sql[qeid] = QueryString
        return {"QueryExecutionId": qeid}

    stub.start_query_execution.side_effect = _start
    stub.get_query_execution.side_effect = lambda QueryExecutionId, **kw: {
        "QueryExecution": {
            "QueryExecutionId": QueryExecutionId,
            "Status": {"State": "SUCCEEDED"},
        }
    }

    # Map lot → {component_id: count}
    _lot_map = {
        "SUP-B/OBC-L01-B": {"onboard_charger": 2},
        "SUP-B/DUI-L05-B": {"drive_unit_inverter": 2},
        # cross lots: rule 4 fails
        "SUP-B/DUI-L01-B": {"drive_unit_inverter": 2},  # OBC FM, DUI lot → 0 OBC VINs
        "SUP-A/OBC-L05-A": {"onboard_charger": 2},      # DU FM, OBC lot → 0 DU VINs
        "SUP-B/OBC-L05-B": {"onboard_charger": 2},      # DU FM, OBC lot → 0 DU VINs
    }

    def _get_results(QueryExecutionId: str = "", **kw: Any) -> dict:
        sql = _query_sql.get(QueryExecutionId, "")
        # Extract lot from WHERE clause
        rows = [{"Data": [{"VarCharValue": "component_id"}, {"VarCharValue": "cnt"}]}]
        for lot, comp_map in _lot_map.items():
            if lot in sql:
                for comp_id, cnt in comp_map.items():
                    rows.append({"Data": [
                        {"VarCharValue": comp_id},
                        {"VarCharValue": str(cnt)},
                    ]})
                break
        return {"ResultSet": {"Rows": rows}}

    stub.get_query_results.side_effect = _get_results
    return stub


def test_pick_pattern_full_fixture() -> None:
    """W3: _pick_pattern over the full captured fixtures with a fake Athena.

    Asserts:
    - The pick is 1475eb51ef302264 (P1B0, SUP-B/DUI-L05-B → FM-DU-01 / OPT-FM-DU-01-B)
    - With 1475eb51ef302264 removed, pick is 83c333de255473c3
    - With both removed, FAIL names component skips for 52f0fda11e057ea8,
      8fb69b52c8016b66, fe51ce960ca603c4, and group-top skips for
      7490144238f0e429 and 63d776e8103fe504
    - A supplier_lot row with cohort_value failing _LOT_RE gets a skip reason
      and the Athena stub is never called for it (S8 fix)

    W3 fix: replaces test_b_eligible_candidates_from_fixture (which never called
    _pick_pattern and never applied rule 4 with a fake Athena).
    """
    patterns_data = json.loads(
        (_FIXTURES_DIR / "ddb-scan-adp-staging-fault-patterns.json").read_text()
    )
    corpus_data = json.loads(
        (_FIXTURES_DIR / "ddb-scan-adp-staging-engineering-corpus.json").read_text()
    )

    def _build_ddb_stub(
        pattern_extra: list[dict] | None = None,
        exclude_pids: set[str] | None = None,
    ) -> Any:
        """Build a DDB stub serving the full fixture data.

        *pattern_extra*: additional pattern items to inject (e.g. invalid-lot row).
        *exclude_pids*: pattern_ids to exclude (simulates removed candidates).
        """
        def v(x: Any) -> Any:
            if isinstance(x, dict) and len(x) == 1:
                return list(x.values())[0]
            return x

        patterns = patterns_data["Items"]
        if exclude_pids:
            patterns = [it for it in patterns if v(it.get("pattern_id", {})) not in exclude_pids]
        if pattern_extra:
            patterns = list(patterns) + pattern_extra

        stub = MagicMock()

        def _scan(TableName: str, **kw: Any) -> dict:
            if "fault-patterns" in TableName:
                return {"Items": patterns, "Count": len(patterns)}
            if "engineering-corpus" in TableName:
                return {"Items": corpus_data["Items"], "Count": len(corpus_data["Items"])}
            return {"Items": [], "Count": 0}

        stub.scan.side_effect = _scan
        stub.get_item.return_value = {"Item": None}
        return stub

    # ── Pass 1: all patterns — expect pick 1475eb51ef302264 (sorts before 83c333) ──
    athena = _make_full_fixture_athena()
    # Inject one invalid-lot row to verify S8 (skip reason, no Athena call)
    invalid_lot_item = {
        "pattern_id":       {"S": "invalid-lot-row-test"},
        "pattern_group_id": {"S": "invalid-lot-row-test"},
        "candidate_rank":   {"N": "1"},
        "code_family":      {"S": "P1AB"},
        "cohort_dimension": {"S": "supplier_lot"},
        "cohort_value":     {"S": "bad::lot"},  # fails _LOT_RE
        "affected_vins":    {"L": [{"S": "1MRDNA0A4MA000001"}]},
    }
    ddb = _build_ddb_stub(pattern_extra=[invalid_lot_item])
    res = _mod.Results()
    row, pid, cval, fm_id, safe_fms = _mod._pick_pattern(res, ddb, "staging", athena=athena)
    assert pid == "1475eb51ef302264", (
        f"W3: first pick must be 1475eb51ef302264; got {pid!r}; rows={res.rows}"
    )
    assert fm_id == "FM-DU-01", (
        f"W3: picked FM must be FM-DU-01; got {fm_id!r}"
    )
    assert safe_fms.get("FM-DU-01") == "OPT-FM-DU-01-B", (
        f"W3: safe_fms must carry FM-DU-01→OPT-FM-DU-01-B; got {safe_fms!r}"
    )
    # Verify S8: invalid-lot row has a skip reason; Athena not called for it
    # (if Athena were called for it, it would have raised or returned empty counts
    # since "bad::lot" is not in the map)
    # We verify directly that "bad::lot" was not passed to Athena:
    athena_sql_calls = [
        call[1]["QueryString"] if "QueryString" in call[1] else call[0][0]
        for call in athena.start_query_execution.call_args_list
        if athena.start_query_execution.call_args_list
    ]
    assert all("bad::lot" not in sql for sql in athena_sql_calls), (
        f"W3/S8: Athena must NOT be called for invalid-lot row; got calls: {athena_sql_calls}"
    )

    # ── Pass 2: remove 1475eb51ef302264 → expect 83c333de255473c3 ──
    athena2 = _make_full_fixture_athena()
    ddb2 = _build_ddb_stub(exclude_pids={"1475eb51ef302264"})
    res2 = _mod.Results()
    _, pid2, _, fm_id2, _ = _mod._pick_pattern(res2, ddb2, "staging", athena=athena2)
    assert pid2 == "83c333de255473c3", (
        f"W3: second pick (after removing 1475eb51ef302264) must be 83c333de255473c3; "
        f"got {pid2!r}; rows={res2.rows}"
    )
    assert fm_id2 == "FM-CHG-01", (
        f"W3: second pick FM must be FM-CHG-01; got {fm_id2!r}"
    )

    # ── Pass 3: remove both eligible → expect FAIL with per-row skip reasons ──
    athena3 = _make_full_fixture_athena()
    ddb3 = _build_ddb_stub(exclude_pids={"1475eb51ef302264", "83c333de255473c3"})
    res3 = _mod.Results()
    row3, pid3, _, _, _ = _mod._pick_pattern(res3, ddb3, "staging", athena=athena3)
    assert row3 is None and pid3 is None, (
        f"W3: with both eligible removed, pick must be None; got pid={pid3!r}"
    )
    fail_row3 = next((r for r in res3.rows if r[0] == "pre-pattern-pick"), None)
    assert fail_row3 is not None and fail_row3[1] == "FAIL", (
        f"W3: with both eligible removed, must FAIL; rows={res3.rows}"
    )
    fail_txt = fail_row3[2]
    # Component-skip patterns
    for comp_skip_pid in ("52f0fda11e057ea8", "8fb69b52c8016b66", "fe51ce960ca603c4"):
        assert comp_skip_pid in fail_txt, (
            f"W3: FAIL must name {comp_skip_pid!r} component skip; got {fail_txt!r}"
        )
    # Group-top-skip patterns (rule 2)
    for grp_skip_pid in ("7490144238f0e429", "63d776e8103fe504"):
        assert grp_skip_pid in fail_txt, (
            f"W3: FAIL must name {grp_skip_pid!r} group-top skip; got {fail_txt!r}"
        )

    # S8: the invalid-lot row (from Pass 1) is not in this ddb3 stub (excluded neither),
    # but the invalid-lot row was injected only in Pass 1 to verify no Athena call.
    # For Pass 3, the FAIL message should NOT include "bad::lot" because the invalid-lot
    # row was only injected in Pass 1's ddb stub, not ddb3.
    # However, to test S8 skip reason, we verify it separately in Pass 1:
    # Pass 1's invalid-lot row should appear in the full pick's skip reasons.
    # Since pick succeeded in Pass 1 (result != None), the skip reasons are not in the FAIL.
    # To test S8 explicitly, we run a dedicated no-picks scenario with only the invalid row.
    ddb_s8 = _build_ddb_stub(
        pattern_extra=[invalid_lot_item],
        exclude_pids={p for it in patterns_data["Items"]
                      if (p := (lambda x: x if isinstance(x, str) else list(x.values())[0])(it.get("pattern_id", {})))},
    )
    athena_s8 = _make_full_fixture_athena()
    res_s8 = _mod.Results()
    row_s8, pid_s8, _, _, _ = _mod._pick_pattern(res_s8, ddb_s8, "staging", athena=athena_s8)
    assert row_s8 is None, "S8: only the invalid-lot row should yield no pick"
    fail_s8 = next((r for r in res_s8.rows if r[0] == "pre-pattern-pick"), None)
    assert fail_s8 is not None and fail_s8[1] == "FAIL", f"S8: must FAIL; rows={res_s8.rows}"
    assert "bad::lot" in fail_s8[2] and ("lot regex" in fail_s8[2] or "does not match" in fail_s8[2]), (
        f"S8: FAIL must name invalid-lot row 'invalid-lot-row-test' with skip reason; "
        f"got {fail_s8[2]!r}"
    )
    # Athena must not have been called for bad::lot
    s8_athena_calls = [
        call[1]["QueryString"] if "QueryString" in call[1] else call[0][0]
        for call in athena_s8.start_query_execution.call_args_list
    ]
    assert all("bad::lot" not in sql for sql in s8_athena_calls), (
        f"S8: Athena must NOT be called for invalid-lot row; calls: {s8_athena_calls}"
    )


