# ── IH1-IH2: HTTP bytes-captured tests ───────────────────────────────────────


import contextlib
import http.server
import threading
from pathlib import Path as _Path


class _CapturingHandler(http.server.BaseHTTPRequestHandler):
    """Records raw request bytes into ``captured`` list; responds 200 {}."""

    captured: list[bytes] = []

    def do_GET(self) -> None:
        self._capture_and_respond()

    def do_POST(self) -> None:
        self._capture_and_respond()

    def _capture_and_respond(self) -> None:
        length = int(self.headers.get("Content-Length", 0))
        body = self.rfile.read(length) if length else b""
        raw = (
            f"{self.command} {self.path} HTTP/1.1\r\n"
            + str(self.headers)
            + (body.decode("latin-1") if body else "")
        ).encode("latin-1")
        self.__class__.captured.append(raw)
        resp = b'{"ok": true}'
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(resp)))
        self.end_headers()
        self.wfile.write(resp)

    def log_message(self, fmt: str, *args: Any) -> None:
        pass  # suppress log output


@contextlib.contextmanager
def _capture_http_server():
    """Start a capturing HTTP server; yield its base URL; stop on exit."""
    _CapturingHandler.captured = []
    server = http.server.HTTPServer(("127.0.0.1", 0), _CapturingHandler)
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    port = server.server_address[1]
    try:
        yield f"http://127.0.0.1:{port}/", _CapturingHandler.captured
    finally:
        server.shutdown()
        thread.join(timeout=2)


def test_ih1_http_get_sends_authorization_header() -> None:
    """IH1: _http GET sends Authorization: Bearer header (bytes-captured)."""
    with _capture_http_server() as (url, captured):
        _mod._http(url, "GET", "investigations/abc-123", "my-id-token")

    assert captured, "no request captured"
    raw = captured[0].decode("latin-1")
    assert "Authorization: Bearer my-id-token" in raw, (
        f"Authorization header not found in: {raw!r}"
    )
    assert "GET /investigations/abc-123" in raw, (
        f"path not found in: {raw!r}"
    )


def test_ih2_http_post_sends_content_type_and_body() -> None:
    """IH2: _http POST sends Content-Type: application/json + JSON body (bytes-captured)."""
    with _capture_http_server() as (url, captured):
        _mod._http(
            url,
            "POST",
            "investigations",
            "eng-token",
            {"pattern_id": "pat-supplier-lot-001"},
        )

    assert captured, "no request captured"
    raw = captured[0].decode("latin-1")
    assert "Content-Type: application/json" in raw, (
        f"Content-Type not found in: {raw!r}"
    )
    assert '"pattern_id"' in raw and '"pat-supplier-lot-001"' in raw, (
        f"JSON body not found in: {raw!r}"
    )
    assert "Authorization: Bearer eng-token" in raw, (
        f"Authorization not found in: {raw!r}"
    )


def test_ih1_http_get_pinned_403_forbidden() -> None:
    """IH1b: _http parses 403 {"error": "Forbidden"} without raising (brief §HTTP)."""
    class _403Handler(http.server.BaseHTTPRequestHandler):
        def do_GET(self) -> None:
            resp = b'{"error": "Forbidden"}'
            self.send_response(403)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(resp)))
            self.end_headers()
            self.wfile.write(resp)

        def log_message(self, fmt: str, *args: Any) -> None:
            pass

    server = http.server.HTTPServer(("127.0.0.1", 0), _403Handler)
    t = threading.Thread(target=server.serve_forever, daemon=True)
    t.start()
    port = server.server_address[1]
    try:
        status, body = _mod._http(
            f"http://127.0.0.1:{port}/", "GET", "investigations/x", "Bearer tok"
        )
    finally:
        server.shutdown()
        t.join(timeout=2)

    assert status == 403, f"expected 403, got {status}"
    assert body.get("error") == "Forbidden", (
        f"expected pinned 403 body {{'error': 'Forbidden'}}; got {body!r}"
    )


