# ── W10: AST-derived lazy-import test (m32) ───────────────────────────────────

def test_i2_ast_derived_lazy_imports_importable(tmp_path: Path) -> None:
    """W10/m32: every lazy import in the script can be imported from a temp cwd.

    Derives the set of lazy imports from the script's AST (function-body ``import``
    statements) rather than from the stale _LAZY_IMPORTS constant.  With m32,
    ``import urllib.requestz`` is injected; this test catches it because
    ``python3 -c "import urllib.requestz"`` exits non-zero.

    Does NOT use --stage prod (which exits before any lazy import runs).  Instead
    it parses the AST directly, giving exact coverage of what the script will import.
    """
    import ast as _ast  # noqa: PLC0415

    source = _SCRIPT.read_text()
    tree = _ast.parse(source)

    # Collect module names from ``import X`` and ``from X import Y`` inside
    # function bodies (lazy imports per the brief §Imports pattern).
    lazy_modules: set[str] = set()
    for node in _ast.walk(tree):
        if not isinstance(node, (_ast.FunctionDef, _ast.AsyncFunctionDef)):
            continue
        for child in _ast.walk(node):
            if isinstance(child, _ast.Import):
                for alias in child.names:
                    lazy_modules.add(alias.name)
            elif isinstance(child, _ast.ImportFrom):
                if child.module:
                    lazy_modules.add(child.module)

    assert lazy_modules, "AST found no lazy imports in any function body"

    env = {k: v for k, v in os.environ.items() if k not in ("PYTHONPATH",)}
    failures: list[str] = []
    for mod in sorted(lazy_modules):
        result = subprocess.run(
            [sys.executable, "-I", "-c", f"import {mod}"],
            capture_output=True,
            cwd=str(tmp_path),
            env=env,
        )
        if result.returncode != 0:
            failures.append(
                f"{mod}: exit {result.returncode} "
                f"stderr={result.stderr[:100]!r}"
            )

    assert not failures, (
        f"W10/m32: {len(failures)} lazy import(s) failed from a PYTHONPATH-free cwd:\n"
        + "\n".join(failures)
    )


# ── W10: guard-allowlist completeness (derived from _PART_ALLOWLISTS) ──────────

def _guard_allows(part: str, svc: str, op: str) -> bool:
    """Return True iff (svc, op) does NOT raise GuardViolation on *part*'s session.

    Fires the botocore ``before-parameter-build`` hook directly (no real network
    call needed), mimicking what the guard does when a client makes a request.
    """
    allowed = _mod._PART_ALLOWLISTS.get(part, frozenset())
    bc = _mod._make_guarded_bcsession(allowed)
    # Build a minimal model mock that the guard hook checks.
    model = MagicMock()
    model.service_model.service_name = svc
    model.name = op
    try:
        bc.get_component("event_emitter").emit(
            f"before-parameter-build.{svc}.{op}",
            params={}, model=model, context={},
        )
        return True
    except _mod.GuardViolation:
        return False


# Derive the test parameters from the script's _PART_ALLOWLISTS, not a hand list.
# This parametrize automatically covers any new ops added to the allowlist.
@pytest.mark.parametrize(
    "part_name,svc,op",
    sorted(
        (part, svc, op)
        for part, ops in _mod._PART_ALLOWLISTS.items()
        for (svc, op) in ops
    ),
)
def test_w10_allowlisted_op_passes_guard(part_name: str, svc: str, op: str) -> None:
    """W10: every op in every part's allowlist passes the guard for that part.

    Derived from _mod._PART_ALLOWLISTS — no hand list.  When a new op is added
    to an allowlist, this test automatically covers it without test updates.
    """
    assert _guard_allows(part_name, svc, op), (
        f"W10: ({svc}, {op}) raised GuardViolation in part {part_name!r}; "
        f"op is in _PART_ALLOWLISTS[{part_name!r}] but the guard refuses it"
    )


@pytest.mark.parametrize(
    "part_name,svc,op",
    sorted(
        (part, svc, op)
        for part, ops in _mod._PART_ALLOWLISTS.items()
        for (svc2, op2) in ops
        # Pick one op that is NOT in the allowlist for this part to verify refusal.
        # Use a deterministic "not in this part" combination for each part.
        for (svc, op) in [("iam", "CreateRole")]  # iam.CreateRole is never in any part's allowlist
        if (svc, op) not in ops
    )[:1],  # just one refusal test; all parts use the same refused op
)
def test_w10_non_allowlisted_op_refused_by_guard(part_name: str, svc: str, op: str) -> None:
    """W10: an op not in a part's allowlist raises GuardViolation."""
    assert not _guard_allows(part_name, svc, op), (
        f"W10: ({svc}, {op}) should raise GuardViolation in part {part_name!r}; "
        f"op is NOT in _PART_ALLOWLISTS[{part_name!r}]"
    )


