import datetime as _dt  # noqa: PLC0415


def _safe_issue_time() -> "_dt.datetime":
    """Return 10:00Z — safe from both maintenance window and cron schedules."""
    return _dt.datetime(2026, 10, 22, 10, 0, 0, tzinfo=_dt.timezone.utc)


@_SKIP_WORLD_E2E
def test_ie1_main_pre_then_issue_through_world(tmp_path: "Path") -> None:
    """IE1: drive main() --part pre then --part issue through FiLoopWorld.

    Uses FiLoopWorld(auto_pump=True) so POST /investigations synchronously
    processes the investigation via pump_investigation() (brief §Fakes from world).
    Verifies all checks PASS, manifest has all ids, DDB issued row and S3 object exist.
    """
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415

    def _manifest_path_hook(rid: str) -> str:  # noqa: ARG001
        # Both pre and issue share the same manifest file regardless of run_id.
        # K1: pre now mints its own run_id; issue uses --run-id to find the manifest.
        # We share a fixed path so the test can write then read without knowing the id.
        return str(tmp_path / "shared-manifest.json")

    # Pattern and VINs seeded into the world
    PATTERN_ID = "pat-supp-bushing-001"
    VIN_LIST = ["1MRDNA0A4MA000001", "1MRDNA0A5MA000002"]
    FM_ID = "fm-susp-bushing-001"
    COHORT_VALUE = "SUP-AXLE/LOT-2024-Q3"

    with FiLoopWorld(
        auto_pump=True,
        # F6b clock fix: pin world start to 2026-10-22 so the ADP writer's
        # received_date matches _utc_now (patched to _safe_issue_time = 2026-10-22T10:00Z).
        start=__import__("datetime").datetime(2026, 10, 22, 12, 0, 0,
                                               tzinfo=__import__("datetime").timezone.utc),
    ) as w:
        # Seed the pattern and corpus
        w.seed_pattern(
            pattern_id=PATTERN_ID,
            vin_list=VIN_LIST,
            failure_mode_id=FM_ID,
            cohort_dimension="supplier_lot",
            cohort_value=COHORT_VALUE,
            component_name="Front Axle Bushing",
        )
        # Remove the monitor option so FiQualityBedrock picks only hardware_recall.
        # seed_fi_quality_tables always inserts both; delete monitor so allowed[0]
        # is opt-recall-001 (alphabetically, 'recall' > 'monitor').
        w.athena.con.execute(
            "DELETE FROM adp_staging_engineering.engineering_remedy_options "
            "WHERE remedy_option_id = 'opt-monitor-001'"
        )

        # Patch the pool + client_id lookup: provide world's cognito stubs
        pool_id = w.pool.pool_id
        client_id = w.pool.client_id

        # Also patch the DLQ check to pass (no real SQS DLQ in the world)
        def _client_with_world(service: str, region: str, **_kw: Any) -> Any:
            """Route boto3 calls through the world's moto / router."""
            import boto3  # noqa: PLC0415
            from botocore.config import Config  # noqa: PLC0415

            cfg = Config(connect_timeout=5, retries={"total_max_attempts": 1})
            return boto3.client(service, region_name=region, config=cfg)

        def _resolve_pool_id_stub(idp: Any) -> str:
            return pool_id

        def _password_client_stub(idp: Any, pid: str) -> str:
            return client_id

        # Patch investigation POST to inject a 9.3-clean code zip
        good_zip = _make_zip_with_9_3_code()

        # Schedule stub returns safe times
        def _schedule_guard_stub(
            scheduler: Any,
            names: Any,
            stage: str,
            now: Any,
        ) -> "str | None":
            return None  # no schedule conflicts in world test

        # ESM stub: Enabled
        def _check_esm_stub(
            res: Any, lam: Any, stage: str, region: str
        ) -> bool:
            check(res, "pre-esm-enabled", True, "ESM=Enabled (world stub)")
            return True

        def _check_tier2_code_stub(res: Any, lam: Any, fn_name: str) -> bool:
            check(res, "pre-tier2-code-readers", True, "readers.py ok (stub)")
            check(res, "pre-tier2-code-sql", True, "select_recalls.sql ok (stub)")
            return True

        # Glue stub: table exists + view has issued
