        # CFN stub: return world's AVX API URL
        avx_url = w.avx_url

        def _get_avx_api_url_stub(cfn: Any, stage: str) -> str:
            return avx_url

        # S3 HeadObject stub (world uses moto S3; the issued-recall object will
        # be in the world's lake bucket via the ADP writer)
        def _check_s3_issued_recall_stub(
            res: Any, s3: Any, stage: str, account: str, campaign_id: str
        ) -> bool:
            # Check the world's moto S3 for the object
            import boto3 as _b3  # noqa: PLC0415
            from scripts.tests.fi_rw_world.world import LAKE_BUCKET  # noqa: PLC0415
            s3c = _b3.client("s3", region_name="us-east-1")
            key = f"curated/engineering/recall_campaigns_issued/{campaign_id}.json"
            try:
                s3c.head_object(Bucket=LAKE_BUCKET, Key=key)
                check(res, "issue-s3-key", True, f"{key} exists in world bucket")
                # moto S3 won't have bucket-level KMS; report SSE as informational
                check(res, "issue-s3-sse-kms", True,
                      "SSE-KMS check skipped in world test (moto S3 has no bucket encryption)")
                return True
            except Exception as exc:  # noqa: BLE001
                check(res, "issue-s3-key", False,
                      on_fail=f"HeadObject failed: {type(exc).__name__}: {exc}")
                return False

        res_holder: list[Results] = []
        real_results_class = _mod.Results

        class _CapResults(real_results_class):  # type: ignore[misc,valid-type]
            def __init__(self) -> None:
                super().__init__()
                res_holder.append(self)

        # ── Part pre ──────────────────────────────────────────────────────────
        with (
            patch.object(_mod, "_download_code_zip", lambda url: good_zip),
            patch.object(_mod, "_utc_now", _safe_issue_time),
            patch.object(_mod, "_check_esm_enabled", _check_esm_stub),
            patch.object(_mod, "_check_tier2_code", _check_tier2_code_stub),
            patch.object(_mod, "_check_recall_table_exists", _check_recall_table_stub),
            patch.object(_mod, "_check_view_sql_unions_issued", _check_view_sql_stub),
            patch.object(_mod, "_check_dlq_empty", _check_dlq_stub),
            patch.object(_mod, "_check_no_open_livetest", _check_no_open_livetest_stub),
            patch.object(_mod, "_compute_expected_vins", _compute_expected_vins_stub),
            patch.object(_mod, "_schedule_guard", _schedule_guard_stub),
            patch.object(_mod, "_manifest_path", _manifest_path_hook),
            patch.object(_mod, "Results", _CapResults),
        ):
            # W11 fix: set _SESSION to guarded world session before calling main().
            # _part_pre calls _init_session("pre") which is idempotent; since
            # _SESSION is already set, it uses the guarded session and the
            # allowlists are enforced throughout the part run.
            _mod._SESSION = w.make_guarded_session("pre")
            main(["--stage", "staging", "--part", "pre"])

        assert res_holder, "Results not instantiated during pre"
        pre_res = res_holder[-1]
        pre_fails = [(r[0], r[2]) for r in pre_res.rows if r[1] == "FAIL"]
        assert not pre_fails, f"pre FAIL rows: {pre_fails}"

        # Read manifest to verify pattern_id was stored
        import json as _js  # noqa: PLC0415
        mf = _js.loads((_Path(tmp_path) / "shared-manifest.json").read_text())
        assert mf.get("pattern_id") == PATTERN_ID, (
            f"manifest pattern_id={mf.get('pattern_id')!r}, expected {PATTERN_ID!r}"
        )

        # ── Part issue ────────────────────────────────────────────────────────
        # K1: issue now requires --run-id; use the run_id from the pre manifest.
        pre_mf = _js.loads((Path(tmp_path) / "shared-manifest.json").read_text())
        pre_run_id = pre_mf.get("run_id", "fi-loop-20261022T100000-deadbeef")
        with (
            patch.object(_mod, "_download_code_zip", lambda url: good_zip),
            patch.object(_mod, "_utc_now", _safe_issue_time),
            patch.object(_mod, "_check_esm_enabled", _check_esm_stub),
            patch.object(_mod, "_check_tier2_code", _check_tier2_code_stub),
            patch.object(_mod, "_check_recall_table_exists", _check_recall_table_stub),
            patch.object(_mod, "_check_view_sql_unions_issued", _check_view_sql_stub),
            patch.object(_mod, "_check_dlq_empty", _check_dlq_stub),
            patch.object(_mod, "_check_no_open_livetest", _check_no_open_livetest_stub),
            patch.object(_mod, "_compute_expected_vins", _compute_expected_vins_stub),
            patch.object(_mod, "_schedule_guard", _schedule_guard_stub),
            patch.object(_mod, "_get_avx_api_url", _get_avx_api_url_stub),
            patch.object(_mod, "_resolve_pool_id", _resolve_pool_id_stub),
            patch.object(_mod, "_password_client", _password_client_stub),
            patch.object(_mod, "_check_s3_issued_recall", _check_s3_issued_recall_stub),
            patch.object(_mod, "_manifest_path", _manifest_path_hook),
            patch.object(_mod, "_POLL_SLEEP_S", 0.0),  # no sleep in tests
            patch.object(_mod, "Results", _CapResults),
        ):
            # W11 fix: reset _SESSION so _part_issue can use its own allowlist
            # (issue allowlist is a superset of pre's, so the session must be
            # re-initialized to include the issue-specific ops like AdminCreateUser).
            _mod._SESSION = None
            _mod._SESSION = w.make_guarded_session("issue")
            main(["--stage", "staging", "--part", "issue", "--allow-writes",
                  "--run-id", pre_run_id])

        assert len(res_holder) >= 2, "Results not instantiated during issue"
        issue_res = res_holder[-1]
        issue_fails = [(r[0], r[2]) for r in issue_res.rows if r[1] == "FAIL"]
        issue_skips = [(r[0], r[2]) for r in issue_res.rows if r[1] == "SKIP"]
        assert not issue_fails, f"issue FAIL rows: {issue_fails}"
        assert not issue_skips, f"issue SKIP rows (unexpected): {issue_skips}"

        # Verify manifest has all expected ids
        mf2 = _js.loads((_Path(tmp_path) / "shared-manifest.json").read_text())
        records = mf2.get("records", {})
        assert records.get("investigation_id"), (
            f"manifest missing investigation_id: {records!r}"
        )
        assert records.get("campaign_id"), (
            f"manifest missing campaign_id: {records!r}"
        )
        assert records.get("thread_id"), (
            f"manifest missing thread_id: {records!r}"
        )
        assert records.get("issue_finding_id"), (
            f"manifest missing issue_finding_id: {records!r}"
        )

        # Verify DDB issued row
        import boto3 as _boto3  # noqa: PLC0415
        from scripts.tests.fi_loop_world.adp_writer import STAGE as _ADP_STAGE  # noqa: PLC0415
        campaign_id = records["campaign_id"]
