# ── W6: issue e2e without _check_s3_issued_recall / _password_client stubs ───
#
# Brief K5: keep one stub-free e2e per part so the allowlist guard fires for
# helpers that receive clients as parameters.
# This test drives _part_issue through the world using make_guarded_session
# WITHOUT stubbing _check_s3_issued_recall or _password_client.  If a mutant
# removes s3:HeadObject from issue's allowlist (mutant a3), _check_s3_issued_recall
# calls s3.head_object() through the _GuardedIdpProxy → GuardViolation → test FAIL.
# (For cognito-idp, _password_client calls idp.list_user_pool_clients() through
# the _GuardedIdpProxy added by the W6 world fix.)
#
# This complements the static test (which catches a3/a5 statically) with a
# runtime guard that fires even if the static analysis missed something.


def test_w6_issue_e2e_guard_fires_for_helper_clients(tmp_path: "Path") -> None:
    """W6/K5: issue e2e with no _check_s3_issued_recall / _password_client stubs.

    Runs --part issue through the world with make_guarded_session("issue").
    Does NOT stub _check_s3_issued_recall (which calls s3.head_object) or
    _password_client (which calls idp.list_user_pool_clients +
    idp.describe_user_pool_client).  Both calls go through the guarded session;
    removing either op from the allowlist would raise GuardViolation here.

    Catches mutants:
    - a3: issue's s3:HeadObject removed → _check_s3_issued_recall raises GuardViolation
    - (complements a5's guard for ground's ListUserPoolClients via test_gg9)
    """
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415

    PATTERN_ID = "pat-supp-bushing-w6"
    VIN_LIST = ["1MRDNA0A4MA000001", "1MRDNA0A5MA000002"]
    FM_ID = "fm-susp-bushing-w6"
    COHORT_VALUE = "SUP-AXLE/LOT-2024-Q3"

    def _manifest_path_hook(rid: str) -> str:  # noqa: ARG001
        return str(tmp_path / "shared-manifest.json")

    with FiLoopWorld(
        auto_pump=True,
        # F6b clock fix: pin world start to 2026-10-22 so received_date matches
        # the patched _utc_now (2026-10-22T10:00Z).
        start=__import__("datetime").datetime(2026, 10, 22, 12, 0, 0,
                                               tzinfo=__import__("datetime").timezone.utc),
    ) as w:
        w.seed_pattern(
            pattern_id=PATTERN_ID,
            vin_list=VIN_LIST,
            failure_mode_id=FM_ID,
            cohort_dimension="supplier_lot",
            cohort_value=COHORT_VALUE,
            component_name="Front Axle Bushing",
        )
        # Remove monitor option so only hardware_recall remains
        w.athena.con.execute(
            "DELETE FROM adp_staging_engineering.engineering_remedy_options "
            "WHERE remedy_option_id = 'opt-monitor-001'"
        )

        pool_id = w.pool.pool_id

        def _resolve_pool_id_stub(idp: Any) -> str:
            return pool_id

        def _schedule_guard_stub(scheduler: Any, names: Any, stage: str, now: Any) -> "str | None":
            return None

        def _check_esm_stub(res: Any, lam: Any, stage: str, region: str) -> bool:
            check(res, "pre-esm-enabled", True, "ESM=Enabled (world stub)")
            return True

        def _check_tier2_code_stub(res: Any, lam: Any, fn_name: str) -> bool:
            check(res, "pre-tier2-code-readers", True, "readers ok (stub)")
            check(res, "pre-tier2-code-sql", True, "sql ok (stub)")
            return True

        def _check_recall_table_stub(res: Any, glue: Any, stage: str) -> bool:
            check(res, "pre-recall-table", True, "recall table exists (stub)")
            return True

        def _check_view_sql_stub(res: Any, glue: Any, stage: str) -> bool:
            check(res, "pre-view-sql", True, "view sql ok (stub)")
            return True

        def _check_dlq_stub(res: Any, sqs: Any, stage: str) -> bool:
            check(res, "pre-dlq-empty", True, "DLQ empty (stub)")
            return True

        def _check_no_open_livetest_stub(res: Any, idp: Any, stage: str) -> bool:
            check(res, "pre-no-open-livetest", True, "no livetest users (stub)")
            return True

        def _compute_expected_vins_stub(
            res: Any, athena: Any, stage: str, cause_value: str, **_kw: Any
        ) -> list[str]:
            check(res, "pre-expected-vins", True,
                  f"expected VINs ({len(VIN_LIST)} VINs, stub)")
            return list(VIN_LIST)

        def _get_avx_api_url_stub(cfn: Any, stage: str) -> str:
            return w.avx_url

        good_zip = _make_zip_with_9_3_code()

        res_holder: list[Results] = []
        real_results_class = _mod.Results

        class _CapResults(real_results_class):  # type: ignore[misc,valid-type]
            def __init__(self) -> None:
                super().__init__()
                res_holder.append(self)

        # ── Part pre ──────────────────────────────────────────────────────────
        _mod._SESSION = None
        _mod._SESSION = w.make_guarded_session("pre")
        with (
            patch.object(_mod, "_utc_now",
                         lambda: __import__("datetime").datetime(
                             2026, 10, 22, 10, 0, tzinfo=__import__("datetime").timezone.utc)),
            patch.object(_mod, "_resolve_pool_id", _resolve_pool_id_stub),
            patch.object(_mod, "_schedule_guard", _schedule_guard_stub),
            patch.object(_mod, "_check_esm_enabled", _check_esm_stub),
            patch.object(_mod, "_check_tier2_code", _check_tier2_code_stub),
            patch.object(_mod, "_check_recall_table_exists", _check_recall_table_stub),
            patch.object(_mod, "_check_view_sql_unions_issued", _check_view_sql_stub),
            patch.object(_mod, "_check_dlq_empty", _check_dlq_stub),
            patch.object(_mod, "_check_no_open_livetest", _check_no_open_livetest_stub),
            patch.object(_mod, "_compute_expected_vins", _compute_expected_vins_stub),
            patch.object(_mod, "_get_avx_api_url", _get_avx_api_url_stub),
            patch.object(_mod, "_download_code_zip", lambda url: good_zip),
            patch.object(_mod, "_manifest_path", _manifest_path_hook),
            patch.object(_mod, "Results", _CapResults),
        ):
            main(["--stage", "staging", "--run-id", "w6-guard-ie1-00001",
                  "--part", "pre",
                  "--allow-writes", "--allow-managed-writes"])

        import json as _jj_pre  # noqa: PLC0415
        pre_mf = _jj_pre.loads(
            (__import__("pathlib").Path(tmp_path) / "shared-manifest.json").read_text()
        )
        pre_run_id = pre_mf.get("run_id", "w6-guard-ie1-00001")

        # ── Part issue (no _password_client / _check_s3_issued_recall stubs) ──
        # NOTE: _password_client and _check_s3_issued_recall are NOT stubbed.
        # They run for real through the guarded session.  If the allowlist
        # guard fires (e.g. mutant a3 removes HeadObject), the test FAILS.
        _mod._SESSION = None
        _mod._SESSION = w.make_guarded_session("issue")
        with (
            patch.object(_mod, "_utc_now",
                         lambda: __import__("datetime").datetime(
                             2026, 10, 22, 10, 0, tzinfo=__import__("datetime").timezone.utc)),
            patch.object(_mod, "_resolve_pool_id", _resolve_pool_id_stub),
            patch.object(_mod, "_schedule_guard", _schedule_guard_stub),
            patch.object(_mod, "_check_esm_enabled", _check_esm_stub),
            patch.object(_mod, "_check_tier2_code", _check_tier2_code_stub),
            patch.object(_mod, "_check_recall_table_exists", _check_recall_table_stub),
            patch.object(_mod, "_check_view_sql_unions_issued", _check_view_sql_stub),
            patch.object(_mod, "_check_dlq_empty", _check_dlq_stub),
            patch.object(_mod, "_check_no_open_livetest", _check_no_open_livetest_stub),
            patch.object(_mod, "_compute_expected_vins", _compute_expected_vins_stub),
            patch.object(_mod, "_get_avx_api_url", _get_avx_api_url_stub),
            patch.object(_mod, "_download_code_zip", lambda url: good_zip),
            patch.object(_mod, "_manifest_path", _manifest_path_hook),
            patch.object(_mod, "Results", _CapResults),
        ):
            main(["--stage", "staging", "--run-id", pre_run_id,
                  "--part", "issue",
                  "--allow-writes", "--allow-managed-writes"])

    assert res_holder, "Results not instantiated"
    # Find the issue Results (last non-pre invocation)
    issue_res = res_holder[-1]
    issue_labels = {r[0]: r[1] for r in issue_res.rows}
    assert issue_labels.get("issue-s3-key") == "PASS", (
        f"W6/K5 guard test: issue-s3-key must PASS (s3.head_object through guard); "
        f"rows={issue_res.rows}"
    )


