def test_k7_create_temp_user_uses_livetest_user_prefix(monkeypatch: pytest.MonkeyPatch) -> None:
    """K7 (red): _create_temp_user username uses _LIVETEST_USER_PREFIX not _LIVETEST_LABEL."""
    created: list[str] = []

    class _FakeIdp:
        def admin_create_user(self, **kw: Any) -> dict:
            created.append(kw["Username"])
            return {"User": {"Username": "sub-uuid-001", "Attributes": []}}

        def admin_set_user_password(self, **kw: Any) -> None:
            pass

        def admin_add_user_to_group(self, **kw: Any) -> None:
            pass

        def initiate_auth(self, **kw: Any) -> dict:
            return {"AuthenticationResult": {"IdToken": "tok"}}

    _mod._create_temp_user(_FakeIdp(), "pool", "client", "testrun", role="pe")
    assert created, "admin_create_user not called"
    username = created[0]
    # Must use the new livetest-fi-loop- prefix, not LIVETEST-g9.3-
    assert username.startswith("livetest-fi-loop-"), (
        f"username={username!r}; expected prefix 'livetest-fi-loop-'"
    )
    # C3 fix: must be email-format (pool uses UsernameAttributes=[email])
    assert "@" in username and username.endswith("@example.invalid"), (
        f"username={username!r}; must be email-format ending in @example.invalid"
    )
    assert username == "livetest-fi-loop-testrun-pe@example.invalid", (
        f"username={username!r}; expected 'livetest-fi-loop-testrun-pe@example.invalid'"
    )


