def test_k8_rate_expression_returns_refusal_reason() -> None:
    """K8 (red): rate() expression returns a reason string (not raises), causing FAIL."""
    import datetime as _dt  # noqa: PLC0415

    stub = MagicMock()
    # Serve a rate() expression for the recall schedule — the guard should refuse it
    def _get_schedule(Name: str, GroupName: str, **_: Any) -> dict:
        return {
            "Name": Name,
            "GroupName": GroupName,
            "ScheduleExpression": "rate(24 hours)",
            "ScheduleExpressionTimezone": "Etc/UTC",
            "State": "ENABLED",
        }
    stub.get_schedule.side_effect = _get_schedule
    stub.list_schedules.return_value = {
        "Schedules": [
            {"Name": "vsa-staging-tier2-daily-battery-us-west-2",  "GroupName": "default"},
            {"Name": "vsa-staging-tier2-daily-tires-us-west-2",    "GroupName": "default"},
            {"Name": "vsa-staging-tier2-daily-brakes-us-west-2",   "GroupName": "default"},
            {"Name": "vsa-staging-tier2-daily-cost-us-west-2",     "GroupName": "default"},
            {"Name": "vsa-staging-tier2-daily-recall-us-west-2",   "GroupName": "default"},
            {"Name": "vsa-staging-tier2-daily-warranty-us-west-2", "GroupName": "default"},
            {"Name": "vsa-staging-tier2-daily-service-us-west-2",  "GroupName": "default"},
            {"Name": "vsa-staging-tier2-daily-rebalance-us-west-2","GroupName": "default"},
            {"Name": "dms-staging-fi-dealer-progress",              "GroupName": "default"},
        ]
    }
    now = _dt.datetime(2026, 10, 21, 10, 0, 0, tzinfo=_dt.timezone.utc)
    reason = _mod._schedule_guard(stub, _mod._SCHEDULES, "staging", now)
    assert reason is not None, (
        "_schedule_guard must return a reason for rate() expression, not None"
    )
    assert "rate" in reason.lower() or "unsupported" in reason.lower(), (
        f"reason should mention 'rate' or 'unsupported'; got {reason!r}"
    )


def test_k8_schedule_group_discovered_via_list_schedules() -> None:
    """K8 (red): _schedule_guard uses list_schedules to discover the group, not hardcoded 'default'."""
    import datetime as _dt  # noqa: PLC0415

    stub = MagicMock()
    # Schedules are in a non-default group; get_schedule would fail without the right group
    real_group = "vsa-tier2-group"
    stub.list_schedules.return_value = {
        "Schedules": [
            {"Name": "vsa-staging-tier2-daily-battery-us-west-2",   "GroupName": real_group},
            {"Name": "vsa-staging-tier2-daily-tires-us-west-2",     "GroupName": real_group},
            {"Name": "vsa-staging-tier2-daily-brakes-us-west-2",    "GroupName": real_group},
            {"Name": "vsa-staging-tier2-daily-cost-us-west-2",      "GroupName": real_group},
            {"Name": "vsa-staging-tier2-daily-recall-us-west-2",   "GroupName": real_group},
            {"Name": "vsa-staging-tier2-daily-warranty-us-west-2", "GroupName": real_group},
            {"Name": "vsa-staging-tier2-daily-service-us-west-2",   "GroupName": real_group},
            {"Name": "vsa-staging-tier2-daily-rebalance-us-west-2", "GroupName": real_group},
            {"Name": "dms-staging-fi-dealer-progress",              "GroupName": real_group},
        ]
    }

    def _get_schedule(Name: str, GroupName: str, **_: Any) -> dict:
        if GroupName != real_group:
            from botocore.exceptions import ClientError  # noqa: PLC0415
            raise ClientError(
                {"Error": {"Code": "ResourceNotFoundException", "Message": "not found"}},
                "GetSchedule",
            )
        return {
            "Name": Name,
            "GroupName": GroupName,
            "ScheduleExpression": "cron(0 5 * * ? *)",
            "ScheduleExpressionTimezone": "Etc/UTC",
            "State": "ENABLED",
        }

    stub.get_schedule.side_effect = _get_schedule

    now = _dt.datetime(2026, 10, 21, 10, 0, 0, tzinfo=_dt.timezone.utc)
    # Should not raise; should find the schedule in real_group via list_schedules
    reason = _mod._schedule_guard(stub, _mod._SCHEDULES, "staging", now)
    assert reason is None, (
        f"_schedule_guard should pass (10:00 UTC, no window conflict); got reason={reason!r}"
    )
    # Must have called list_schedules to discover the group
    stub.list_schedules.assert_called()


# ── W4: window edge tests (m22, m23, m24) ─────────────────────────────────────
# These tests verify exact boundary behaviour of the maintenance-window and
# schedule-guard checks.  They catch three mutants:
#   m22  gap < _SCHED_GUARD_MIN - 1  (misses gap == 44 min)
#   m23  _MAINT_START_MIN < n ...    (misses the 01:45 boundary)
#   m24  abs(n - mnt) instead of     (breaks midnight wrap)
#         min(... % 1440, ... % 1440)

def _one_sched_stub(name: str, expr: str, tz: str = "Etc/UTC") -> Any:
    """Return a minimal scheduler stub for a single schedule *name*/*expr*."""
    stub = MagicMock()
    stub.list_schedules.return_value = {"Schedules": [{"Name": name, "GroupName": "default"}]}
    stub.get_schedule.return_value = {
        "Name": name, "GroupName": "default",
        "ScheduleExpression": expr,
        "ScheduleExpressionTimezone": tz,
        "State": "ENABLED",
    }
    return stub


def test_w4_maint_01_44_passes() -> None:
    """W4: 01:44 UTC is one minute before the window boundary — must pass."""
    t = _dt.datetime(2026, 10, 22, 1, 44, 0, tzinfo=_dt.timezone.utc)
    assert _mod._maint_window_guard(t) is None, (
        "01:44 UTC is before the maintenance window (01:45); must not be refused"
    )


def test_w4_maint_01_45_fails() -> None:
    """W4/m23: 01:45 UTC is the window start — must fail (catches m23 < → <=)."""
    t = _dt.datetime(2026, 10, 22, 1, 45, 0, tzinfo=_dt.timezone.utc)
    reason = _mod._maint_window_guard(t)
    assert reason is not None, (
        "01:45 UTC is exactly at the maintenance window start; must be refused (m23)"
    )


def test_w4_maint_03_29_fails() -> None:
    """W4: 03:29 UTC is inside the window — must fail."""
    t = _dt.datetime(2026, 10, 22, 3, 29, 0, tzinfo=_dt.timezone.utc)
    reason = _mod._maint_window_guard(t)
    assert reason is not None, "03:29 UTC is inside the maintenance window; must be refused"


def test_w4_maint_03_30_passes() -> None:
    """W4: 03:30 UTC is exactly at the window end (exclusive) — must pass."""
    t = _dt.datetime(2026, 10, 22, 3, 30, 0, tzinfo=_dt.timezone.utc)
    assert _mod._maint_window_guard(t) is None, (
        "03:30 UTC is at the maintenance window end (exclusive); must not be refused"
    )


def test_w4_schedule_gap_44_refuses() -> None:
    """W4/m22: gap exactly 44 min from cron → refused (< 45, catches m22 < 44)."""
    # recall at 05:00 (minute 300); 44 min before = 04:16 (minute 256)
    stub = _one_sched_stub("vsa-staging-tier2-daily-recall-us-west-2", "cron(0 5 * * ? *)")
    now = _dt.datetime(2026, 10, 22, 4, 16, 0, tzinfo=_dt.timezone.utc)
    schedules = [("vsa-staging-tier2-daily-recall-us-west-2", "default", "us-west-2")]
    reason = _mod._schedule_guard(stub, schedules, "staging", now)
    assert reason is not None, (
        "gap=44 must be refused (< _SCHED_GUARD_MIN=45); m22 would allow this"
    )


def test_w4_schedule_gap_45_allows() -> None:
    """W4/m22: gap exactly 45 min from cron → allowed (>= 45)."""
    # recall at 05:00 (minute 300); 45 min before = 04:15 (minute 255)
    stub = _one_sched_stub("vsa-staging-tier2-daily-recall-us-west-2", "cron(0 5 * * ? *)")
    now = _dt.datetime(2026, 10, 22, 4, 15, 0, tzinfo=_dt.timezone.utc)
    schedules = [("vsa-staging-tier2-daily-recall-us-west-2", "default", "us-west-2")]
    reason = _mod._schedule_guard(stub, schedules, "staging", now)
    assert reason is None, (
        f"gap=45 must be allowed (>= _SCHED_GUARD_MIN=45); got {reason!r}"
    )


def test_w4_schedule_midnight_wrap_refuses() -> None:
    """W4/m24: 23:40 is 30 min from cron at 00:10 → refused (wrap correct, catches m24)."""
    # cron at 00:10 = minute 10; current 23:40 = minute 1420
    # correct gap = min((1420-10)%1440, (10-1420)%1440) = min(1410, 30) = 30 < 45 → refuse
    # m24 gap = abs(1420-10) = 1410 → allow (wrong)
    stub = _one_sched_stub("my-early-sched", "cron(10 0 * * ? *)")
    now = _dt.datetime(2026, 10, 22, 23, 40, 0, tzinfo=_dt.timezone.utc)
    schedules = [("my-early-sched", "default", "us-west-2")]
    reason = _mod._schedule_guard(stub, schedules, "staging", now)
    assert reason is not None, (
        "23:40 is 30 min before 00:10 cron (midnight wrap); must be refused (m24)"
    )


