def test_w4_received_date_future_fails() -> None:
    """W4 (red→fix): received_date > today's UTC date → must fail.

    The ADP writer should never set a future date; if it does, the next recall
    run's query WHERE received_date <= CURRENT_DATE would skip this campaign.
    Catches the missing check (current code only checks non-empty).
    """
    import datetime as _dts  # noqa: PLC0415
    tomorrow = _dts.datetime(2026, 10, 23, 0, 0, 0, tzinfo=_dts.timezone.utc).strftime("%Y-%m-%d")
    ddb = MagicMock()
    ddb.get_item.return_value = {"Item": {
        "campaign_id": {"S": "MRD-2026-001"},
        "status": {"S": "issued"},
        "received_date": {"S": tomorrow},
    }}
    with patch.object(_mod, "_utc_now",
                      lambda: _dts.datetime(2026, 10, 22, 10, 0, 0, tzinfo=_dts.timezone.utc)):
        res = Results()
        result = _mod._check_ddb_issued_row(res, ddb, "staging", "MRD-2026-001")
    # With the fix applied, the date check must fail.
    assert any(r[1] == "FAIL" for r in res.rows), (
        f"W4: received_date in the future must cause a FAIL; rows={res.rows}"
    )
    assert result is False, (
        f"W4: _check_ddb_issued_row must return False when received_date is in future; "
        f"got {result!r}"
    )


