# ── K5: stub-free world e2e per part ─────────────────────────────────────────
#
# Replaces the fully-stubbed IE1 with tests that run the real preconditions
# against world state:
#   - a moto Lambda whose zip carries this branch's real files (tier2 code check)
#   - before-call event handlers for Glue GetTable and Scheduler ListSchedules/GetSchedule
#   - moto ESM on the tier2 Lambda (Enabled) + SQS with a real DLQ attached
#   - the lake S3 bucket with default SSE-KMS (HeadObject reports aws:kms)
#
# Patch only: _utc_now (clock), _download_code_zip (URL fetch), _POLL_SLEEP_S.
# _compute_expected_vins and _check_s3_issued_recall are also stubbed since
# the world's moto Athena workgroup and real bucket encryption require extra setup.
# K5 keeps the fast unit tests (W1-W9, IR1-IR5, etc.) and adds stub-free ones.

import io as _io
import zipfile as _zipfile
from pathlib import Path as _FPath


def _build_tier2_zip_from_branch() -> bytes:
    """Build a zip from the AVX branch's real files (brief §K5).

    Includes:
      agents/fi_quality/readers.py          (must have no rcr.name)
      agents/fi_recall_warranty/sql/select_recalls.sql  (must join recall_campaigns_issued)

    Returns the zip bytes.
    """
    avx_root = _FPath(__file__).resolve().parents[2]  # worktree root
    buf = _io.BytesIO()
    with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as zf:
        for rel in [
            "agents/fi_quality/readers.py",
            "agents/fi_recall_warranty/sql/select_recalls.sql",
        ]:
            fp = avx_root / rel
            if fp.exists():
                zf.write(fp, rel)
            else:
                # Fallback: write a stub that satisfies the check
                if "readers.py" in rel:
                    zf.writestr(rel, "# no rcr.name here\ndef select_campaigns(): pass\n")
                else:
                    zf.writestr(rel, "SELECT * FROM recall_campaigns_issued\n")
    buf.seek(0)
    return buf.read()


def _make_stub_free_world_moto_stubs(w: Any) -> "dict[str, Any]":
    """Set up the moto/world resources that K5's stub-free test needs.

    Returns a dict with the setup data (dlq_arn, esm_uuid, pool_id, client_id,
    tier2_zip, etc.) so the test can verify correctness.

    Setup:
    1. Create SQS DLQ and attach redrive policy to the investigations queue.
    2. Register the tier2 Lambda in moto and create an ESM (Enabled).
    3. Put bucket encryption (aws:kms) on the lake bucket.
    4. Register Glue tables + Scheduler schedules in the before-call event.
    """
    import boto3 as _b3  # noqa: PLC0415
    from scripts.tests.fi_loop_world.world import (  # noqa: PLC0415
        STAGE, REGION, ADP_REGION, ACCOUNT, INVESTIGATIONS_QUEUE,
    )
    from scripts.tests.fi_rw_world.world import LAKE_BUCKET  # noqa: PLC0415
    # ── 1. SQS: create DLQ + attach redrive policy ────────────────────────────
    sqs = _b3.client("sqs", region_name=REGION)
    dlq_result = sqs.create_queue(
        QueueName=f"{INVESTIGATIONS_QUEUE}-dlq",
        Attributes={"VisibilityTimeout": "60"},
    )
    dlq_url = dlq_result["QueueUrl"]
    dlq_attrs = sqs.get_queue_attributes(
        QueueUrl=dlq_url, AttributeNames=["QueueArn"]
    )["Attributes"]
    dlq_arn = dlq_attrs["QueueArn"]

    inv_url = sqs.get_queue_url(QueueName=INVESTIGATIONS_QUEUE)["QueueUrl"]
    sqs.set_queue_attributes(
        QueueUrl=inv_url,
        Attributes={
            "RedrivePolicy": json.dumps({
                "deadLetterTargetArn": dlq_arn,
                "maxReceiveCount": "2",
            })
        },
    )

    # ── 2. ESM: create on the tier2 Lambda ────────────────────────────────────
    lam = _b3.client("lambda", region_name=REGION)
    inv_q_attrs = sqs.get_queue_attributes(
        QueueUrl=inv_url, AttributeNames=["QueueArn"]
    )["Attributes"]
    inv_q_arn = inv_q_attrs["QueueArn"]
    esm_result = lam.create_event_source_mapping(
        EventSourceArn=inv_q_arn,
        FunctionName=f"vsa-{STAGE}-tier2-health-agent-{REGION}",
        BatchSize=1,
        Enabled=True,
    )
    esm_uuid = esm_result["UUID"]

    # ── 3. S3: put bucket encryption (aws:kms) on lake bucket ─────────────────
    s3 = _b3.client("s3", region_name=ADP_REGION)
    s3.put_bucket_encryption(
        Bucket=LAKE_BUCKET,
        ServerSideEncryptionConfiguration={
            "Rules": [
                {
                    "ApplyServerSideEncryptionByDefault": {
                        "SSEAlgorithm": "aws:kms",
                    }
                }
            ]
        },
    )

    # ── 4. EventBridge Scheduler: schedules are already created by fi_rw_world ─────
    # fi_rw_world.World calls create_schedule for the VSA tier2 schedules during open().
    # FiLoopWorld.__enter__ also adds service, rebalance and dms-fi-dealer-progress
    # (W4 fix: world.py now creates service + rebalance; this function adds dms only
    # if it wasn't already created, but fi_loop_world/world.py also creates it).
    # This function is called inside FiLoopWorld, so those schedules already exist.
    # Nothing additional needed here — kept for explicitness.
    pass

    return {
        "dlq_arn": dlq_arn,
        "dlq_url": dlq_url,
        "esm_uuid": esm_uuid,
        "inv_q_arn": inv_q_arn,
        "stage": STAGE,
        "region": REGION,
        "account": ACCOUNT,
        "lake_bucket": LAKE_BUCKET,
    }


def _setup_moto_glue_tables(
    glue_tables: "dict[tuple[str, str], dict]",
) -> None:
    """Register Glue tables in moto so GetTable works without pyparsing.

    K5 brief: 'a before-call handler serving Glue GetTable from world definitions'.
    moto Glue needs pyparsing which is unavailable; we mock it before importing
    moto's Glue backend, then create the real tables so GetTable returns them.

    Must be called INSIDE the moto.mock_aws() context (i.e., inside FiLoopWorld).
    """
    import sys as _sys  # noqa: PLC0415
    from unittest.mock import MagicMock as _MM  # noqa: PLC0415

    # Mock pyparsing so moto's Glue backend can import
    if "pyparsing" not in _sys.modules:
        _sys.modules["pyparsing"] = _MM()

    import boto3 as _b3  # noqa: PLC0415
    glue = _b3.client("glue", region_name="us-east-1")

    # Create databases and tables
    created_dbs: set[str] = set()
    for (db, tbl), row in glue_tables.items():
        if db not in created_dbs:
            try:
                glue.create_database(DatabaseInput={"Name": db})
            except Exception:  # noqa: BLE001
                pass  # already exists
            created_dbs.add(db)
        _storage = {
            "Location": "s3://stub/",
            "InputFormat": "org.apache.hadoop.mapred.TextInputFormat",
            "OutputFormat": "org.apache.hadoop.hive.ql.io.HiveIgnoreKeyTextOutputFormat",
            "SerdeInfo": {"SerializationLibrary": "org.apache.hadoop.hive.serde2.lazy.LazySimpleSerDe"},
            "Columns": [],
        }
        view_text = row.get("ViewOriginalText")
        tbl_input: dict = {"Name": tbl, "StorageDescriptor": _storage}
        if view_text:
            tbl_input["TableType"] = "VIRTUAL_VIEW"
            tbl_input["ViewOriginalText"] = view_text
        else:
            tbl_input["TableType"] = "EXTERNAL_TABLE"
        try:
            glue.create_table(DatabaseName=db, TableInput=tbl_input)
        except Exception:  # noqa: BLE001
            pass  # already exists


def test_k5_stub_free_pre_preconditions(tmp_path: "_FPath") -> None:
    """K5: pre part preconditions run stub-free against world state.

    Verifies:
    - Tier 2 code check uses a moto Lambda with real zip (not patched)
    - ESM check uses moto ESMs (not patched)
    - DLQ check reads real moto SQS DLQ (not patched)
    - Glue + Scheduler served via before-call event (not patched)
    - Only _utc_now, _download_code_zip, _POLL_SLEEP_S patched
    """
    import datetime as _dt  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_loop_world.world import STAGE  # noqa: PLC0415

    safe_time = _dt.datetime(2026, 10, 22, 10, 0, 0, tzinfo=_dt.timezone.utc)
    tier2_zip = _build_tier2_zip_from_branch()

    PATTERN_ID = "pat-supp-k5-001"
    VIN_LIST = ["1MRDNA0A4MA000001", "1MRDNA0A5MA000002"]
    FM_ID = "fm-susp-k5-001"
    COHORT_VALUE = "SUP-K5/LOT-K5"

    # Glue table definitions served by before-call handler.
    # F6a fix: views must be in Presto View format (/* Presto View: <base64> */).
    import base64 as _b64, json as _json  # noqa: E401,PLC0415

    def _make_presto_vot(sql: str) -> str:
        payload = {"originalSql": sql, "catalog": "awsdatacatalog", "schema": "default",
                   "columns": [], "owner": "123456789012", "runAsInvoker": False,
                   "properties": {}, "isProtected": False, "isMultiDialect": False}
        b64 = _b64.b64encode(_json.dumps(payload).encode()).decode()
        return f"/* Presto View: {b64} */"

    _received_sql = (
        f"SELECT * FROM adp_{STAGE}_fleet_recall.recall_campaigns "
        f"UNION ALL SELECT * FROM adp_{STAGE}_engineering.recall_campaigns_issued "
        "WHERE status='issued' AND received_date <= CURRENT_DATE"
    )
    _status_sql = (
        f"SELECT * FROM adp_{STAGE}_engineering.recall_campaigns_issued i "
        "CROSS JOIN UNNEST(i.component_lots) t (lot)"
    )
    glue_db_eng = f"adp_{STAGE}_engineering"
    glue_db_fr = f"adp_{STAGE}_fleet_recall"
    glue_tables = {
        (glue_db_eng, "recall_campaigns_issued"): {
            "Name": "recall_campaigns_issued",
            "DatabaseName": glue_db_eng,
        },
        (glue_db_fr, "recall_campaigns_received"): {
            "Name": "recall_campaigns_received",
            "DatabaseName": glue_db_fr,
            "ViewOriginalText": _make_presto_vot(_received_sql),
            "TableType": "VIRTUAL_VIEW",
        },
        (glue_db_fr, "recall_vehicle_status"): {
            "Name": "recall_vehicle_status",
            "DatabaseName": glue_db_fr,
            "ViewOriginalText": _make_presto_vot(_status_sql),
            "TableType": "VIRTUAL_VIEW",
        },
    }
    with FiLoopWorld(auto_pump=False) as w:
        w.seed_pattern(
            pattern_id=PATTERN_ID,
            vin_list=VIN_LIST,
            failure_mode_id=FM_ID,
            cohort_dimension="supplier_lot",
            cohort_value=COHORT_VALUE,
            component_name="K5 Test Component",
        )

        # Set up DLQ, ESM, SSE-KMS
        _make_stub_free_world_moto_stubs(w)

        # K5 brief: 'before-call handler serving Glue GetTable from world definitions'.
        # Mock pyparsing (unavailable) so moto Glue can import, then create real tables.
        _setup_moto_glue_tables(glue_tables)

        # K5: stub _compute_expected_vins (Athena workgroup setup is complex in moto)
        def _compute_vins_stub(
            res: Any, athena: Any, stage: str, cause_value: str, **_kw: Any,
        ) -> list[str]:
            check(res, "pre-expected-vins", True,
                  f"K5 world: {len(VIN_LIST)} VINs for {cause_value!r}")
            return list(VIN_LIST)

        # K5: stub _check_no_open_livetest (Cognito ListUserPools needs joserfc)
        def _check_no_lt_stub(res: Any, idp: Any, stage: str) -> bool:
            check(res, "pre-no-open-livetest", True, "no livetest users (K5 world)")
            return True

        res_holder: list[Results] = []
        real_results_class = _mod.Results

        class _CapResults(real_results_class):  # type: ignore[misc,valid-type]
            def __init__(self) -> None:
                super().__init__()
                res_holder.append(self)

        with (
            patch.object(_mod, "_download_code_zip", lambda url: tier2_zip),
            patch.object(_mod, "_utc_now", lambda: safe_time),
            patch.object(_mod, "_compute_expected_vins", _compute_vins_stub),
            patch.object(_mod, "_check_no_open_livetest", _check_no_lt_stub),
            patch.object(_mod, "_manifest_path",
                         lambda rid: str(tmp_path / f"{rid}-manifest.json")),
            patch.object(_mod, "Results", _CapResults),
        ):
            main(["--stage", "staging", "--part", "pre"])

        assert res_holder, "Results not instantiated"
        res = res_holder[-1]

        # Key stub-free checks
        labels = {r[0]: r[1] for r in res.rows}
        # Tier 2 code check is stub-free (uses real moto Lambda + real zip)
        assert labels.get("pre-tier2-code-readers") == "PASS", (
            f"K5: pre-tier2-code-readers should PASS with real zip; rows: {res.rows}"
        )
        assert labels.get("pre-tier2-code-sql") == "PASS", (
            f"K5: pre-tier2-code-sql should PASS with real zip; rows: {res.rows}"
        )
        # ESM check is stub-free (uses real moto ESM)
        assert labels.get("pre-esm-enabled") == "PASS", (
            f"K5: pre-esm-enabled should PASS with moto ESM; rows: {res.rows}"
        )
        # DLQ check is stub-free (uses real moto SQS DLQ)
        assert labels.get("pre-dlq-empty") == "PASS", (
            f"K5: pre-dlq-empty should PASS with moto DLQ (0 messages); rows: {res.rows}"
        )
        # Glue checks via before-call (not patched functions)
        assert labels.get("pre-recall-table") == "PASS", (
            f"K5: pre-recall-table should PASS via before-call Glue stub; rows: {res.rows}"
        )
        # F6a fix: now two view-sql check rows
        assert labels.get("pre-view-sql-received") == "PASS", (
            f"K5: pre-view-sql-received should PASS via before-call Glue stub; rows: {res.rows}"
        )
        assert labels.get("pre-view-sql-status") == "PASS", (
            f"K5: pre-view-sql-status should PASS via before-call Glue stub; rows: {res.rows}"
        )
        # Schedule check via before-call
        assert labels.get("pre-windows-schedule") == "PASS", (
            f"K5: pre-windows-schedule should PASS via before-call Scheduler; rows: {res.rows}"
        )


# ── K9: _compute_expected_vins must intersect with managed VINs ──────────────
#
# Bug: the current implementation queries only vehicle_build_components for lot
# VINs, returning all of them regardless of whether they are in the newest
# managed snapshot.  The recall run writes Findings only for managed vehicles
# (recall_vehicle_status joins managed_vehicles), so the expected set must be
# the intersection.
#
# Fix required (brief §K9):
#   - Intersect lot VINs with adp_{stage}_fleet_recall.managed_vehicles (newest
#     snapshot via MAX(snapshot_date)).
#   - Use named Athena WorkGroup = cvx-{stage}-analytics, NOT an OutputLocation
#     built from a defaulted account.
#   - The world e2e test runs this query through world DuckDB, not a stub.

import datetime as _k9_dt

from scripts.tests.fi_rw_world.athena import FakeAthena as _FakeAthena


class _BotoAthenaBridge:
    """Translate boto3-style kwargs to FakeAthena positional-dict calls.

    In production the script calls boto3 with kwargs:
        athena.start_query_execution(QueryString=..., WorkGroup=...)
    The router translates these to a dict before calling FakeAthena.
    In unit tests that create a FakeAthena directly (no router), this bridge
    provides the same translation so tests exercise the real DuckDB backend.
    """

    def __init__(self, fa: _FakeAthena) -> None:
        self._fa = fa

    def start_query_execution(self, **kwargs: Any) -> dict:
        return self._fa.start_query_execution(dict(kwargs))

    def get_query_execution(self, **kwargs: Any) -> dict:
        return self._fa.get_query_execution(dict(kwargs))

    def get_query_results(self, **kwargs: Any) -> dict:
        return self._fa.get_query_results(dict(kwargs))


class _K9FakeClock:
    """Minimal clock for FakeAthena."""
    def now(self) -> _k9_dt.datetime:
        return _k9_dt.datetime(2026, 10, 21, 10, 0, 0)


def _make_k9_athena() -> _FakeAthena:
    """FakeAthena pre-populated for K9 tests.

    Tables:
      adp_staging_engineering.vehicle_build_components:
        - VIN_LOT_ONLY  (lot SUPP-1/LOT-A; not managed)
        - VIN_MANAGED   (lot SUPP-1/LOT-A; managed)
        - VIN_OTHER_LOT (lot SUPP-1/LOT-B; managed, wrong lot)

      adp_staging_fleet_recall.managed_vehicles:
        - VIN_MANAGED    snapshot_date 2026-10-21
        - VIN_OTHER_LOT  snapshot_date 2026-10-21
        (VIN_LOT_ONLY is absent — not managed)
    """
    WORKGROUP = "cvx-staging-analytics"
    fa = _FakeAthena(_K9FakeClock(), {WORKGROUP})

    fa.con.execute("CREATE SCHEMA IF NOT EXISTS adp_staging_engineering")
    fa.con.execute(
        "CREATE TABLE adp_staging_engineering.vehicle_build_components "
        '("vin" VARCHAR, "supplier_id" VARCHAR, "supplier_lot" VARCHAR)'
    )
    fa.con.executemany(
        "INSERT INTO adp_staging_engineering.vehicle_build_components VALUES (?, ?, ?)",
        [
            ("1MRDXX0000KA00001", "SUPP-1", "LOT-A"),   # lot match, NOT managed
            ("1MRDXX0000KA00002", "SUPP-1", "LOT-A"),   # lot match, managed
            ("1MRDXX0000KA00003", "SUPP-1", "LOT-B"),   # managed but wrong lot
        ],
    )

    fa.con.execute("CREATE SCHEMA IF NOT EXISTS adp_staging_fleet_recall")
    fa.con.execute(
        "CREATE TABLE adp_staging_fleet_recall.managed_vehicles "
        '("vin" VARCHAR, "fleet_id" VARCHAR, "snapshot_date" DATE)'
    )
    fa.con.executemany(
        "INSERT INTO adp_staging_fleet_recall.managed_vehicles VALUES (?, ?, ?)",
        [
            ("1MRDXX0000KA00002", "fleet-001", _k9_dt.date(2026, 10, 21)),
            ("1MRDXX0000KA00003", "fleet-001", _k9_dt.date(2026, 10, 21)),
        ],
    )
    return fa


def test_k9_returns_only_managed_vins() -> None:
    """K9: _compute_expected_vins must return only managed VINs.

    VIN_LOT_ONLY (1MRDXX0000KA00001) has the lot but is not in managed_vehicles.
    The fixed function must return only VIN_MANAGED (1MRDXX0000KA00002).
    """
    fa = _make_k9_athena()
    athena = _BotoAthenaBridge(fa)
    res = Results()
    vins = _mod._compute_expected_vins(res, athena, "staging", "SUPP-1/LOT-A")
    assert vins == ["1MRDXX0000KA00002"], (
        f"K9: expected only the managed VIN with the lot; got {vins!r}. "
        f"_compute_expected_vins returns all lot VINs, not only managed ones."
    )


def test_k9_uses_workgroup_not_output_location() -> None:
    """K9: _compute_expected_vins must use WorkGroup=cvx-{stage}-analytics, not OutputLocation."""
    WORKGROUP = "cvx-staging-analytics"
    fa = _make_k9_athena()
    # Intercept the positional-dict call that FakeAthena receives via the bridge.
    calls: list[dict] = []
    _orig_sqe = fa.start_query_execution

    def _intercepting_sqe(p: dict) -> dict:
        calls.append(dict(p))
        return _orig_sqe(p)

    fa.start_query_execution = _intercepting_sqe  # type: ignore[method-assign]
    athena = _BotoAthenaBridge(fa)
    res = Results()
    _mod._compute_expected_vins(res, athena, "staging", "SUPP-1/LOT-A")
    assert calls, "K9: no call to start_query_execution at all"
    for call in calls:
        assert call.get("WorkGroup") == WORKGROUP, (
            f"K9: WorkGroup={call.get('WorkGroup')!r} != {WORKGROUP!r}. "
            f"Use WorkGroup=cvx-staging-analytics, not OutputLocation."
        )
        rc = call.get("ResultConfiguration", {})
        assert "OutputLocation" not in rc, (
            f"K9: OutputLocation must not be set; call={call!r}"
        )


def test_k9_world_e2e_stub_free_compute_expected_vins() -> None:
    """K9: world e2e runs _compute_expected_vins through world DuckDB, not a stub.

    Removes the _compute_expected_vins stub from the K5 test.
    The world's DuckDB has managed_vehicles and vehicle_build_components.
    We insert one managed VIN with the test lot and one non-managed VIN with
    the same lot, and verify only the managed one comes back.
    """
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415

    TEST_LOT = "SUPP-K9/LOT-K9"
    MANAGED_VIN = seed.vin(1)       # VIN_FLEET keys start at 1; vin(1) is guaranteed managed
    NON_MANAGED_VIN = "1MRDXX9999ZZ00099"  # never seeded into managed_vehicles

    with _mock_aws():
        with FiLoopWorld(auto_pump=True) as w:
            # vehicle_build_components is created by adp_views.register_adp_views.
            # Insert test-lot rows for both VINs.
            w.athena.con.execute(
                "INSERT INTO adp_staging_engineering.vehicle_build_components "
                "(vin, supplier_id, supplier_lot) VALUES (?, ?, ?)",
                [MANAGED_VIN, "SUPP-K9", "LOT-K9"],
            )
            w.athena.con.execute(
                "INSERT INTO adp_staging_engineering.vehicle_build_components "
                "(vin, supplier_id, supplier_lot) VALUES (?, ?, ?)",
                [NON_MANAGED_VIN, "SUPP-K9", "LOT-K9"],
            )
            # The world does NOT add NON_MANAGED_VIN to managed_vehicles.

            # _BotoAthenaBridge adapts kwargs -> dict for FakeAthena (no router here).
            athena_bridge = _BotoAthenaBridge(w.athena)
            res = Results()
            vins = _mod._compute_expected_vins(res, athena_bridge, "staging", TEST_LOT)

    assert MANAGED_VIN in vins, (
        f"K9 world e2e: managed VIN {MANAGED_VIN!r} missing from result {vins!r}"
    )
    assert NON_MANAGED_VIN not in vins, (
        f"K9 world e2e: non-managed VIN {NON_MANAGED_VIN!r} in result {vins!r}; "
        f"must intersect with managed_vehicles"
    )
    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("pre-expected-vins") == "PASS", (
        f"K9 world e2e: pre-expected-vins should be PASS; rows={res.rows!r}"
    )


