# ── after-run world e2e ───────────────────────────────────────────────────────

def test_af4_after_run_world_e2e(tmp_path: Any) -> None:
    """AF4 (C5/C6 fix): after-run drives main() using Findings from the real Tier 2 recall run.

    Runs the complete investigation → issue_recall → Tier 2 recall component chain
    (mirrors test_fi_loop_world.py::test_loop_investigation_to_recall_findings_with_component_lots
    steps 1-7) to produce real recall Findings in schema-format evidence.

    Then runs --part after-run and verifies:
    - after-run-run-record PASS
    - after-run-findings-count PASS (set equality)
    - after-run-findings-item-types PASS (reads from evidence list)
    - after-run-findings-recall-rule PASS (component_lots in list evidence)
    - after-run-findings-disclosure-txt PASS (byte equality with catalog row)
    - after-run-fleet-queue PASS
    - after-run-cms-recall-list PASS
    """
    import datetime as _dt  # noqa: PLC0415
    import json as _json  # noqa: PLC0415
    import uuid as _uuid  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_loop_world import approve_route as _ar  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415
    from scripts.tests.fi_rw_world.world import _ISSUED_RECALL_COLUMNS  # noqa: PLC0415

    STAGE = "staging"
    RUN_ID = "fi-loop-20261021T050500-aabbccdd"
    COMPLETED_AT = "2026-10-21T04:00:00+00:00"

    # Use 3 managed VINs (indices 1-3) so the Tier 2 recall agent finds them.
    MANAGED_VINS = [seed.vin(i) for i in range(1, 4)]
    FLEET_ID = seed.FLEETS[0]
    COHORT_VALUE = "SUP-C/LOT-003"
    SUMMARY = "Lot-specific suspension recall"
    CONSEQUENCE = "Reduced handling"
    REMEDY = "Inspect and replace"
    today = _dt.date.today()

    with _mock_aws():
        with FiLoopWorld() as w:
            # ── Steps 1-5: investigation → issue_recall (mirrors loop world test) ──
            pattern_id = f"pat-af4-{_uuid.uuid4().hex[:8]}"
            w.seed_pattern(
                pattern_id=pattern_id,
                vin_list=MANAGED_VINS,
                failure_mode_id="fm-af4-001",
                cohort_dimension="supplier_lot",
                cohort_value=COHORT_VALUE,
                component_name="Front Suspension Bushing",
            )

            sub = "eng-af4-001"
            inv_resp = w.post_investigation(pattern_id=pattern_id, sub=sub)
            pump_result = w.pump_investigation(inv_resp["investigation_id"])
            inv_row = pump_result["investigation"]
            finding_id = inv_row["finding_id"]

            option_id = "opt-recall-001"  # hardware_recall option seeded by seed_pattern()
            _ar.post_approve(
                w, finding_id=finding_id, action_kind="record_engineering_decision",
                target_system="adp", parameters={"option_id": option_id}, sub=sub,
            )

            import boto3 as _b3  # noqa: PLC0415
            r_east = _b3.resource("dynamodb", region_name="us-east-1")
            thread_rows = r_east.Table("adp-staging-digital-thread").scan().get("Items", [])
            assert thread_rows, "No thread rows after record_engineering_decision"
            campaign_id = str(thread_rows[0].get("recall_campaign_id", ""))
            assert campaign_id.startswith("MRD-"), (
                f"recall_campaign_id should start with MRD-; got {campaign_id!r}"
            )

            r_west = _b3.resource("dynamodb", region_name="us-west-2")
            quality_issues = r_west.Table("vsa-staging-avx-findings").scan(
                FilterExpression="finding_kind = :k",
                ExpressionAttributeValues={":k": "quality.issue"},
            ).get("Items", [])
            assert quality_issues, "Expected quality.issue Finding"
            issue_finding_id = quality_issues[0]["finding_id"]

            issue_resp = _ar.post_approve(
                w, finding_id=issue_finding_id, action_kind="issue_recall",
                target_system="adp", parameters={}, sub=sub,
            )
            assert issue_resp.get("status") == "executed", (
                f"issue_recall not executed: {issue_resp!r}"
            )

            # ── Step 6: inject issued row into DuckDB ──────────────────────────
            col_names = [c for c, _ in _ISSUED_RECALL_COLUMNS]
            row_data: dict = {c: None for c in col_names}
            row_data.update({
                "campaign_id": campaign_id,
                "status": "issued",
                "received_date": today,
                "recall_class": "safety",
                "manufacturer": "Meridian",
                "component": "Front Suspension Bushing",
                "summary": SUMMARY,
                "consequence": CONSEQUENCE,
                "remedy": REMEDY,
                "do_not_drive": False,
                "park_outside": False,
                "models": ["Azimuth"],
                "model_year_min": 0,
                "model_year_max": 9999,
                "plants": None,
                "component_lots": [COHORT_VALUE],
                "fault_codes": None,
                "remedy_available_from": today + _dt.timedelta(days=90),
                "catalog_version": "1.0.0",
                "affected_vins_count": len(MANAGED_VINS),
            })
            ph = ", ".join("?" for _ in col_names)
            w.athena.con.execute(
                f"INSERT INTO adp_staging_engineering.recall_campaigns_issued "
                f"({', '.join(col_names)}) VALUES ({ph})",
                [row_data.get(c) for c in col_names],
            )

            # recall_campaigns_received is now a VIEW (UNION ALL of
            # recall_campaigns + recall_campaigns_issued); the issued row
            # inserted above (status='issued', received_date=today) already
            # surfaces through the issued branch — no INSERT needed.

            # recall_vehicle_status is now a VIEW computed from
            # managed_vehicles × vehicle_identity × recall_campaigns_received.
            # Populate vehicle_identity so the population CTE can match
            # MANAGED_VINS to the issued campaign.  managed_vehicles was
            # already seeded in _create_lake_tables with VINs 1-3; the
            # campaign uses models=["Azimuth"] with no year/plant restriction.
            for v in MANAGED_VINS:
                w.athena.con.execute(
                    "INSERT INTO adp_staging_vehicle_identity.vehicle_identity "
                    "(vin, model, model_year, manufacture_date, assembly_plant) "
                    "VALUES (?, ?, ?, ?, ?)",
                    [v, "Azimuth", 2023, today - _dt.timedelta(days=365 * 3), None],
                )

            # ── Step 7: run the Tier 2 recall component ────────────────────────
            from scripts.tests.fi_rw_world.world import HEALTH_FN  # noqa: PLC0415
            w.lam.run(HEALTH_FN, {"stage": "staging", "component": "recall"})
            w.pump()

            # Verify real Findings were created by the Tier 2 run.
            recall_findings = r_west.Table("vsa-staging-avx-findings").scan(
                FilterExpression="finding_kind = :k",
                ExpressionAttributeValues={":k": _mod._RECALL_FINDING_KIND},
            ).get("Items", [])
            assert recall_findings, (
                "No recall Findings produced by Tier 2 recall component; "
                "cannot drive after-run from real Findings"
            )

            # ── Seed CMS recall cache ─────────────────────────────────────────
            w.seed_recall_cache(
                fleet_id=FLEET_ID, vin_list=MANAGED_VINS, campaign_id=campaign_id,
            )

            # ── Insert run record ─────────────────────────────────────────────
            ddb_avx = w.internal("dynamodb")
            run_table = _mod._AGENT_RUNS_TABLE.format(stage=STAGE)
            try:
                ddb_avx.create_table(
                    TableName=run_table,
                    KeySchema=[
                        {"AttributeName": "agent_component", "KeyType": "HASH"},
                        {"AttributeName": "started_at", "KeyType": "RANGE"},
                    ],
                    AttributeDefinitions=[
                        {"AttributeName": "agent_component", "AttributeType": "S"},
                        {"AttributeName": "started_at", "AttributeType": "S"},
                    ],
                    BillingMode="PAY_PER_REQUEST",
                )
            except Exception:  # noqa: BLE001
                pass
            ddb_avx.put_item(
                TableName=run_table,
                Item={
                    "agent_component": {"S": _mod._RECALL_AGENT_COMPONENT},
                    "started_at": {"S": "2026-10-21T05:00:00+00:00"},
                    "status": {"S": "completed"},
                    "artifacts_written": {"N": "1"},
                },
            )

            # ── Write manifest ────────────────────────────────────────────────
            manifest_data = {
                "run_id": RUN_ID, "stage": STAGE,
                "records": {
                    "issued_campaign_id": campaign_id,
                    "part_issue_completed_at": COMPLETED_AT,
                },
                "expected_vins": MANAGED_VINS,
                "account": "123456789012",
            }
            p = tmp_path / f"{RUN_ID}.json"
            p.write_text(_json.dumps(manifest_data))

            # ── Run --part after-run ──────────────────────────────────────────
            def _world_client(service: str, region: str, **_kw: Any) -> Any:
                return w.internal(service, region=region)

            # Athena stub: recall_vehicle_status returns the MANAGED_VINS;
            # catalog row returns the expected summary/consequence/remedy.
            def _athena_stub(athena: Any, stage_: str, sql: str, label: str) -> list[dict]:
                if "recall_vehicle_status" in label:
                    return [{"vin": v, "fleet_id": FLEET_ID,
                             "match_basis": "POPULATION", "remedied": "false"}
                            for v in MANAGED_VINS]
                if "recall_catalog_row" in label or "recall_campaigns_received" in label:
                    return [{
                        "summary": SUMMARY,
                        "consequence": CONSEQUENCE,
                        "remedy": REMEDY,
                    }]
                return []

            res_holder: list[Results] = []
            real_rc = _mod.Results

            class _Cap(real_rc):  # type: ignore[misc,valid-type]
                def __init__(self) -> None:
                    super().__init__()
                    res_holder.append(self)

            with (
                patch.object(_mod, "_manifest_path", lambda rid: str(p)),
                patch.object(_mod, "_athena_query_paged", _athena_stub),
                patch.object(_mod, "Results", _Cap),
            ):
                # W11 fix: set _SESSION to the guarded world session before calling main().
                # _part_after_run calls _init_session("after-run") which is idempotent;
                # since _SESSION is already set, it uses the guarded session and the
                # allowlists are enforced throughout the part run.
                _mod._SESSION = w.make_guarded_session("after-run")
                main(["--stage", STAGE, "--run-id", RUN_ID, "--part", "after-run"])

    assert res_holder, "Results not instantiated"
    res = res_holder[-1]
    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("after-run-manifest-read") == "PASS", f"rows={res.rows}"
    assert labels.get("after-run-run-record") == "PASS", f"rows={res.rows}"
    assert labels.get("after-run-recall-vehicle-status") == "PASS", (
        f"C6: rvs set equality; rows={res.rows}"
    )
    assert labels.get("after-run-findings-count") == "PASS", (
        f"C6: findings set equality; rows={res.rows}"
    )
    assert labels.get("after-run-findings-item-types") == "PASS", (
        f"C5: item type from evidence list; rows={res.rows}"
    )
    assert labels.get("after-run-findings-recall-rule") == "PASS", (
        f"C5: recall.rule from evidence list; rows={res.rows}"
    )
    assert labels.get("after-run-findings-disclosure-txt") == "PASS", (
        f"C5: disclosure_txt byte-equality; rows={res.rows}"
    )
    assert labels.get("after-run-fleet-queue") == "PASS", f"rows={res.rows}"
    assert labels.get("after-run-cms-recall-list") == "PASS", f"rows={res.rows}"


