# ── cleanup world e2e ─────────────────────────────────────────────────────────

def test_cl3_cleanup_world_e2e(tmp_path: Any) -> None:
    """CL3: cleanup world e2e — deletes manifest ids via real _check_residue + _delete_temp_user.

    C4 F3a / W4 F3a / W13 F3a: test now exercises all F3a fixes on the cleanup path:
    - lock row has investigation_id_ref (W13: conditional delete matches)
    - Action rows seeded and must be deleted (W4)
    - cap_date in manifest drives the correct cap key (C4)
    Injects a lock row (lock#pat-001) and the investigation row; seeds the Cognito user;
    seeds the cap row as expected residue.  Verifies:
    - lock row is deleted (cleanup-lock-row PASS)
    - investigation row is deleted (cleanup-investigation-row PASS)
    - Action rows deleted (cleanup-decision-action PASS, cleanup-issue-action PASS)
    - residue check passes (all must-be-gone keys absent; expected_residue cap row present)
    """
    import json as _json  # noqa: PLC0415
    import uuid as _uuid  # noqa: PLC0415
    import datetime as _dt  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415

    CAMPAIGN_ID = "MRD-2026-502"
    VIN = seed.vin(1)
    RUN_ID = "fi-loop-20261021T100000-ccddee00"
    STAGE = "staging"
    ACCOUNT = "123456789012"
    PATTERN_ID = "pat-cl3-lock-test"
    INV_ID = _uuid.uuid4().hex
    INV_FINDING_ID = f"find-inv-{INV_ID[:8]}"
    ISSUE_FINDING_ID = f"find-iss-{INV_ID[:8]}"
    DEC_ACTION_ID = f"act-dec-{INV_ID[:8]}"
    ISS_ACTION_ID = f"act-iss-{INV_ID[:8]}"
    # Must match ^thread-[0-9a-f]{16}$ (F2d2: _THREAD_ID_RE validates in cleanup)
    THREAD_ID = f"thread-{INV_ID[:16]}"
    # W6 fix: username is the email (recorded before AdminCreateUser)
    USERNAME = f"{_mod._LIVETEST_USER_PREFIX}{RUN_ID}-pe@example.invalid"
    LOCK_KEY = f"lock#{PATTERN_ID}"
    # C4 F3a: cap_date is today; the cap key is cap#<today>.
    CAP_DATE = _dt.date.today().isoformat()
    CAP_KEY = f"cap#{CAP_DATE}"

    with _mock_aws():
        with FiLoopWorld(auto_pump=True) as w:
            ddb_avx = w.internal("dynamodb")
            ddb_adp = w.internal("dynamodb", region="us-east-1")
            s3_adp = w.internal("s3", region="us-east-1")
            inv_table = _mod._INV_TABLE.format(stage=STAGE)

            # Insert investigation row (must be deleted by cleanup)
            ddb_avx.put_item(TableName=inv_table,
                             Item={"investigation_id": {"S": INV_ID},
                                   "status": {"S": "completed"}})

            # Insert lock row (must be deleted by cleanup — C4 fix)
            # W13 F3a: lock row must have investigation_id_ref matching INV_ID
            # so the conditional delete (investigation_id_ref = :inv_id) succeeds.
            ddb_avx.put_item(TableName=inv_table,
                             Item={"investigation_id": {"S": LOCK_KEY},
                                   "pattern_id": {"S": PATTERN_ID},
                                   "investigation_id_ref": {"S": INV_ID}})

            # Insert cap row (expected residue — must NOT be deleted)
            ddb_avx.put_item(TableName=inv_table,
                             Item={"investigation_id": {"S": CAP_KEY},
                                   "count": {"N": "1"}})

            # W4 F3a: Insert Action rows (must be deleted by cleanup)
            actions_table = _mod._ACTIONS_TABLE.format(stage=STAGE)
            ddb_avx.put_item(TableName=actions_table,
                             Item={"action_id": {"S": DEC_ACTION_ID},
                                   "action_kind": {"S": "record_engineering_decision"}})
            ddb_avx.put_item(TableName=actions_table,
                             Item={"action_id": {"S": ISS_ACTION_ID},
                                   "action_kind": {"S": "issue_recall"}})

            # Insert investigation Finding
            findings_table = _mod._FINDINGS_TABLE.format(stage=STAGE)
            ddb_avx.put_item(TableName=findings_table,
                             Item={"finding_id": {"S": INV_FINDING_ID},
                                   "finding_kind": {"S": "quality.investigation"},
                                   "subject_key": {"S": "quality/inv/1"}})

            # Insert recall Finding (campaign-scoped)
            recall_fkey = f"recall-{INV_ID[:8]}"
            ddb_avx.put_item(TableName=findings_table,
                             Item={
                                 "finding_id": {"S": recall_fkey},
                                 "finding_kind": {"S": _mod._RECALL_FINDING_KIND},
                                 "subject_key": {"S": f"{CAMPAIGN_ID}/parts_expected/1"},
                                 "fleet_id": {"S": seed.VIN_FLEET[1]},
                             })

            # Insert DDB issued-recall row
            issued_table = _mod._RECALL_CAMPAIGNS_ISSUED_DDB.format(stage=STAGE)
            try:
                ddb_adp.create_table(
                    TableName=issued_table,
                    KeySchema=[{"AttributeName": "campaign_id", "KeyType": "HASH"}],
                    AttributeDefinitions=[
                        {"AttributeName": "campaign_id", "AttributeType": "S"}],
                    BillingMode="PAY_PER_REQUEST",
                )
            except Exception:  # noqa: BLE001
                pass
            ddb_adp.put_item(TableName=issued_table,
                             Item={"campaign_id": {"S": CAMPAIGN_ID},
                                   "status": {"S": "issued"},
                                   # S2 fix: ADP writer always sets thread_id; add it here
                                   # so the cleanup's `thread_id = :our_tid` condition matches.
                                   "thread_id": {"S": THREAD_ID}})

            # Put S3 issued-recall object
            from scripts.tests.fi_rw_world.world import LAKE_BUCKET  # noqa: PLC0415
            s3_key = f"curated/engineering/recall_campaigns_issued/{CAMPAIGN_ID}.json"
            s3_adp.put_object(Bucket=LAKE_BUCKET, Key=s3_key, Body=b"{}")

            # Create VIN-list bucket (F2d2: step 7c requires it to exist)
            vin_bucket_cl3 = f"adp-{STAGE}-engineering-vins-{ACCOUNT}-us-east-1"
            try:
                s3_adp.create_bucket(Bucket=vin_bucket_cl3)
            except Exception:  # noqa: BLE001
                pass

            # Insert digital-thread row
            dt_table = _mod._DIGITAL_THREAD_TABLE.format(stage=STAGE)
            try:
                ddb_adp.create_table(
                    TableName=dt_table,
                    KeySchema=[
                        {"AttributeName": "thread_id", "KeyType": "HASH"},
                        {"AttributeName": "version", "KeyType": "RANGE"},
                    ],
                    AttributeDefinitions=[
                        {"AttributeName": "thread_id", "AttributeType": "S"},
                        {"AttributeName": "version", "AttributeType": "N"},
                    ],
                    BillingMode="PAY_PER_REQUEST",
                )
            except Exception:  # noqa: BLE001
                pass
            ddb_adp.put_item(TableName=dt_table,
                             Item={"thread_id": {"S": THREAD_ID},
                                   "version": {"N": "1"},
                                   "status": {"S": "decided"},
                                   "action_id": {"S": DEC_ACTION_ID}})

            # Seed Cognito user so real _delete_temp_user can delete it
            w.pool.admin_create_user({
                "UserPoolId": w.pool.pool_id,
                "Username": USERNAME,
                "MessageAction": "SUPPRESS",
                "UserAttributes": [
                    {"Name": "email", "Value": USERNAME},
                    {"Name": "email_verified", "Value": "true"},
                ],
            })

            manifest_data = {
                "run_id": RUN_ID, "stage": STAGE,
                "pattern_id": PATTERN_ID,
                "records": {
                    "users": [USERNAME],
                    "investigation_id": INV_ID,
                    "investigation_finding_id": INV_FINDING_ID,
                    "issue_finding_id": ISSUE_FINDING_ID,
                    "thread_id": THREAD_ID,
                    "thread_versions": [1],  # F2g: recorded by issue step
                    "campaign_id": CAMPAIGN_ID,
                    "issued_campaign_id": CAMPAIGN_ID,
                    "cap_date": CAP_DATE,          # C4 F3a
                    "decision_action_id": DEC_ACTION_ID,  # W4 F3a
                    "issue_action_id": ISS_ACTION_ID,     # W4 F3a
                    # S4 F3b: recorded VIN-list key (no actual VIN object; step 7c will FAIL, not crash)
                    "vin_s3_keys": [f"digital-thread/{STAGE}/{THREAD_ID}/v1/affected-vins.json"],
                },
                "account": ACCOUNT,
                "residue": {},
                "expected_vins": [VIN],
            }
            p = tmp_path / f"{RUN_ID}.json"
            p.write_text(_json.dumps(manifest_data))

            def _resolve_pool_id_stub(idp: Any) -> str:
                return w.pool.pool_id  # use the world's actual Cognito pool

            res_holder: list[Results] = []
            real_rc = _mod.Results

            class _Cap(real_rc):  # type: ignore[misc,valid-type]
                def __init__(self) -> None:
                    super().__init__()
                    res_holder.append(self)

            with (
                patch.object(_mod, "_manifest_path", lambda rid: str(p)),
                patch.object(_mod, "_resolve_pool_id", _resolve_pool_id_stub),
                # No _check_residue stub — C4 fix drives the real function.
                # No _delete_temp_user stub — W6 fix drives the real function.
                # F2g: stub reconcile since no real AWS in test.
                patch.object(_mod, "_run_reconcile_check", lambda *a, **kw: None),
                patch.object(_mod, "Results", _Cap),
            ):
                # W11 fix: set _SESSION to the guarded world session before calling main().
                # The allowlists are enforced throughout the cleanup part run.
                # This catches any boto3 call reachable from cleanup that is not
                # on its allowlist (e.g. s3.ListObjectsV2 was missing before F2f).
                _mod._SESSION = w.make_guarded_session("cleanup")
                rc = main(["--stage", STAGE, "--run-id", RUN_ID,
                           "--part", "cleanup", "--allow-writes"])

    assert res_holder, "Results not instantiated"
    res = res_holder[-1]
    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("cleanup-manifest-read") == "PASS", f"rows={res.rows}"
    assert labels.get("cleanup-investigation-row") == "PASS", f"rows={res.rows}"
    assert labels.get("cleanup-issued-ddb-row") == "PASS", f"rows={res.rows}"
    assert labels.get("cleanup-s3-issued-recall") == "PASS", f"rows={res.rows}"
    assert labels.get("cleanup-recall-findings") == "PASS", f"rows={res.rows}"
    # W13 F3a fix: lock row must be deleted with conditional check
    assert labels.get("cleanup-lock-row") == "PASS", (
        f"W13/C4: lock row must be conditionally deleted in cleanup; rows={res.rows}"
    )
    # W4 F3a fix: Action rows must be deleted
    assert labels.get("cleanup-decision-action") == "PASS", (
        f"W4 F3a: decision action must be deleted in cleanup; rows={res.rows}"
    )
    assert labels.get("cleanup-issue-action") == "PASS", (
        f"W4 F3a: issue action must be deleted in cleanup; rows={res.rows}"
    )
    # C4 F3a fix: residue check uses GetItem with cap_date from manifest
    assert labels.get("cleanup-residue-match") == "PASS", (
        f"C4 F3a: residue check failed; rows={res.rows}"
    )
    # W2 F3a fix: stamp written only on clean run
    assert labels.get("cleanup-completion-time") == "PASS", (
        f"W2 F3a: completion stamp must be written on clean run; rows={res.rows}"
    )
    assert rc == 0


def test_s2_cleanup_recovers_finding_id_from_investigation_row(tmp_path: Any) -> None:
    """S2: cleanup reads finding_id off the investigation row and deletes that Finding.

    If issue stops before recording investigation_finding_id in the manifest
    (e.g. poll timeout), cleanup must recover it from the investigation row.

    Break: removing the pre-delete read from step 2 means the Finding is never
    deleted, and this test would FAIL (cleanup-recover-inv-finding-id absent).
    """
    import json as _json_s2  # noqa: PLC0415
    import uuid as _uuid_s2  # noqa: PLC0415

    RUN_ID = "fi-loop-20261022T050000-s2000001"
    INV_ID = _uuid_s2.uuid4().hex
    INV_FINDING_ID = f"find-s2-{INV_ID[:8]}"

    manifest = {
        "run_id": RUN_ID,
        "stage": "staging",
        "account": "123456789012",
        "records": {
            "investigation_id": INV_ID,
            # No investigation_finding_id — simulates issue stopping before step 10.5
        },
        "pre_residue": {},
    }
    mf_path = str(tmp_path / f"{RUN_ID}.json")
    with open(mf_path, "w") as f:
        _json_s2.dump(manifest, f)
    import os as _os_s2  # noqa: PLC0415
    _os_s2.chmod(mf_path, 0o600)

    # Mock: investigation row contains finding_id
    _inv_row_reads: list[dict | None] = []
    _deleted_keys: list[dict] = []

    def _read_item(ddb: Any, table: str, key: dict) -> dict | None:
        if "findings" in table.lower():
            # Return the investigation Finding so GetItem confirms presence
            if key.get("finding_id", {}).get("S") == INV_FINDING_ID:
                return {"finding_id": INV_FINDING_ID}
        if "investigation" in table.lower() or "investigations" in table.lower():
            # First read (for S2 recovery): return row with finding_id
            # Second read (for confirmed-absent check): return None
            if not _inv_row_reads:
                _inv_row_reads.append({"investigation_id": INV_ID,
                                       "finding_id": INV_FINDING_ID})
                return _inv_row_reads[-1]
            return None  # already deleted
        return None

    def _delete_item(ddb: Any, table: str, key: dict, label: str) -> None:
        _deleted_keys.append({"table": table, "key": key})

    from unittest.mock import MagicMock  # noqa: PLC0415
    from unittest.mock import patch  # noqa: PLC0415

    ddb_mock = MagicMock()
    fake_cognito = MagicMock()
    fake_cognito.list_user_pools.return_value = {"UserPools": [
        {"Id": "us-west-2_TESTPL", "Name": "cms-staging-ui-users"}
    ]}
    fake_cognito.list_users.return_value = {"Users": []}

    with (
        patch.object(_mod, "_client", lambda svc, region, **kw: fake_cognito if svc == "cognito-idp" else ddb_mock),
        patch.object(_mod, "_read_ddb_item", _read_item),
        patch.object(_mod, "_delete_ddb_item", _delete_item),
        patch.object(_mod, "_write_manifest", lambda path, m: open(path, "w").write(_json_s2.dumps(m))),
        patch.object(_mod, "_read_manifest", lambda path: _json_s2.loads(open(path).read())),
        patch.object(_mod, "_manifest_path", lambda rid: mf_path),
        patch.object(_mod, "_resolve_pool_id", lambda idp_: "us-west-2_TESTPL"),
        patch.object(_mod, "_delete_temp_user", lambda *a, **kw: None),
        patch.object(_mod, "_check_residue", lambda *a, **kw: None),
    ):
        res = Results()
        _PARTS["cleanup"](res, stage="staging", run_id=RUN_ID, allow_writes=True)

    labels = {r[0]: r[1] for r in res.rows}
    # S2 fix: cleanup-recover-inv-finding-id PASS means the finding_id was recovered
    assert labels.get("cleanup-recover-inv-finding-id") == "PASS", (
        f"S2: cleanup must recover investigation_finding_id from the investigation row; "
        f"rows={res.rows}"
    )
    # The investigation row itself must also be deleted
    assert labels.get("cleanup-investigation-row") == "PASS", (
        f"S2: investigation row must be deleted; rows={res.rows}"
    )
    # The recovered Finding must be deleted (shows up in _deleted_keys)
    finding_deletes = [k for k in _deleted_keys if INV_FINDING_ID in str(k)]
    assert finding_deletes, (
        f"S2: investigation Finding {INV_FINDING_ID!r} must be deleted by cleanup; "
        f"deleted_keys={_deleted_keys}"
    )


# ── Signal test: held during cleanup ─────────────────────────────────────────

def test_cl4_signal_held_during_cleanup_delete(tmp_path: Any) -> None:
    """CL4: SIGTERM is held during _defer_signals_for_restore in cleanup.

    Sends SIGTERM from inside a stubbed _delete_ddb_item; verifies the signal
    is deferred (no immediate exit) and re-delivered after the context exits.
    """
    import os as _os  # noqa: PLC0415

    # Use os.kill test: verify that SIGTERM is deferred inside _defer_signals_for_restore
    # by testing the context manager directly.
    _mod._install_signal_handlers()
    received: list[int] = []
    with pytest.raises(SystemExit) as exc_info:
        with _mod._defer_signals_for_restore():
            _os.kill(_os.getpid(), signal.SIGTERM)
            # Should NOT have raised; signal is deferred
            received.append(42)  # sentinel if we get here
        # After context exits, deferred SIGTERM is re-delivered → SystemExit(143)
    assert received == [42], (
        "SIGTERM should be deferred inside _defer_signals_for_restore; "
        f"sentinel not set (signal fired before deferral): {received!r}"
    )
    assert exc_info.value.code == 143, (
        f"Expected SystemExit(143) from re-delivered SIGTERM; "
        f"got code={exc_info.value.code!r}"
    )


