# ── C2: approve checks must require status=="executed" in the response body ──

def _make_approve_declined_http(action_kind: str) -> Any:
    """Return a _http stub that gives 200 but status='declined' for the approve call."""
    def _http_stub(api_url: str, method: str, route: str, token: str,
                   body: Any, **_kw: Any) -> tuple[int, dict]:
        if method == "POST" and "approve" in route:
            return (200, {"status": "declined", "action_kind": action_kind,
                          "action_id": "act-declined-001", "target_ref": "thread-001"})
        # Any other call: reasonable fake
        return (202, {"investigation_id": "inv-001", "status": "pending"})
    return _http_stub


def _make_issue_client_factory(factory: "_FakeClientFactory") -> Any:
    """Wrap factory.make_client to also serve cloudformation as MagicMock."""
    def _client(service: str, region: str, **kw: Any) -> Any:
        if service == "cloudformation":
            return MagicMock()
        return factory.make_client(service, region, **kw)
    return _client


def _issue_read_ddb_item_with_pattern(
    pattern_id: str,
    investigation_finding: dict,
) -> Any:
    """Return a _read_ddb_item stub that supplies a valid pattern AND inv finding.

    Used in C2 tests to get past the W1 pre-POST pattern reread step.
    """
    def _stub(ddb: Any, table: str, key: dict) -> dict | None:
        if "fault-patterns" in table:
            return {
                "pattern_id": {"S": pattern_id},
                "failure_mode_id": {"S": "fm-susp-bushing-001"},
                "cohort_dimension": {"S": "supplier_lot"},
                "cohort_value": {"S": "SUP-A/LOT-001"},
                "affected_vins": {"L": [{"S": "1MRDNA0A4MA000001"}]},
                "affected_vins_count": {"N": "1"},
            }
        if "engineering-corpus" in table:
            return {
                "pk": {"S": "fm#fm-susp-bushing-001"},
                "component_name": {"S": "Front Suspension Bushing"},
            }
        if "avx-findings" in table:
            return investigation_finding
        return None
    return _stub


