# ── C9: fail-closed gates: window/precondition FAILs stop issue before first write

def _make_issue_patches_base(tmp_path: "Path", run_id: str,
                              factory: "_FakeClientFactory") -> list:
    """Return common patches for C9 issue tests (manifest at {run_id}-manifest.json).

    NOTE: use with contextlib.ExitStack, not with (*patches, ...): tuple unpacking.

    F6b: manifest now includes safe_failure_modes (required by issue; brief §F6b).
    _recheck_investigation_finding is stubbed to PASS so C9 tests that reach step 10.6
    don't fail on the re-check — they test precondition or window behaviour, not the
    re-check itself (b6/b7/b8 test that separately).
    """
    import json as _json  # noqa: PLC0415
    manifest_data = {
        "run_id": run_id, "stage": "staging", "pattern_id": "pat-001",
        "account": "123456789012", "records": {}, "pre_verdict": "passed",
        "expected_vins": ["VIN00000000000001"],
        # F6b: safe_failure_modes required by _part_issue
        "predicted_failure_mode_id": "fm-001",
        "safe_failure_modes": {"fm-001": "opt-recall-001"},
    }
    mf_file = tmp_path / f"{run_id}-manifest.json"
    mf_file.write_text(_json.dumps(manifest_data))
    return [
        patch.object(_mod, "_client", _make_issue_client_factory(factory)),
        patch.object(_mod, "_manifest_path",
                     lambda rid: str(tmp_path / f"{rid}-manifest.json")),
        patch.object(_mod, "_download_code_zip", lambda url: _make_zip_with_9_3_code()),
        patch.object(_mod, "_get_avx_api_url", lambda cfn, stage: "http://fake-avx/"),
        patch.object(_mod, "_resolve_pool_id", lambda idp: "us-west-2_FAKE"),
        patch.object(_mod, "_password_client", lambda idp, pid: "fake-client"),
        patch.object(_mod, "_create_temp_user",
                     lambda idp, pid, cid, rid, role: ("fake-user", "pw", "tok")),
        patch.object(_mod, "_delete_temp_user", lambda idp, pid, uname: None),
        # F6b: stub re-check to PASS so tests focused on other steps pass through
        patch.object(
            _mod, "_recheck_investigation_finding",
            lambda res, ddb_avx, ddb_adp, stage, fid, safe_fms: ("fm-001", "opt-recall-001", True),
        ),
    ]


def test_c9_maintenance_window_stops_before_post(tmp_path: "Path") -> None:
    """C9/m19 (red→fix): maintenance window at step-8 (pre-POST) stops the investigation POST.

    Uses a sequenced clock: step-2 window check sees ok_time (passes);
    step-8 window check sees bad_time (maintenance window, 02:30 UTC).
    After C9 fix + C9 manifest-first: reads manifest, step-2 passes, step-8
    fires and returns before POST.
    Catches m19 (if False: → step-8 check disabled → POST proceeds).
    """
    import contextlib  # noqa: PLC0415
    import datetime as _dt  # noqa: PLC0415

    ok_time = _dt.datetime(2026, 10, 22, 10, 0, 0, tzinfo=_dt.timezone.utc)
    bad_time = _dt.datetime(2026, 10, 22, 2, 30, 0, tzinfo=_dt.timezone.utc)

    call_n = [0]

    def _seq_clock() -> "_dt.datetime":
        call_n[0] += 1
        return ok_time if call_n[0] == 1 else bad_time

    factory = _FakeClientFactory()
    run_id = "test-run"
    patches = _make_issue_patches_base(tmp_path, run_id, factory)

    with contextlib.ExitStack() as stack:
        for p in patches:
            stack.enter_context(p)
        stack.enter_context(patch.object(_mod, "_utc_now", _seq_clock))
        res = Results()
        _PARTS["issue"](res, stage="staging", run_id=run_id, allow_writes=True)

    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("issue-pre-post-window") == "FAIL", (
        f"C9/m19: expected FAIL on issue-pre-post-window; rows: {labels}"
    )
    assert "issue-post-investigation" not in labels, (
        f"C9/m19: issue reached POST despite maintenance window; rows: {labels}"
    )


