def test_c9_bad_draft_stops_issue_recall(tmp_path: "Path") -> None:
    """C9/m21 (red→fix): _check_ddb_draft_row FAIL stops issue_recall approve.

    With wrong thread_id in the draft row, draft check FAILs; after C9 fix
    issue_recall is NOT approved.
    Catches m21 (ok = True → draft check always passes, issue_recall proceeds).
    """
    import contextlib  # noqa: PLC0415

    run_id = "test-run"
    factory = _FakeClientFactory()
    patches = _make_issue_patches_base(tmp_path, run_id, factory)

    def _http_stub(api_url: str, method: str, route: str, token: str,
                   body: Any, **_kw: Any) -> tuple[int, dict]:
        if method == "POST" and "approve" in route:
            return (200, {"status": "executed",
                          "action_kind": "record_engineering_decision",
                          "action_id": "act-001",
                          "target_ref": "THREAD-REAL"})
        return (202, {"investigation_id": "inv-001"})

    # Draft row has WRONG thread_id → _check_ddb_draft_row should FAIL
    def _read_ddb_stub(ddb: Any, table: str, key: dict) -> dict | None:
        if "fault-patterns" in table:
            # W1/C9 fix: return a valid pattern row so execution reaches the draft check
            # (and beyond) if gates are bypassed; needed to isolate the draft thread_id check.
            return {
                "pattern_id": "pat-001",
                "failure_mode_id": "fm-001",
                "cohort_dimension": "supplier_lot",
                "cohort_value": "SUP-A/LOT-001",
            }
        if "engineering-corpus" in table:
            return {"pk": "fm#fm-001", "component_name": "Test"}
        if "recall-campaigns-issued" in table:
            # m21b fix: return UNWRAPPED values.  _read_ddb_item already unwraps DDB
            # AttributeValue wrappers; returning wrapped values here caused the status
            # compare to fail first ({"S":"draft"} != "draft"), hiding the thread_id check.
            return {
                "campaign_id": "MRD-2026-001",  # valid shape for _CAMPAIGN_ID_RE
                "status": "draft",               # ← unwrapped; status compare passes
                "thread_id": "THREAD-WRONG",     # ← unwrapped; thread_id compare fails (m21b)
            }
        if "avx-findings" in table:
            # Investigation finding for step 11 — include hardware_recall option
            return {
                "finding_id": {"S": "inv-find-001"},
                "recommended_action": {"M": {
                    "action_kind": {"S": "record_engineering_decision"},
                    "parameters": {"M": {"option_id": {"S": "opt-001"}}},
                }},
                "evidence": {"L": [{"M": {
                    "kind": {"S": "quality.options"},
                    "value": {"L": [{"M": {
                        "remedy_option_id": {"S": "opt-001"},
                        "remedy_type": {"S": "hardware_recall"},
                        "recommended": {"BOOL": True},
                    }}]},
                }}]},
            }
        return None

    def _find_qi_stub(ddb: Any, stage: str, thread_id: str) -> dict:
        return {
            "finding_id": {"S": "qi-find-001"},
            "finding_kind": {"S": "quality.issue"},
            "subject_key": {"S": f"{thread_id}/issue"},
            "recommended_action": {"M": {
                "action_kind": {"S": "issue_recall"},
                "parameters": {"M": {
                    "thread_id": {"S": thread_id},
                    "draft_id": {"S": "MRD-2026-001"},  # valid shape
                }},
            }},
            "evidence": {"L": []},
        }

    with contextlib.ExitStack() as stack:
        for p in patches:
            stack.enter_context(p)
        stack.enter_context(patch.object(_mod, "_utc_now", _safe_issue_time))
        stack.enter_context(patch.object(_mod, "_http", _http_stub))
        stack.enter_context(patch.object(
            _mod, "_poll_investigation",
            lambda url, inv_id, tok: {"status": "completed", "finding_id": "inv-find-001"}
        ))
        stack.enter_context(patch.object(_mod, "_read_ddb_item", _read_ddb_stub))
        stack.enter_context(patch.object(_mod, "_find_quality_issue_finding", _find_qi_stub))
        stack.enter_context(patch.object(_mod, "_check_ddb_issued_row", lambda *a, **k: False))
        stack.enter_context(patch.object(_mod, "_check_s3_issued_recall", lambda *a, **k: False))
        stack.enter_context(patch.object(_mod, "_check_thread_versions", lambda *a, **k: []))
        res = Results()
        _PARTS["issue"](res, stage="staging", run_id=run_id, allow_writes=True)

    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("issue-ddb-draft") == "FAIL", (
        f"C9/m21: expected issue-ddb-draft FAIL (wrong thread_id); rows: {labels}"
    )
    assert "issue-issue-recall-approve" not in labels, (
        f"C9/m21: issue_recall was approved despite failed draft check; rows: {labels}"
    )


