# ── C10: K3 — _pick_pattern must validate hardware_recall option criteria ────

def _corpus_with_options(options: list[dict], *, do_not_drive: bool = False) -> dict:
    """Return a DDB low-level corpus item with embedded options.

    C10 fix: do_not_drive is a failure-mode field (top level), not an option field.
    ADP writer 87d3025b handler.py:976 reads failure_mode.get("do_not_drive").

    F6a fix: added cause_dimension, component_id, symptom_codes so _rules_match_failure_mode
    can find and classify this FM (required by new pick rules 1-3).
    """
    def _wrap_opt(o: dict) -> dict:
        m: dict = {}
        for k, v in o.items():
            if isinstance(v, bool):
                m[k] = {"BOOL": v}
            elif isinstance(v, (int, float)):
                m[k] = {"N": str(v)}
            else:
                m[k] = {"S": str(v)}
        return {"M": m}
    return {
        "pk": {"S": "fm#fm-susp-bushing-001"},
        "failure_mode_id": {"S": "fm-susp-bushing-001"},
        "component_name": {"S": "Front Suspension Bushing"},
        "component_id": {"S": "suspension_bushing"},
        # F6a: cause_dimension="supplier_lot" satisfies the safe rule (rule 3)
        "cause_dimension": {"S": "supplier_lot"},
        # F6a: symptom_codes with P1AB prefix so _rules_match_failure_mode picks this FM
        "symptom_codes": {"L": [{"S": "P1AB0"}, {"S": "P1AB1"}]},
        "do_not_drive": {"BOOL": do_not_drive},   # C10 fix: on failure mode, not option
        "park_outside": {"BOOL": False},
        "options": {"L": [_wrap_opt(o) for o in options]},
    }


