def test_c10_pick_pattern_rejects_zero_managed_vins() -> None:
    """C10 (red→fix): _pick_pattern skips a candidate with empty managed × lot.

    Without athena, the proxy is the affected_vins list.  Catches the mutant that
    replaces the per-candidate managed × lot check with affected_vins_count: the
    pattern below has affected_vins_count=5 (non-zero) but affected_vins=[] (empty).
    The correct code sees the empty list and skips; the mutant accepts because
    affected_vins_count > 0.
    """
    corpus_ok = _corpus_with_options([{
        "remedy_option_id": "opt-recall-001",
        "remedy_type": "hardware_recall",
        "lead_time_weeks": 8,
    }])  # do_not_drive=False at top level via _corpus_with_options default
    # Pattern: affected_vins_count > 0 but affected_vins list is empty — proxy = 0
    # F6a: must have pattern_group_id == pattern_id (rule 2) and code_family (rule 3)
    pattern_no_vins = [{
        "pattern_id": {"S": "pat-supplier-lot-001"},
        "pattern_group_id": {"S": "pat-supplier-lot-001"},  # F6a: rule 2 requires this
        "candidate_rank": {"N": "1"},
        "code_family": {"S": "P1AB"},                       # F6a: matches corpus symptom codes
        "cohort_dimension": {"S": "supplier_lot"},
        "cohort_value": {"S": "SUP-A/LOT-001"},
        "affected_vins": {"L": []},
        "affected_vins_count": {"N": "5"},  # mutant would accept this; correct code skips
    }]
    ddb = _ddb_stub(pattern_items=pattern_no_vins, corpus_item=corpus_ok)
    res = Results()
    # No athena → fallback to affected_vins list length
    pattern_row, _, _, _, _ = _mod._pick_pattern(res, ddb, "staging")
    labels = {r[0]: r[1] for r in res.rows}
    assert pattern_row is None, (
        f"C10: _pick_pattern should skip empty managed × lot (no VINs in affected_vins); "
        f"got {pattern_row!r}"
    )
    assert labels.get("pre-pattern-pick") == "FAIL", (
        f"C10: expected FAIL when no managed VINs; rows: {labels}"
    )


