# ── S3: manifest remedy_option_id → issue approves that exact option ─────────

def test_s3_issue_approves_manifest_option_not_first_option(tmp_path: Any) -> None:
    """S3/F6b (red→fix): _part_issue approves the option from safe_failure_modes, not
    the first hardware_recall option from the Finding.

    F6b update: the option is now determined by _recheck_investigation_finding which
    reads safe_failure_modes[chosen_fm_id] from the manifest. This tests that:
    - The decision approve uses the option from safe_failure_modes for the chosen FM.
    - A mutant that takes the FIRST hardware_recall option from the Finding instead
      of the safe_failure_modes value would approve opt-first-recall, not opt-specific-recall.
    """
    import json as _json_s3  # noqa: PLC0415

    MANIFEST_FM_ID = "fm-specific-001"
    MANIFEST_OPT_ID = "opt-specific-recall"   # the one in safe_failure_modes
    FIRST_OPT_ID = "opt-first-recall"         # first in Finding — mutant would use this
    run_id = "fi-loop-20261021T120000-s3test00"

    manifest_data = {
        "run_id": run_id, "stage": "staging",
        "part": "pre", "account": "123456789012",
        "pattern_id": "pat-supp-s3-001",
        # F6b: safe_failure_modes maps chosen FM → expected option
        "safe_failure_modes": {MANIFEST_FM_ID: MANIFEST_OPT_ID},
        "pre_verdict": "passed",
        "expected_vins": ["VIN00000000000001"],
        "records": {},
    }
    p = tmp_path / f"{run_id}.json"
    p.write_text(_json_s3.dumps(manifest_data))

    approve_bodies: list[dict] = []

    def _fake_http(url: str, method: str, path: str, token: str,
                   body: dict | None = None) -> tuple[int, dict]:
        if method == "POST" and "approve" in path:
            approve_bodies.append(body or {})
            return 200, {
                "status": "executed",
                "action_kind": (body or {}).get("action_kind", ""),
                "action_id": "act-s3-001",
                "target_ref": "thread-s3-001",
            }
        if method == "POST" and "investigations" in path:
            return 202, {"investigation_id": "inv-s3-001"}
        if method == "GET" and "investigations" in path:
            return 200, {"status": "completed", "finding_id": "find-s3-inv-001"}
        return 200, {}

    def _fake_client(svc: str, reg: str, **kw: Any) -> Any:
        m = MagicMock()
        if svc == "cognito-idp":
            m.list_user_pools.return_value = {
                "UserPools": [{"Id": "us-west-2_S3TEST", "Name": "cms-staging-ui-users"}]
            }
            m.list_user_pool_clients.return_value = {
                "UserPoolClients": [{"ClientId": "cid-s3-001"}]
            }
            m.describe_user_pool_client.return_value = {
                "UserPoolClient": {"ExplicitAuthFlows": ["ALLOW_USER_PASSWORD_AUTH"]}
            }
            m.admin_create_user.return_value = {
                "User": {"Username": "sub-s3-001", "Attributes": []}
            }
            m.admin_set_user_password.return_value = {}
            m.admin_add_user_to_group.return_value = {}
            m.admin_delete_user.return_value = {}
            m.list_users.return_value = {"Users": []}
            m.initiate_auth.return_value = {"AuthenticationResult": {"IdToken": "tok-s3"}}
        elif svc == "dynamodb":
            def _get_item_fn(**kw2: Any) -> dict:
                key = kw2.get("Key", {})
                if "pattern_id" in key:
                    return {"Item": {
                        "pattern_id": {"S": "pat-supp-s3-001"},
                        "cohort_dimension": {"S": "supplier_lot"},
                    }}
                return {}
            m.get_item.side_effect = _get_item_fn
            m.scan.return_value = {"Items": []}
        elif svc == "scheduler":
            m.list_schedules.return_value = {"Schedules": []}
        elif svc == "cloudformation":
            m.describe_stacks.return_value = {
                "Stacks": [{"Outputs": [
                    {"OutputKey": "AVXApiUrl", "OutputValue": "https://api.example.com/"}
                ]}]
            }
        return m

    # F6b: stub re-check to return the specific option from safe_failure_modes.
    # A mutant that skips this and takes opt-first-recall from the Finding directly
    # would fail the assertion below.
    def _fake_recheck(
        res: Any, ddb_avx: Any, ddb_adp: Any, stage: str,
        finding_id: str, safe_fms: dict,
    ) -> tuple:
        # Simulates: investigation chose MANIFEST_FM_ID; safe_fms has opt-specific-recall;
        # corpus passes safe rule; Finding has opt-specific-recall in quality.options.
        _mod.check(res, "issue-recheck-finding-read", True,
                   f"finding root_cause failure_mode_id={MANIFEST_FM_ID!r}")
        _mod.check(res, "issue-recheck-fm-in-safe", True,
                   f"chosen fm in safe_failure_modes; option_id={MANIFEST_OPT_ID!r}")
        _mod.check(res, "issue-recheck-corpus-safe", True,
                   f"corpus still safe; option_id={MANIFEST_OPT_ID!r}")
        _mod.check(res, "issue-recheck-finding-option", True,
                   f"Finding quality.options has {MANIFEST_OPT_ID!r} (hardware_recall)")
        return (MANIFEST_FM_ID, MANIFEST_OPT_ID, True)

    with (
        patch.object(_mod, "_manifest_path", lambda rid: str(p)),
        patch.object(_mod, "_client", _fake_client),
        patch.object(_mod, "_http", _fake_http),
        patch.object(_mod, "_recheck_investigation_finding", _fake_recheck),
        patch.object(_mod, "_utc_now",
                     lambda: __import__("datetime").datetime(
                         2026, 10, 21, 10, 0, tzinfo=__import__("datetime").timezone.utc)),
        patch.object(_mod, "_check_tier2_code",
                     lambda res, lam, fn: (_mod.check(res, "pre-tier2-code-readers", True, "ok"), True)[1]),
        patch.object(_mod, "_check_recall_table_exists",
                     lambda res, glue, stg: (_mod.check(res, "pre-recall-table", True, "ok"), True)[1]),
        patch.object(_mod, "_check_view_sql_unions_issued",
                     lambda res, glue, stg: (_mod.check(res, "pre-view-sql", True, "ok"), True)[1]),
        patch.object(_mod, "_check_esm_enabled",
                     lambda res, lam, stg, reg: (_mod.check(res, "pre-esm-enabled", True, "ok"), True)[1]),
        patch.object(_mod, "_check_dlq_empty",
                     lambda res, sqs, stg: (_mod.check(res, "pre-dlq-empty", True, "ok"), True)[1]),
        patch.object(_mod, "_check_no_open_livetest",
                     lambda res, idp, stg: (_mod.check(res, "pre-no-open-livetest", True, "ok"), True)[1]),
        patch.object(_mod, "_schedule_guard", lambda *a, **kw: None),
        patch.object(_mod, "_get_avx_api_url", lambda cfn, stg: "https://api.example.com/"),
        patch.object(_mod, "_POLL_SLEEP_S", 0.0),
    ):
        res = Results()
        _mod._part_issue(res, stage="staging", run_id=run_id, allow_writes=True)

    # The decision approve must use MANIFEST_OPT_ID (from safe_failure_modes), not FIRST_OPT_ID
    decision_approves = [b for b in approve_bodies
                         if b.get("action_kind") == "record_engineering_decision"]
    assert decision_approves, (
        f"S3/F6b: no record_engineering_decision approve found; bodies={approve_bodies!r}"
    )
    used_option_id = decision_approves[0].get("parameters", {}).get("option_id", "")
    assert used_option_id == MANIFEST_OPT_ID, (
        f"S3/F6b: expected option_id={MANIFEST_OPT_ID!r} from safe_failure_modes; "
        f"got {used_option_id!r}. "
        f"Mutant would use the first Finding option ({FIRST_OPT_ID!r}) instead"
    )


# ── W1: re-read pattern from DDB right before investigation POST ─────────────

def test_w1_pattern_reread_before_post(tmp_path: "Path") -> None:
    """W1 (red→fix): pattern_id is re-read from DDB right before investigation POST.

    The manifest may be days old; the pattern row must be re-read (ConsistentRead)
    right before the POST to verify it still exists and is still supplier_lot.
    If the pattern is not found, issue returns without POST.
    """
    import contextlib  # noqa: PLC0415
    import json as _json  # noqa: PLC0415

    factory = _FakeClientFactory()
    run_id = "test-run"

    manifest_data = {"run_id": run_id, "stage": "staging", "pre_verdict": "passed",
                     "pattern_id": "pat-no-longer-exists",
                     "account": "123456789012", "expected_vins": ["VIN00000000000001"], "records": {},
                     "safe_failure_modes": {"fm-001": "opt-recall-001"}}
    (tmp_path / f"{run_id}-manifest.json").write_text(_json.dumps(manifest_data))

    # DDB stub that returns None for fault-patterns (pattern was deleted)
    def _missing_pattern_ddb_get(ddb: Any, table: str, key: dict) -> dict | None:
        if "fault-patterns" in table:
            return None  # pattern no longer exists
        return None

    with contextlib.ExitStack() as stack:
        stack.enter_context(patch.object(_mod, "_client", _make_issue_client_factory(factory)))
        stack.enter_context(patch.object(
            _mod, "_manifest_path", lambda rid: str(tmp_path / f"{rid}-manifest.json")
        ))
        stack.enter_context(patch.object(_mod, "_utc_now", _safe_issue_time))
        stack.enter_context(patch.object(_mod, "_download_code_zip", lambda url: _make_zip_with_9_3_code()))
        stack.enter_context(patch.object(_mod, "_get_avx_api_url", lambda cfn, stage: "http://fake-avx/"))
        stack.enter_context(patch.object(_mod, "_resolve_pool_id", lambda idp: "us-west-2_FAKE"))
        stack.enter_context(patch.object(_mod, "_password_client", lambda idp, pid: "fake-client"))
        stack.enter_context(patch.object(
            _mod, "_create_temp_user",
            lambda idp, pid, cid, rid, role: ("fake-user", "pw", "tok")
        ))
        stack.enter_context(patch.object(_mod, "_delete_temp_user", lambda idp, pid, uname: None))
        stack.enter_context(patch.object(_mod, "_read_ddb_item", _missing_pattern_ddb_get))
        res = Results()
        _PARTS["issue"](res, stage="staging", run_id=run_id, allow_writes=True)

    labels = {r[0]: r[1] for r in res.rows}
    # W1 fix: a pre-POST pattern reread step should exist and FAIL (pattern not found)
    assert "issue-pre-post-pattern-reread" in labels, (
        f"W1: expected issue-pre-post-pattern-reread label (reread before POST); "
        f"rows: {labels}"
    )
    assert labels.get("issue-pre-post-pattern-reread") == "FAIL", (
        f"W1: expected FAIL on issue-pre-post-pattern-reread when pattern not found; "
        f"rows: {labels}"
    )
    assert "issue-post-investigation" not in labels, (
        f"W1: POST investigation must not happen when pattern reread fails; rows: {labels}"
    )


def test_w1_pattern_reread_cohort_dimension_must_be_supplier_lot(tmp_path: "Path") -> None:
    """W1/n15 (red→fix): pattern reread fails when cohort_dimension != supplier_lot.

    The manifest may reference a stale pattern whose cohort_dimension has changed.
    The pre-POST reread must check that it is still supplier_lot; if not, issue returns
    before POST.  Catches n15 (supplier_lot check removed → wrong-dimension pattern passes).
    """
    import contextlib  # noqa: PLC0415
    import json as _json  # noqa: PLC0415

    factory = _FakeClientFactory()
    run_id = "test-run-w1-cdim"

    manifest_data = {"run_id": run_id, "stage": "staging", "pre_verdict": "passed",
                     "pattern_id": "pat-cdim-changed",
                     "account": "123456789012", "expected_vins": ["VIN00000000000001"], "records": {},
                     "safe_failure_modes": {"fm-001": "opt-recall-001"}}
    (tmp_path / f"{run_id}-manifest.json").write_text(_json.dumps(manifest_data))

    def _wrong_cdim_pattern_ddb_get(ddb: Any, table: str, key: dict) -> dict | None:
        if "fault-patterns" in table:
            # Pattern exists but cohort_dimension changed from supplier_lot to "model"
            return {
                "pattern_id": "pat-cdim-changed",
                "failure_mode_id": "fm-001",
                "cohort_dimension": "model",        # ← NOT supplier_lot
                "cohort_value": "Azimuth/2023",
            }
        return None

    with contextlib.ExitStack() as stack:
        stack.enter_context(patch.object(_mod, "_client", _make_issue_client_factory(factory)))
        stack.enter_context(patch.object(
            _mod, "_manifest_path", lambda rid: str(tmp_path / f"{rid}-manifest.json")
        ))
        stack.enter_context(patch.object(_mod, "_utc_now", _safe_issue_time))
        stack.enter_context(patch.object(_mod, "_download_code_zip", lambda url: _make_zip_with_9_3_code()))
        stack.enter_context(patch.object(_mod, "_get_avx_api_url", lambda cfn, stage: "http://fake-avx/"))
        stack.enter_context(patch.object(_mod, "_resolve_pool_id", lambda idp: "us-west-2_FAKE"))
        stack.enter_context(patch.object(_mod, "_password_client", lambda idp, pid: "fake-client"))
        stack.enter_context(patch.object(
            _mod, "_create_temp_user",
            lambda idp, pid, cid, rid, role: ("fake-user", "pw", "tok")
        ))
        stack.enter_context(patch.object(_mod, "_delete_temp_user", lambda idp, pid, uname: None))
        stack.enter_context(patch.object(_mod, "_read_ddb_item", _wrong_cdim_pattern_ddb_get))
        res = Results()
        _PARTS["issue"](res, stage="staging", run_id=run_id, allow_writes=True)

    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("issue-pre-post-pattern-reread") == "FAIL", (
        f"W1/n15: expected FAIL on issue-pre-post-pattern-reread when "
        f"cohort_dimension='model' (not supplier_lot); rows: {labels}"
    )
    assert "issue-post-investigation" not in labels, (
        f"W1/n15: POST investigation must not happen when supplier_lot check fails; rows: {labels}"
    )


# ── W2 (m33): _check_s3_issued_recall must return False on SSE-KMS FAIL ──────

def test_w2_sse_kms_fail_returns_false() -> None:
    """W2/m33 (red→fix): _check_s3_issued_recall returns False when SSE is not aws:kms.

    Currently returns True after the SSE-KMS check regardless of the result (S6).
    Fix: return sse_ok instead of True.
    Catches m33 (sse_ok = True → check always passes).
    """
    s3 = MagicMock()
    # HeadObject returns a response with no SSE (not aws:kms)
    s3.head_object.return_value = {
        "ContentLength": 1234,
        "ServerSideEncryption": "AES256",  # not aws:kms → sse_ok = False
    }
    res = Results()
    result = _mod._check_s3_issued_recall(res, s3, "staging", "123456789012", "MRD-2026-001")
    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("issue-s3-sse-kms") == "FAIL", (
        f"W2: expected FAIL on issue-s3-sse-kms when SSE=AES256; rows: {labels}"
    )
    assert result is False, (
        f"W2: _check_s3_issued_recall must return False when SSE-KMS FAIL; "
        f"got {result!r}"
    )


def test_w2_sse_kms_pass_returns_true() -> None:
    """W2: _check_s3_issued_recall returns True when SSE is aws:kms."""
    s3 = MagicMock()
    s3.head_object.return_value = {
        "ContentLength": 1234,
        "ServerSideEncryption": "aws:kms",
    }
    res = Results()
    result = _mod._check_s3_issued_recall(res, s3, "staging", "123456789012", "MRD-2026-001")
    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("issue-s3-sse-kms") == "PASS", (
        f"W2: expected PASS on issue-s3-sse-kms when SSE=aws:kms; rows: {labels}"
    )
    assert result is True, (
        f"W2: _check_s3_issued_recall should return True when SSE-KMS passes; "
        f"got {result!r}"
    )


# ── C3: Cognito email-type usernames ──────────────────────────────────────────

def _make_fakepool_client(pool: Any) -> Any:
    """Wrap FakeUserPool as a boto3-style IDP client (kwargs → p-dict)."""
    class _PoolClient:
        def list_user_pools(self, **kw: Any) -> dict:
            return {"UserPools": [{"Id": pool.pool_id, "Name": "cms-staging-ui-users"}]}

        def list_users(self, **kw: Any) -> dict:
            return pool.list_users(kw)

        def admin_create_user(self, **kw: Any) -> dict:
            return pool.admin_create_user(kw)

        def admin_set_user_password(self, **kw: Any) -> dict:
            return pool.admin_set_user_password(kw)

        def admin_add_user_to_group(self, **kw: Any) -> dict:
            return pool.admin_add_user_to_group(kw)

        def admin_delete_user(self, **kw: Any) -> dict:
            return pool.admin_delete_user(kw)

        def initiate_auth(self, **kw: Any) -> dict:
            return pool.initiate_auth(kw)

    return _PoolClient()


def _make_fakepool() -> Any:
    """Return a fresh FakeUserPool with a minimal clock."""
    import datetime as _dtx  # noqa: PLC0415
    from scripts.tests.fi_rw_world.cognito import FakeUserPool  # noqa: PLC0415

    class _Clk:
        def now(self) -> _dtx.datetime:
            return _dtx.datetime(2026, 10, 21, 10, 0, 0)
        def epoch(self) -> float:
            return 1729512000.0

    return FakeUserPool(_Clk())


def test_c3_create_user_username_and_email_attr_are_email_format() -> None:
    """C3 (red): _create_temp_user must pass email-format string as Username and email attr.

    Staging pool has UsernameAttributes=[email]; AdminCreateUser Username is the email.
    Username must be 'livetest-fi-loop-<run>-<role>@example.invalid'.
    Return value (first element) must equal that email so cleanup can find the user.
    Catches m06 (email attr carries a random non-livetest address).
    """
    created_username: list[str] = []
    created_attrs: list[list] = []

    class _FakeIdp:
        def admin_create_user(self, **kw: Any) -> dict:
            created_username.append(kw["Username"])
            created_attrs.append(kw.get("UserAttributes", []))
            return {"User": {"Username": "sub-uuid-001", "Attributes": []}}

        def admin_set_user_password(self, **kw: Any) -> None:
            pass

        def admin_add_user_to_group(self, **kw: Any) -> None:
            pass

        def initiate_auth(self, **kw: Any) -> dict:
            return {"AuthenticationResult": {"IdToken": "tok"}}

    email, _pw, _tok = _mod._create_temp_user(
        _FakeIdp(), "pool", "client", "testrun", role="pe"
    )
    assert created_username, "admin_create_user not called"
    uname = created_username[0]
    assert "@" in uname and uname.endswith("@example.invalid"), (
        f"C3: Username={uname!r} must end with @example.invalid"
    )
    assert uname.startswith("livetest-fi-loop-"), (
        f"C3: Username={uname!r} must start with livetest-fi-loop-"
    )
    attrs_map = {a["Name"]: a["Value"] for a in created_attrs[0]}
    assert attrs_map.get("email") == uname, (
        f"C3: email attr={attrs_map.get('email')!r} must equal Username={uname!r}"
    )
    assert email == uname, (
        f"C3: return[0]={email!r} must equal the email passed to AdminCreateUser={uname!r}"
    )


def test_c3_fakepool_rejects_non_email_username() -> None:
    """C3 (red): FakeUserPool.admin_create_user must reject a non-email-format Username.

    The live pool has UsernameAttributes=[email]; AdminCreateUser with a non-email
    Username raises InvalidParameterException.  Adding this guard to FakeUserPool
    makes the test suite catch the email-format omission.
    """
    pool = _make_fakepool()
    with pytest.raises(Exception) as exc_info:
        pool.admin_create_user({
            "UserPoolId": pool.pool_id,
            "Username": "livetest-fi-loop-testrun-pe",  # not email format
            "MessageAction": "SUPPRESS",
            "UserAttributes": [
                {"Name": "email", "Value": "livetest-fi-loop-testrun-pe"},
                {"Name": "email_verified", "Value": "true"},
            ],
        })
    err_str = str(exc_info.value).lower()
    assert "invalid" in err_str or "email" in err_str or "parameter" in err_str, (
        f"C3: expected InvalidParameterException for non-email Username; got {exc_info.value!r}"
    )


def test_c3_no_open_livetest_via_fakepool_detects_leftover_email() -> None:
    """C3 (red): _check_no_open_livetest via FakeUserPool finds leftover livetest email.

    After the C3 fix the check reads email attributes, not Username.  Using a real
    FakeUserPool (which applies the filter) ensures the email filter (not a Username
    prefix check) drives detection.
    Catches m07 (filter prefix changed to 'zz-no-such-prefix-': FakeUserPool returns 0
    users → check incorrectly passes).
    """
    pool = _make_fakepool()
    leftover_email = "livetest-fi-loop-prev-run-pe@example.invalid"
    pool.admin_create_user({
        "UserPoolId": pool.pool_id,
        "Username": leftover_email,
        "MessageAction": "SUPPRESS",
        "UserAttributes": [
            {"Name": "email", "Value": leftover_email},
            {"Name": "email_verified", "Value": "true"},
        ],
    })
    # Set password so the user is CONFIRMED
    pool.admin_set_user_password({
        "UserPoolId": pool.pool_id,
        "Username": leftover_email,
        "Password": "Lv1234567890!9Qz",
        "Permanent": True,
    })

    idp = _make_fakepool_client(pool)
    res = Results()
    _mod._check_no_open_livetest(res, idp, "staging")
    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("pre-no-open-livetest") == "FAIL", (
        f"C3: expected FAIL when leftover email user in FakeUserPool; "
        f"got {labels.get('pre-no-open-livetest')!r}; rows={res.rows}"
    )


def test_c3_cleanup_confirm_absent_uses_email_filter() -> None:
    """C3 (red): cleanup confirm-absent must use email filter, not username filter.

    FakeUserPool assigns a UUID sub as Username; filtering by 'username = <email>'
    never matches (sub ≠ email), so the old filter was vacuous.
    After the fix, cleanup uses 'email = <email>' which correctly detects a
    user still present after a failed delete.
    Catches m08 (ok = True: confirm always passes regardless of user presence).
    """
    pool = _make_fakepool()
    test_email = "livetest-fi-loop-testrun-pe@example.invalid"
    pool.admin_create_user({
        "UserPoolId": pool.pool_id,
        "Username": test_email,
        "MessageAction": "SUPPRESS",
        "UserAttributes": [
            {"Name": "email", "Value": test_email},
            {"Name": "email_verified", "Value": "true"},
        ],
    })

    # email filter finds the user (user is still present)
    result_email = pool.list_users({
        "UserPoolId": pool.pool_id,
        "Filter": f'email = "{test_email}"',
    })
    assert len(result_email.get("Users", [])) == 1, (
        f"C3: email filter must find 1 user; got {result_email.get('Users')}"
    )
    # username filter with the email value finds nothing (sub ≠ email)
    result_user = pool.list_users({
        "UserPoolId": pool.pool_id,
        "Filter": f'username = "{test_email}"',
    })
    assert len(result_user.get("Users", [])) == 0, (
        f"C3: username filter with email value should return 0 (sub ≠ email); "
        f"got {result_user.get('Users')} — old filter was vacuous"
    )


def test_c3_cleanup_confirm_detects_user_still_present(tmp_path: Any) -> None:
    """C3 (m08): cleanup-user FAIL when user still present after delete.

    Seeds a user in FakeUserPool, patches _delete_temp_user to do nothing,
    runs cleanup.  After the C3 fix, the email filter returns 1 user → FAIL.
    Mutant m08 (ok = True) makes the confirm vacuous → PASS (wrong).
    """
