def test_f3a_cap_key_from_manifest_cap_date(tmp_path: Any) -> None:
    """F3a C4 (red): cleanup uses records['cap_date'] not date.today() for cap row key.

    Mutant: change `records.get("cap_date")` to `date.today().isoformat()`.
    With a manifest cap_date = yesterday and cap row for yesterday in DDB,
    cleanup-residue-match must PASS.  Under the mutant it uses today's key,
    finds no matching row, and reports expected residue absent → FAIL.
    """
    import json as _json  # noqa: PLC0415
    import datetime as _ddt  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415

