def test_f3a_s10_rerun_uses_recorded_finding_ids(tmp_path: Any) -> None:
    """F3a S10 (red): cleanup re-run must only delete the originally recorded finding_ids.

    Mutant: remove the `if recorded_fids:` branch so re-runs always re-query by campaign.
    Set up: run 1 deletes original finding F1; afterwards, a new finding F2 (same campaign_id)
    is added to DDB.  Run 2 re-reads the manifest and must only re-delete F1, not F2.
    Under the mutant, run 2 queries and deletes F2 as well.
    """
    import json as _json  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415

    STAGE = "staging"
