def test_w7_run_before_issue_completion_fails(tmp_path: Any) -> None:
    """W7: a recall run started BEFORE issue_completed_at must not count.

    Catches m28: if r.get('started_at', '') > issue_completed_at → if True:
    (all runs match, including ones before issue completion).

    Clock fix: pin FiLoopWorld's start to 2026-10-21T12:00Z so the world always
    seeds the scheduled run at 2026-10-21T05:00Z, which is before COMPLETED_AT
    regardless of the real date. Without the pin the world uses today's date and
    the seeded run advances past COMPLETED_AT on 2026-10-22+, turning the FAIL
    into a PASS.
    """
    import datetime as _dt_w7  # noqa: PLC0415
    import json as _json  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415

