# ── W7 (C11/W7 cycle-2): fault code shape-check in _query_fault_status ───────


def test_w7_fault_code_sql_injection_refused() -> None:
    """W7 (red→fix): _query_fault_status must refuse codes that aren't valid DTCs.

    The brief §SQL rule: shape-check every interpolated value. A fault code that
    doesn't match _DTC_RE (^[A-Z0-9_]{2,32}$, CMS's groundings rule) could inject
    arbitrary SQL.

    S8 F4b fix: use a stub whose start_query_execution raises AssertionError and
    assert it isn't called for the injection payload.  When w7 removes the shape
    check, the injection reaches the Athena call, the stub fires, and the test
    FAILs on its own assertion ("w7 caught on its own assertion").
    """
    import pytest as _pytest  # noqa: PLC0415
    from unittest.mock import MagicMock  # noqa: PLC0415

    VALID_VIN = "11111111111111111"  # 17-char alphanumeric
    # The probe's exact injection payload.
    injection = "P0420') OR (1=1'"

    # S8 F4b: stub raises AssertionError if start_query_execution is called.
    # For the injection code, the shape check must fire ValueError BEFORE Athena.
    # Under w7 (shape check removed), the stub fires instead of ValueError.
    _athena_stub = MagicMock()
    _athena_stub.start_query_execution.side_effect = AssertionError(
        "S8: start_query_execution must NOT be called for an injection payload; "
        "the shape check must fire ValueError before reaching Athena. "
        "Under w7 (shape check removed), this AssertionError is the catch."
    )

    with _pytest.raises(ValueError, match="fault code shape check failed"):
        _mod._query_fault_status(_athena_stub, "staging", VALID_VIN, [injection])

    # Stub must NOT have been called (shape check fired first).
    _athena_stub.start_query_execution.assert_not_called()

    # A genuinely malformed code also fires the shape check before Athena.
    _athena_stub2 = MagicMock()
    _athena_stub2.start_query_execution.side_effect = AssertionError(
        "S8: shape check must fire before Athena for a malformed code"
    )
    with _pytest.raises(ValueError, match="fault code shape check failed"):
        _mod._query_fault_status(_athena_stub2, "staging", VALID_VIN, ["not-a-dtc"])
    _athena_stub2.start_query_execution.assert_not_called()


def test_ground_fault_view_query_admits_every_catalog_code() -> None:
    """Leg G step 8 must be able to query every real fault code (2026-10-26, prompt 124).

    The old `_DTC_RE` (`^[A-Z][0-9]{4}$`) refused 5 of the 10 p0 codes (P0AA6, P0A0D,
    P0A80, B0001_FIRE, U3000_CRASH), so `_query_fault_status` raised for every vehicle
    holding one and leg G could never reach return to service. The codes come from
    ADP's catalog as vendored in `agents/fi_fleet_health/adp_code_labor_op_map.json`.
    Each must reach Athena verbatim inside the `code IN (...)` literal list.
    """
    import json as _json  # noqa: PLC0415
    from unittest.mock import MagicMock  # noqa: PLC0415

    map_path = _SCRIPT.parents[1] / "agents" / "fi_fleet_health" / "adp_code_labor_op_map.json"
    catalog = sorted(_json.loads(map_path.read_text())["fault_codes"])
    p0 = ["B0001_FIRE", "C1234", "P0217", "P0520", "P0700", "P0A0D", "P0A80",
          "P0AA6", "U3000", "U3000_CRASH"]
    assert len(catalog) >= 50 and {"P0AA6", "B0001_FIRE"} <= set(catalog)

    class _Stop(Exception):
        pass

    for codes in ([c] for c in sorted(set(catalog) | set(p0))):
        athena = MagicMock()
        athena.start_query_execution.side_effect = _Stop()
        try:
            _mod._query_fault_status(athena, "staging", "MRDAZ01S0SR03752W", codes)
        except _Stop:
            pass
        except ValueError as exc:
            pytest.fail(f"real catalog code {codes[0]!r} refused by the shape check: {exc}")
        assert athena.start_query_execution.call_count == 1, codes
        sql = athena.start_query_execution.call_args.kwargs["QueryString"]
        assert f"code IN ('{codes[0]}')" in sql, sql

    # Still refused: anything that could close or extend the SQL literal.
    for bad in ("P0AA6'", "P0AA6 ", "P0AA6\n", "P0AA6;", "p0aa6", "B0001-FIRE", "P", "X" * 33):
        athena = MagicMock()
        athena.start_query_execution.side_effect = AssertionError("must not reach Athena")
        with pytest.raises(ValueError, match="fault code shape check failed"):
            _mod._query_fault_status(athena, "staging", "MRDAZ01S0SR03752W", [bad])
        athena.start_query_execution.assert_not_called()


