def test_w8_rts_uses_registry_vehicle_id(tmp_path: Any) -> None:
    """W8 (red→fix): RTS path must use the registry vehicleId, not the VIN.

    VIN index 10 has vehicleId='VEH-WORLD-0010' (seed.py:38).  With the current
    bug the script passes the VIN as vehicleId → CMS returns 404 → negative
    control FAILs.  After the fix the script looks up the registry vehicleId →
    CMS returns 409 fault_not_repaired → PASS.
    """
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415
    import uuid as _uuid  # noqa: PLC0415

    VIN = seed.vin(10)            # vehicleId = "VEH-WORLD-0010", != VIN
    FLEET_ID = seed.VIN_FLEET[10]  # "demo-rental-carshare"
    VEHICLE_ID = seed.vehicle_id(10)  # "VEH-WORLD-0010"
    RUN_ID = "fi-loop-20261021T100000-f1aabb02"
    STAGE = "staging"
    FINDING_ID = f"FIND-{_uuid.uuid4()}"
    FAULT_CODE = "P0300"

    rts_paths_seen: list[str] = []

    with _mock_aws():
        with FiLoopWorld(auto_pump=False) as w:
            ddb = w.internal("dynamodb")
            findings_table = _mod._FINDINGS_TABLE.format(stage=STAGE)
            ddb.put_item(
                TableName=findings_table,
                Item={
                    "finding_id": {"S": FINDING_ID},
                    "finding_kind": {"S": _mod._FLEET_HEALTH_FINDING_KIND},
                    "severity": {"S": "p0"},
                    "fleet_id": {"S": FLEET_ID},
                    "scope": {"M": {"vin": {"S": VIN}}},
                    "recommended_action": {"M": {
                        "action_kind": {"S": _mod._GROUND_VEHICLE_KIND},
                        "target_system": {"S": "cms"},
                        "parameters": {"M": {
                            "vehicle_vin": {"S": VIN},
                            "fault_codes": {"L": [{"S": FAULT_CODE}]},
                        }},
                    }},
                    "subject_key": {"S": f"fault/{FAULT_CODE}/p0"},
                    "headline": {"S": "Engine fault"},
                    "evidence": {"M": {}},
                },
            )
            w.seed_recall_cache(fleet_id=FLEET_ID, vin_list=[VIN])

            def _world_client(service: str, region: str, **_kw: Any) -> Any:
                if service == "cognito-idp":
                    return w.idp_client()
                return w.internal(service, region=region)

            def _stub_http(api_url: str, method: str, route: str,
                           token: str, body: Any, **_kw: Any) -> tuple[int, dict]:
                if method == "POST" and "approve" in route:
                    return (200, {"status": "executed",
                                  "action_kind": _mod._GROUND_VEHICLE_KIND,
                                  "action_id": "act-ground-w8",
                                  "finding_id": FINDING_ID})
                if method == "POST" and "return-to-service" in route:
                    # Record the vehicleId segment of the path so the test can check it.
                    rts_paths_seen.append(route)
                    # Only accept the registry vehicleId; return 404 for the bare VIN.
                    if VEHICLE_ID in route and VIN not in route:
                        return (409, {"reason": "fault_not_repaired",
                                      "fault_codes": [FAULT_CODE]})
                    return (404, {"reason": "vehicle_not_found"})
                return (200, {})

            res_holder: list[Results] = []
            real_rc = _mod.Results

            class _Cap(real_rc):  # type: ignore[misc,valid-type]
                def __init__(self) -> None:
                    super().__init__()
                    res_holder.append(self)

            mf_w8b = str(tmp_path / f"{RUN_ID}-manifest.json")
            # S1 fix: pre-write manifest.
            import json as _jj_w8b  # noqa: PLC0415
            Path(mf_w8b).write_text(_jj_w8b.dumps(
                {"stage": STAGE, "run_id": RUN_ID, "account": "", "records": {}}))

            with (
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_utc_now",
                             lambda: __import__("datetime").datetime(
                                 2026, 10, 21, 10, 0,
                                 tzinfo=__import__("datetime").timezone.utc)),
                patch.object(_mod, "_athena_query_paged",
                             lambda *a, **kw: []),
                patch.object(_mod, "_get_avx_api_url",
                             lambda cfn, stage: "http://fake-avx/"),
                patch.object(_mod, "_get_cms_api_url",
                             lambda cfn, stage: "http://fake-cms/"),
                patch.object(_mod, "_http", _stub_http),
                patch.object(_mod, "_manifest_path", lambda rid: mf_w8b),
                patch.object(_mod, "Results", _Cap),
            ):
                main(["--stage", STAGE, "--run-id", RUN_ID,
                      "--part", "ground",
                      "--allow-writes", "--allow-managed-writes"])

    assert res_holder, "Results not collected"
    labels = {r[0]: r[1] for r in res_holder[-1].rows}
    # The RTS path must use the registry vehicleId, not the raw VIN.
    assert any(VEHICLE_ID in p for p in rts_paths_seen), (
        f"W8: no RTS call with registry vehicleId {VEHICLE_ID!r}; "
        f"paths seen: {rts_paths_seen!r}"
    )
    assert labels.get("ground-rts-before-repair") == "PASS", (
        f"W8: registry vehicleId must reach 409 fault_not_repaired; "
        f"rows={res_holder[-1].rows}"
    )


def test_w8_pick_skips_open_booking_tries_next(tmp_path: Any) -> None:
    """W8 (red→fix): _iter_p0_health_findings-based pick must skip a VIN with an open FI
    booking and try the next candidate instead of FAILing immediately.

    Seeds TWO p0 fleet-health Findings:
    - Finding A: VIN 1 has an open FI fleet-health booking in DMS → must be skipped.
    - Finding B: VIN 2 has no booking → must be selected.

    Asserts that ``ground-finding-pick`` is PASS and the result names VIN 2 (not VIN 1).

    Catches the W8 property: if the code returns on first open-booking instead of
    continuing, the first Finding is returned (finding pick FAIL) instead of the
    second one (finding pick PASS with VIN 2).
    """
    import uuid as _uuid  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415

    VIN_WITH_BOOKING = seed.vin(1)
    VIN_CLEAN = seed.vin(2)
    FLEET_ID_1 = seed.VIN_FLEET[1]
    FLEET_ID_2 = seed.VIN_FLEET[2]
    RUN_ID = "fi-loop-20261021T110000-e8abc123"
    STAGE = "staging"
    FAULT_CODE = "P0420"
    FINDING_ID_1 = f"FIND-A-{_uuid.uuid4()}"
    FINDING_ID_2 = f"FIND-B-{_uuid.uuid4()}"

    with _mock_aws():
        with FiLoopWorld(auto_pump=False) as w:
            ddb = w.internal("dynamodb")
            findings_table = _mod._FINDINGS_TABLE.format(stage=STAGE)

            def _seed_finding(finding_id: str, vin: str, fleet_id: str) -> None:
                ddb.put_item(
                    TableName=findings_table,
                    Item={
                        "finding_id": {"S": finding_id},
                        "finding_kind": {"S": _mod._FLEET_HEALTH_FINDING_KIND},
                        "severity": {"S": "p0"},
                        "fleet_id": {"S": fleet_id},
                        "scope": {"M": {"vin": {"S": vin}}},
                        "recommended_action": {"M": {
                            "action_kind": {"S": _mod._GROUND_VEHICLE_KIND},
                            "target_system": {"S": "cms"},
                            "parameters": {"M": {
                                "vehicle_vin": {"S": vin},
                                "fault_codes": {"L": [{"S": FAULT_CODE}]},
                            }},
                        }},
                        "subject_key": {"S": f"fault/{FAULT_CODE}/p0"},
                        "headline": {"S": "Test finding"},
                        "evidence": {"M": {}},
                    },
                )

            _seed_finding(FINDING_ID_1, VIN_WITH_BOOKING, FLEET_ID_1)
            _seed_finding(FINDING_ID_2, VIN_CLEAN, FLEET_ID_2)

            # Seed an open FI fleet-health booking for VIN_WITH_BOOKING.
            dms_ro_table = _mod._DMS_RO_TABLE.format(stage=STAGE)
            ddb.put_item(
                TableName=dms_ro_table,
                Item={
                    "ro_id": {"S": f"RO-BLOCK-{_uuid.uuid4()}"},
                    "vin": {"S": VIN_WITH_BOOKING},
                    "avx_action_id": {"S": "act-prior-fh-book"},
                    "customer_type": {"S": "fleet"},
                    "status": {"S": "Draft"},
                    "lines": {"L": [{"M": {
                        "need_id": {"S": "fault:P0420"},
                        "pay_type": {"S": "customer_pay"},
                    }}]},
                },
            )

            def _world_client(service: str, region: str, **_kw: Any) -> Any:
                if service == "cognito-idp":
                    return w.idp_client()
                return w.internal(service, region=region)

            res_holder: list[Results] = []
            real_rc = _mod.Results

            class _Cap(real_rc):  # type: ignore[misc,valid-type]
                def __init__(self) -> None:
                    super().__init__()
                    res_holder.append(self)

            with (
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_utc_now",
                             lambda: __import__("datetime").datetime(
                                 2026, 10, 21, 10, 0,
                                 tzinfo=__import__("datetime").timezone.utc)),
                patch.object(_mod, "_manifest_path",
                             lambda rid: str(tmp_path / f"{rid}-manifest.json")),
                patch.object(_mod, "Results", _Cap),
            ):
                # S1 fix: pre-write manifest.
                import json as _jj_w8p  # noqa: PLC0415
                Path(str(tmp_path / f"{RUN_ID}-manifest.json")).write_text(
                    _jj_w8p.dumps({"stage": STAGE, "run_id": RUN_ID,
                                   "account": "", "records": {}}))
                main(["--stage", STAGE, "--run-id", RUN_ID,
                      "--part", "ground",
                      "--allow-writes", "--allow-managed-writes"])

    assert res_holder, "Results not collected"
    labels = {r[0]: r[1] for r in res_holder[-1].rows}
    assert labels.get("ground-finding-pick") == "PASS", (
        "W8: pick must PASS (skip VIN_WITH_BOOKING, select VIN_CLEAN instead of failing); "
        f"rows={res_holder[-1].rows}"
    )
    # Confirm the PASS row names the clean VIN, not the one with an open booking.
    pick_row_text = next(
        (txt for label, status, txt in res_holder[-1].rows
         if label == "ground-finding-pick"),
        "",
    )
    assert VIN_CLEAN in pick_row_text, (
        f"W8: PASS row must name VIN_CLEAN={VIN_CLEAN!r}, not the blocked VIN; "
        f"pick_row_text={pick_row_text!r}"
    )
    assert VIN_WITH_BOOKING not in pick_row_text, (
        f"W8: PASS row must NOT name VIN_WITH_BOOKING={VIN_WITH_BOOKING!r}; "
        f"pick_row_text={pick_row_text!r}"
    )


