def test_c11_is_fi_booking_matches_dms_predicate_on_real_shapes() -> None:
    """C11 (red→fix): _is_fi_booking must agree with DMS de6c181's is_fi_booking
    on both a real recall-booking shape and a real fleet-health-booking shape.

    Loads the real DMS predicate via ``git show de6c181:source/simulation/fi_stand_ins.py``
    and compares it against the script's ported ``_is_fi_booking`` on the two
    canonical shapes defined by DMS (not an invented shape).

    Also verifies that:
    - _count_open_fi_bookings counts recall bookings (C11 fix).
    - _has_open_booking returns True for a recall booking (C11 fix).

    Catches m30 re-anchored to the full is_fi_booking predicate (drops recall branch →
    both script functions miss the recall booking → count/has_booking wrong for
    a recall-only scenario).
    """
    import subprocess  # noqa: PLC0415
    import tempfile  # noqa: PLC0415
    import importlib.util  # noqa: PLC0415
    import uuid as _uuid  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    import boto3 as _boto3  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415

    # ── 1. Load DMS de6c181 is_fi_booking ──────────────────────────────────
    dms_repo = str(Path.home() / "guidance-for-dealer-management-system-on-aws")
    result = subprocess.run(
        ["git", "-C", dms_repo, "show",
         "de6c181:source/simulation/fi_stand_ins.py"],
        capture_output=True, text=True,
    )
    assert result.returncode == 0, (
        f"git show de6c181:source/simulation/fi_stand_ins.py failed: {result.stderr!r}"
    )
    dms_src = result.stdout
    # Write to a temp file and import it as a module.
    # Remove the DMS-internal import block (from source._lib.events ...) that
    # won't resolve in this venv.
    import re as _re  # noqa: PLC0415
    dms_src_patched = _re.sub(
        r"from source\._lib\.events import \(.*?\)",
        "# removed for import: from source._lib.events import (...)",
        dms_src,
        flags=_re.DOTALL,
    )
    with tempfile.NamedTemporaryFile(suffix=".py", mode="w", delete=False) as fh:
        fh.write(dms_src_patched)
        tmp_path_fi = fh.name
    spec = importlib.util.spec_from_file_location("dms_fi_stand_ins_de6c181", tmp_path_fi)
    assert spec and spec.loader
    dms_mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(dms_mod)  # type: ignore[union-attr]
    dms_is_fi_booking = dms_mod.is_fi_booking

    # ── 2. Real shapes ───────────────────────────────────────────────────────
    # Shape A: FI recall booking (fleet AVX RO + pay_type=recall + valid campaign_id).
    # Source: DMS de6c181 source/simulation/fi_stand_ins.py:80-91 (is_fi_recall_booking).
    recall_ro = {
        "avx_action_id": "act-recall-001",
        "customer_type": "fleet",
        "status": "Draft",
        "lines": [{"pay_type": "recall", "recall_campaign_id": "MRD-2024-A01",
                   "labor_op": "recall-inspect"}],
    }
    # Shape B: FI fleet-health booking (fleet AVX RO + need_id line).
    # Source: DMS de6c181 source/simulation/fi_stand_ins.py:93-117 (is_fi_fleet_health_booking).
    fleet_health_ro = {
        "avx_action_id": "act-fh-001",
        "customer_type": "fleet",
        "status": "Draft",
        "lines": [{"need_id": "fault:P0420", "pay_type": "customer_pay",
                   "labor_op": "brake-inspect"}],
    }
    # Non-FI RO: no avx_action_id.
    non_fi_ro = {
        "customer_type": "fleet",
        "status": "Draft",
        "lines": [{"need_id": "fault:P0420", "pay_type": "customer_pay"}],
    }

    # ── 3. Compare script vs DMS predicate on both shapes ────────────────────
    for shape, label in [(recall_ro, "recall"), (fleet_health_ro, "fleet-health"), (non_fi_ro, "non-fi")]:
        script_result = _mod._is_fi_booking(shape)
        dms_result = dms_is_fi_booking(shape)
        assert script_result == dms_result, (
            f"C11: _is_fi_booking disagrees with DMS de6c181 on {label} shape: "
            f"script={script_result!r}, dms={dms_result!r}, shape={shape!r}"
        )

    assert _mod._is_fi_booking(recall_ro), "recall booking must be True"
    assert _mod._is_fi_booking(fleet_health_ro), "fleet-health booking must be True"
    assert not _mod._is_fi_booking(non_fi_ro), "non-FI RO must be False"

    # ── 4. _count_open_fi_bookings counts recall bookings ────────────────────
    STAGE = "staging"
    VIN = seed.vin(2)
    BOOK_ACTION_ID = "act-recall-book-001"

    with _mock_aws():
        ddb = _boto3.client("dynamodb", region_name="us-west-2")
        dms_ro_table = _mod._DMS_RO_TABLE.format(stage=STAGE)
        ddb.create_table(
            TableName=dms_ro_table,
            KeySchema=[{"AttributeName": "ro_id", "KeyType": "HASH"}],
            AttributeDefinitions=[{"AttributeName": "ro_id", "AttributeType": "S"}],
            BillingMode="PAY_PER_REQUEST",
        )

        # Seed a recall FI booking with the real shape: fleet, pay_type=recall, campaign_id.
        ddb.put_item(
            TableName=dms_ro_table,
            Item={
                "ro_id": {"S": f"RO-RECALL-{_uuid.uuid4()}"},
                "vin": {"S": VIN},
                "avx_action_id": {"S": BOOK_ACTION_ID},
                "customer_type": {"S": "fleet"},
                "status": {"S": "Draft"},
                "lines": {"L": [{"M": {
                    "pay_type": {"S": "recall"},
                    "recall_campaign_id": {"S": "MRD-2024-A01"},
                    "labor_op": {"S": "recall-inspect"},
                }}]},
            },
        )

        total_open, ours = _mod._count_open_fi_bookings(ddb, STAGE, BOOK_ACTION_ID)

    assert total_open > 0, (
        "C11: recall FI booking (customer_type='fleet', pay_type='recall', "
        f"recall_campaign_id=MRD-2024-A01) must be counted; total_open={total_open}"
    )
    assert ours == 1, (
        f"C11: recall booking with matching avx_action_id must be 'ours'; ours={ours}"
    )


# ── C7 tests ─────────────────────────────────────────────────────────────────


def _ground_stub_result(
    *,
    fault_view_rows: list[dict],
    stand_in_counts: tuple[int, int] = (1, 1),
    rts_before_repair_response: tuple[int, dict] | None = None,
    rts_after_repair_response: tuple[int, dict] | None = None,
    run_id: str = "fi-loop-20261021T120000-c700001f",
    stage: str = "staging",
    book_response: tuple[int, dict] | None = None,
    initial_records: dict | None = None,
    http_calls: list | None = None,
    tmp_path: Any,
) -> dict[str, str]:
    """Run --part ground with stubs and return the label→status dict.

    ``book_response`` overrides the book_fleet_service approve answer (default: the
    old ``executed`` stub shape).
    """
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415
    import uuid as _uuid  # noqa: PLC0415

    VIN = seed.vin(1)
    FLEET_ID = seed.VIN_FLEET[1]
    FINDING_ID = f"FIND-{_uuid.uuid4()}"
    BOOKING_FINDING_ID = f"FIND-{_uuid.uuid4()}"
    FAULT_CODE = "P0420"

    # default RTS responses
    if rts_before_repair_response is None:
        rts_before_repair_response = (409, {"reason": "fault_not_repaired",
                                            "fault_codes": [FAULT_CODE]})
    if rts_after_repair_response is None:
        rts_after_repair_response = (200, {"status": "rts_accepted"})

    with _mock_aws():
        with FiLoopWorld(auto_pump=False) as w:
            ddb = w.internal("dynamodb")
            findings_table = _mod._FINDINGS_TABLE.format(stage=stage)
            ddb.put_item(
                TableName=findings_table,
                Item={
                    "finding_id": {"S": FINDING_ID},
                    "finding_kind": {"S": _mod._FLEET_HEALTH_FINDING_KIND},
                    "severity": {"S": "p0"},
                    "fleet_id": {"S": FLEET_ID},
                    "scope": {"M": {"vin": {"S": VIN}}},
                    "recommended_action": {"M": {
                        "action_kind": {"S": _mod._GROUND_VEHICLE_KIND},
                        "target_system": {"S": "cms"},
                        "parameters": {"M": {
                            "vehicle_vin": {"S": VIN},
                            "fault_codes": {"L": [{"S": FAULT_CODE}]},
                        }},
                    }},
                    "subject_key": {"S": "ground/1"},
                    "headline": {"S": "Brake fault"},
                    "evidence": {"M": {}},
                },
            )
            ddb.put_item(
                TableName=findings_table,
                Item={
                    "finding_id": {"S": BOOKING_FINDING_ID},
                    "finding_kind": {"S": _mod._FLEET_HEALTH_FINDING_KIND},
                    "severity": {"S": "p0"},
                    "fleet_id": {"S": FLEET_ID},
                    "scope": {"M": {"vin": {"S": VIN}}},
                    "recommended_action": {"M": {
                        "action_kind": {"S": _mod._BOOK_FLEET_SERVICE_KIND},
                        "target_system": {"S": "dms"},
                        "parameters": {"M": {
                            "vehicle_vin": {"S": VIN},
                            "needs": {"L": [{"M": {
                                "labor_op": {"S": "brake-inspect-001"},
                                "pay_type": {"S": "customer_pay"},
                            }}]},
                            "dealer_id": {"S": "dealer-001"},
                        }},
                    }},
                    "subject_key": {"S": "service/1"},
                    "headline": {"S": "Service booking"},
                    "evidence": {"M": {}},
                },
            )
            w.seed_recall_cache(fleet_id=FLEET_ID, vin_list=[VIN])

            def _world_client(service: str, region: str, **_kw: Any) -> Any:
                if service == "cognito-idp":
                    return w.idp_client()
                return w.internal(service, region=region)

            rts_call_count = [0]

            def _stub_http(api_url: str, method: str, route: str,
                           token: str, body: Any, **_kw: Any) -> tuple[int, dict]:
                if http_calls is not None:
                    http_calls.append((method, route))
                if method == "POST" and "approve" in route:
                    if "book_fleet_service" in str(body):
                        if book_response is not None:
                            return book_response
                        return (200, {"status": "executed",
                                      "action_kind": _mod._BOOK_FLEET_SERVICE_KIND,
                                      "action_id": "act-book-c7",
                                      "finding_id": BOOKING_FINDING_ID})
                    return (200, {"status": "executed",
                                  "action_kind": _mod._GROUND_VEHICLE_KIND,
                                  "action_id": "act-ground-c7",
                                  "finding_id": FINDING_ID})
                if method == "POST" and "return-to-service" in route:
                    rts_call_count[0] += 1
                    if rts_call_count[0] == 1:
                        return rts_before_repair_response  # type: ignore[return-value]
                    return rts_after_repair_response  # type: ignore[return-value]
                return (200, {})

            def _athena_stub(athena: Any, stage_: str, sql: str,
                             label: str) -> list[dict]:
                return fault_view_rows

            res_holder: list[Results] = []
            real_rc = _mod.Results

            class _Cap(real_rc):  # type: ignore[misc,valid-type]
                def __init__(self) -> None:
                    super().__init__()
                    res_holder.append(self)

            mf_path = str(tmp_path / f"{run_id}-manifest.json")
            # S1 fix: pre-write a minimal manifest so _part_ground doesn't
            # FAIL on the missing-manifest check.  account="" preserves the
            # existing bypass of the recall-slice pick check in test scenarios
            # that don't seed the recall cache with a clock-matched timestamp.
            import json as _jj_stub  # noqa: PLC0415
            Path(mf_path).write_text(_jj_stub.dumps(
                {"stage": stage, "run_id": run_id, "account": "",
                 "records": dict(initial_records or {})}))

            with (
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_utc_now",
                             lambda: __import__("datetime").datetime(
                                 2026, 10, 21, 10, 0,
                                 tzinfo=__import__("datetime").timezone.utc)),
                patch.object(_mod, "_athena_query_paged", _athena_stub),
                patch.object(_mod, "_get_avx_api_url",
                             lambda cfn, s: "http://fake-avx/"),
                patch.object(_mod, "_get_cms_api_url",
                             lambda cfn, s: "http://fake-cms/"),
                patch.object(_mod, "_http", _stub_http),
                patch.object(_mod, "_count_open_fi_bookings",
                             lambda *a, **k: stand_in_counts),
                patch.object(_mod, "_manifest_path", lambda rid: mf_path),
                patch.object(_mod, "Results", _Cap),
            ):
                main(["--stage", stage, "--run-id", run_id,
                      "--part", "ground",
                      "--allow-writes", "--allow-managed-writes"])

    assert res_holder, "Results not collected"
    return {r[0]: r[1] for r in res_holder[-1].rows}


def test_c7_stand_in_deferred_is_skip_not_pass(tmp_path: Any) -> None:
    """C7 (red→fix): stand-in DEFERRED must be SKIP, not a PASS with waiting wording.

    stand_in_counts = (2, 1): two open FI bookings, only one is ours.
    The script must SKIP (wait for the scheduled 05:40Z run), not PASS.
    """
    labels = _ground_stub_result(
        fault_view_rows=[],
        stand_in_counts=(2, 1),  # cannot invoke: others' bookings present
        tmp_path=tmp_path,
        run_id="fi-loop-20261021T120000-c7defe01",
    )
    assert labels.get("ground-stand-in") == "SKIP", (
        "C7: stand-in with others' bookings present must be SKIP, not PASS; "
        f"labels={labels}"
    )


def test_c7_repair_ref_absent_is_skip_not_pass(tmp_path: Any) -> None:
    """C7/W10 (red→fix): repair_ref absent must yield SKIP, not PASS with lag wording.

    W10 fix: tests feed the fault view a row with repair_ref=None (the real pre-repair
    shape from ADP vehicle_fault_status.sql), not [].  Catches m16b which replaces
    ``not (by_code.get(c) or {}).get("repair_ref")`` with ``c not in by_code`` —
    under the mutant a code that IS in by_code but has repair_ref=None is treated
    as repaired (not in the missing-ref list), so step 8 would PASS.
    """
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415

    VIN = seed.vin(1)
    FAULT_CODE = "P0420"
    FLEET_ID = seed.VIN_FLEET[1]

    # W10 fix: row WITH the code but repair_ref absent (None) — real pre-repair shape.
    labels = _ground_stub_result(
        fault_view_rows=[{
            "vin": VIN,
            "code": FAULT_CODE,
            "fleet_id": FLEET_ID,
            "repair_ref": None,      # W10: real pre-repair row has repair_ref null
            "repaired_on": None,
            "status": "open",
        }],
        stand_in_counts=(1, 1),
        tmp_path=tmp_path,
        run_id="fi-loop-20261021T120000-c7beef01",
    )
    assert labels.get("ground-repair-ref") == "SKIP", (
        "C7/W10: repair_ref null must be SKIP (row in view but not repaired); "
        f"labels={labels}"
    )


