def test_w10_ground_guard_passthrough_lambda_invoke() -> None:
    """W10: ground-part lambda.Invoke passes the real guard in a moto context."""
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    import boto3 as _b3  # noqa: PLC0415
    import json as _json  # noqa: PLC0415

    with _mock_aws():
        # Create a minimal Lambda function in moto
        iam = _b3.client("iam", region_name="us-west-2")
        try:
            iam.create_role(
                RoleName="w10-lambda-role",
                AssumeRolePolicyDocument=_json.dumps({
                    "Version": "2012-10-17",
                    "Statement": [{"Effect": "Allow", "Principal": {"Service": "lambda.amazonaws.com"},
                                   "Action": "sts:AssumeRole"}]
                }),
            )
        except Exception:  # noqa: BLE001
            pass
        lam = _b3.client("lambda", region_name="us-west-2")
        lam.create_function(
            FunctionName="w10-test-fn",
            Runtime="python3.11",
            Role="arn:aws:iam::123456789012:role/w10-lambda-role",
            Handler="index.handler",
            Code={"ZipFile": b""},
        )

        _mod._init_session("ground")
        guarded_lam = _mod._client("lambda", "us-west-2")
        # Invoke is in _GROUND_EXTRA_OPS → allowed in ground
        try:
            guarded_lam.invoke(FunctionName="w10-test-fn", Payload=b"{}")
        except Exception:  # noqa: BLE001
            pass  # moto may not execute the function; we only care that no GuardViolation
    # No GuardViolation means the guard was exercised and allowed lambda.Invoke


