# ── W1/n01: disclosure FAIL when catalog row not read ────────────────────────

def test_w1_disclosure_fails_when_catalog_row_not_read() -> None:
    """W1/n01 (red→fix): disclosure check must FAIL when catalog_row is empty.

    With an empty catalog_row (Athena error or no rows), the disclosure check
    must FAIL rather than silently skipping the byte comparison.
    A Finding with a valid disclosure_txt should still fail because the comparison
    cannot be made without the catalog row.
    Catches n01 (removes the 'catalog_row not read' fail guard → the else-branch
    computes an empty expected_disc and the mismatch check fires with wrong wording,
    not the intentional 'catalog_row not read' message).
    """
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415

    CAMPAIGN_ID = "MRD-2026-910"
    VIN = seed.vin(1)
    FLEET_ID = seed.VIN_FLEET[1]

    # Finding has a valid disclosure_txt — but without catalog_row we can't verify it
    finding = _make_recall_finding_schema_ev(
        campaign_id=CAMPAIGN_ID, vin=VIN, fleet_id=FLEET_ID,
        disclosure_txt="Summary\n\nConsequence\n\nRemedy",
    )

    def _wrap(v: Any) -> dict:
        if v is None:
            return {"NULL": True}
        if isinstance(v, bool):
            return {"BOOL": v}
        if isinstance(v, int):
            return {"N": str(v)}
        if isinstance(v, str):
            return {"S": v}
        if isinstance(v, list):
            return {"L": [_wrap(i) for i in v]}
        if isinstance(v, dict):
            return {"M": {k2: _wrap(v2) for k2, v2 in v.items()}}
        return {"S": str(v)}

    class _FakeDDB:
        def scan(self, **kw: Any) -> dict:
            return {"Items": [{k: _wrap(v) for k, v in finding.items()}]}

    res = Results()
    _mod._check_recall_findings(
        res, _FakeDDB(), "staging", CAMPAIGN_ID, [VIN],
        catalog_row={},  # empty catalog row — Athena error swallowed
    )
    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("after-run-findings-disclosure-txt") == "FAIL", (
        f"W1/n01: empty catalog_row must cause disclosure check to FAIL; "
        f"rows={res.rows}"
    )
    # n01 isolation: the FAIL reason must be 'catalog_row not read', not a mismatch.
    # With n01 applied (guard removed), the else-branch fires with expected_disc=""
    # + "\n\n\n\n", which mismatches the Finding — a different FAIL message.
    fail_detail = next(
        (r[2] for r in res.rows if r[0] == "after-run-findings-disclosure-txt" and r[1] == "FAIL"),
        "",
    )
    assert "catalog_row" in fail_detail, (
        f"W1/n01: disclosure FAIL must cite 'catalog_row'; "
        f"got {fail_detail!r}. "
        "Catches n01: guard removed → falls through to mismatch with wrong expected_disc."
    )


