def test_c6_extra_vins_in_rvs_fail(tmp_path: Any) -> None:
    """W3/m15b (red→fix): extra VINs in recall_vehicle_status must FAIL.

    recall_vehicle_status should have EXACTLY the expected VINs (set equality).
    An extra VIN in the RVS result means a VIN we did not expect is enrolled
    in the recall — this is a safety-critical property (the lot rule).
    Catches m15b (removes the extra_vins check → extra VINs pass silently).
    """
    import json as _json  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415

    CAMPAIGN_ID = "MRD-2026-913"
    VIN1 = seed.vin(1)
    EXTRA_VIN = seed.vin(2)  # not in expected_vins
    FLEET_ID = seed.VIN_FLEET[1]
    RUN_ID = "fi-loop-20261021T060200-44bb15bc"
    STAGE = "staging"
    COMPLETED_AT = "2026-10-21T04:00:00+00:00"

    with _mock_aws():
        with FiLoopWorld(auto_pump=True) as w:
            ddb_avx = w.internal("dynamodb")
            run_table = _mod._AGENT_RUNS_TABLE.format(stage=STAGE)
            try:
                ddb_avx.create_table(
                    TableName=run_table,
                    KeySchema=[
                        {"AttributeName": "agent_component", "KeyType": "HASH"},
                        {"AttributeName": "started_at", "KeyType": "RANGE"},
                    ],
                    AttributeDefinitions=[
                        {"AttributeName": "agent_component", "AttributeType": "S"},
                        {"AttributeName": "started_at", "AttributeType": "S"},
                    ],
                    BillingMode="PAY_PER_REQUEST",
                )
            except Exception:  # noqa: BLE001
                pass
            ddb_avx.put_item(
                TableName=run_table,
                Item={
                    "agent_component": {"S": _mod._RECALL_AGENT_COMPONENT},
                    "started_at": {"S": "2026-10-21T05:00:00+00:00"},
                    "status": {"S": "completed"},
                },
            )

            manifest_data = {
                "run_id": RUN_ID, "stage": STAGE,
                "records": {
                    "issued_campaign_id": CAMPAIGN_ID,
                    "part_issue_completed_at": COMPLETED_AT,
                },
                "expected_vins": [VIN1],  # only VIN1 expected; EXTRA_VIN is not
                "account": "123456789012",
            }
            p = tmp_path / f"{RUN_ID}-manifest.json"
            p.write_text(_json.dumps(manifest_data))

            def _world_client(service: str, region: str, **_kw: Any) -> Any:
                return w.internal(service, region=region)

            # RVS returns BOTH VIN1 and EXTRA_VIN — set not equal to expected
            def _rvs_stub(athena: Any, stage_: str, sql: str, label: str) -> list[dict]:
                if "recall_vehicle_status" in label or "recall_vehicle_status" in sql:
                    return [
                        {"vin": VIN1, "fleet_id": FLEET_ID, "match_basis": "POPULATION",
                         "remedied": "false"},
                        {"vin": EXTRA_VIN, "fleet_id": FLEET_ID, "match_basis": "POPULATION",
                         "remedied": "false"},
                    ]
                return []  # catalog row empty (not under test)

            def _stub_findings(
                res_: Any, ddb_: Any, stage_: str, cid: str, exp_vins: "list[str]",
                catalog_row: "dict | None" = None,
                cause_value: str = "",
            ) -> list[dict]:
                return []  # no findings; step 2 isolated

            res_holder: list[Results] = []
            real_rc = _mod.Results

            class _Cap(real_rc):  # type: ignore[misc,valid-type]
                def __init__(self) -> None:
                    super().__init__()
                    res_holder.append(self)

            with (
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_manifest_path", lambda rid: str(p)),
                patch.object(_mod, "_athena_query_paged", _rvs_stub),
                patch.object(_mod, "_check_recall_findings", _stub_findings),
                patch.object(_mod, "Results", _Cap),
            ):
                main(["--stage", STAGE, "--run-id", RUN_ID, "--part", "after-run"])

    assert res_holder
    labels = {r[0]: r[1] for r in res_holder[-1].rows}
    assert labels.get("after-run-recall-vehicle-status") == "FAIL", (
        f"W3/m15b: extra VIN {EXTRA_VIN!r} in recall_vehicle_status should FAIL; "
        f"catches m15b (extra_vins check removed). rows={res_holder[-1].rows}"
    )


def test_w5_vehicle_not_in_cohort_fails_drill_down(tmp_path: Any) -> None:
    """W3/n20 (red→fix): a VIN in vehicle_status but not in cohort must FAIL the drill-down.

    CMS's recall source returns 'not_in_cohort' for VINs not in the slice's cohort
    list.  The check must require the VIN to be in both vehicle_status AND cohort.
    Catches n20 (cohort membership check removed → any VIN in vehicle_status passes).
    """
    import json as _json  # noqa: PLC0415
    import gzip as _gzip  # noqa: PLC0415
    import hashlib as _hashlib  # noqa: PLC0415
    import datetime as _dt  # noqa: PLC0415
    import time as _time  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415
    from scripts.tests.fi_loop_world.cms_fi import (  # noqa: PLC0415
        CMS_ATHENA_BUCKET, CMS_ATHENA_PREFIX,
    )

    CAMPAIGN_ID = "MRD-2026-914"
    VIN = seed.vin(1)
    FLEET_ID = seed.VIN_FLEET[1]
    OTHER_VIN = seed.vin(2)  # in cohort, but not in vehicle_status for this campaign
    RUN_ID = "fi-loop-20261021T060300-20202020"
    STAGE = "staging"
    COMPLETED_AT = "2026-10-21T04:00:00+00:00"

    with _mock_aws():
        with FiLoopWorld(auto_pump=True) as w:
            s3 = w.internal("s3")
            ddb_avx = w.internal("dynamodb")

            run_table = _mod._AGENT_RUNS_TABLE.format(stage=STAGE)
            try:
                ddb_avx.create_table(
                    TableName=run_table,
                    KeySchema=[
                        {"AttributeName": "agent_component", "KeyType": "HASH"},
                        {"AttributeName": "started_at", "KeyType": "RANGE"},
                    ],
                    AttributeDefinitions=[
                        {"AttributeName": "agent_component", "AttributeType": "S"},
                        {"AttributeName": "started_at", "AttributeType": "S"},
                    ],
                    BillingMode="PAY_PER_REQUEST",
                )
            except Exception:  # noqa: BLE001
                pass
            ddb_avx.put_item(
                TableName=run_table,
                Item={
                    "agent_component": {"S": _mod._RECALL_AGENT_COMPONENT},
                    "started_at": {"S": "2026-10-21T05:00:00+00:00"},
                    "status": {"S": "completed"},
                },
            )

            computed_at = _dt.datetime.fromtimestamp(
                _time.time(), _dt.timezone.utc
            ).isoformat()
            gen = "20261021T000000000000Z-n20test1"
            scope_hash = _hashlib.sha256(FLEET_ID.encode()).hexdigest()
            scope_name = f"fleet-{scope_hash}"
            recall_prefix = f"{CMS_ATHENA_PREFIX}_cache/fi-recall-views-v1/"

            s3.put_object(
                Bucket=CMS_ATHENA_BUCKET,
                Key=f"{recall_prefix}manifest.json",
                Body=_json.dumps({
                    "schemaVersion": 2, "generation": gen,
                    "computedAt": computed_at, "windowMonths": 0,
                    "seriesShards": 16, "kinds": ["recall"], "fleets": [FLEET_ID],
                }).encode(),
            )

            # VIN is in vehicle_status BUT NOT in cohort.
            # n20 fix: cohort membership check ensures VIN must be in cohort list too.
            view_body = {
                "schemaVersion": 2, "kind": "recall", "generation": gen,
                "windowMonths": 0,
                "scope": {"fleetId": FLEET_ID},
                "computed_at": computed_at, "computedAt": computed_at,
                # cohort has OTHER_VIN only — VIN is NOT in cohort
                "cohort": [{"vin": OTHER_VIN}],
                "campaigns": [{"campaign_id": CAMPAIGN_ID, "recall_class": "safety"}],
                "fleet_summary": [{"campaign_id": CAMPAIGN_ID, "recall_class": "safety",
                                   "count": 1}],
                # vehicle_status has VIN but cohort doesn't
                "vehicle_status": [{"vin": VIN, "campaign_id": CAMPAIGN_ID,
                                    "remedied": False}],
            }
            s3.put_object(
                Bucket=CMS_ATHENA_BUCKET,
                Key=f"{recall_prefix}{gen}/recall/{scope_name}.json.gz",
                Body=_gzip.compress(_json.dumps(view_body).encode()),
            )

            manifest_data = {
                "run_id": RUN_ID, "stage": STAGE,
                "records": {
                    "issued_campaign_id": CAMPAIGN_ID,
                    "part_issue_completed_at": COMPLETED_AT,
                },
                "expected_vins": [VIN],
                "account": "123456789012",
            }
            p = tmp_path / f"{RUN_ID}-manifest.json"
            p.write_text(_json.dumps(manifest_data))

            def _world_client(service: str, region: str, **_kw: Any) -> Any:
                return w.internal(service, region=region)

            def _athena_stub(athena: Any, stage_: str, sql: str, label: str) -> list[dict]:
                if "recall_vehicle_status" in label:
                    return [{"vin": VIN, "fleet_id": FLEET_ID,
                             "match_basis": "POPULATION", "remedied": "false"}]
                if "recall_catalog_row" in label or "recall_campaigns_received" in label:
                    return [{"summary": "S", "consequence": "C", "remedy": "R"}]
                return []

            def _stub_findings(
                res_: Any, ddb_: Any, stage_: str, cid: str, exp_vins: "list[str]",
                catalog_row: "dict | None" = None,
                cause_value: str = "",
            ) -> list[dict]:
                # n20 fix: return a finding with FLEET_ID so fleet_ids_list is non-empty
                # and the CMS S3 drill-down for FLEET_ID is checked.
                # Without a fleet_id here, the CMS check never reads the S3 slice.
                return [{"fleet_id": FLEET_ID, "scope": {"vin": VIN}}]

            res_holder: list[Results] = []
            real_rc = _mod.Results

            class _Cap(real_rc):  # type: ignore[misc,valid-type]
                def __init__(self) -> None:
                    super().__init__()
                    res_holder.append(self)

            with (
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_manifest_path", lambda rid: str(p)),
                patch.object(_mod, "_athena_query_paged", _athena_stub),
                patch.object(_mod, "_check_recall_findings", _stub_findings),
                patch.object(_mod, "Results", _Cap),
            ):
                main(["--stage", STAGE, "--run-id", RUN_ID, "--part", "after-run"])

    assert res_holder
    labels = {r[0]: r[1] for r in res_holder[-1].rows}
    assert labels.get("after-run-cms-vehicle-drill-down") == "FAIL", (
        f"W3/n20: VIN not in cohort must FAIL drill-down; "
        f"catches n20 (cohort membership check removed). rows={res_holder[-1].rows}"
    )


# ── S8/n06: >1 quality.issue for same thread must fail ───────────────────────

def test_s8_multiple_quality_issues_for_thread_returns_none() -> None:
    """S8/n06 (red→fix): >1 quality.issue Finding with same subject_key → _find_quality_issue_finding returns None.

    The brief: the check must require exactly one quality.issue Finding for this
    thread (ambiguity means we can't safely approve one); >1 must FAIL.
    Catches n06 (removes the len(matched) != 1 guard → returns the first match instead).
    """
    ddb = MagicMock()
    # Two Findings with the same subject_key — ambiguous, must return None
    ITEMS = [
        {
            "finding_id": {"S": "FIND-qi-001"},
            "finding_kind": {"S": "quality.issue"},
            "subject_key": {"S": "OUR-THREAD/issue"},
            "evidence": {"L": []},
        },
        {
            "finding_id": {"S": "FIND-qi-002"},
            "finding_kind": {"S": "quality.issue"},
            "subject_key": {"S": "OUR-THREAD/issue"},
            "evidence": {"L": []},
        },
    ]
    ddb.scan.return_value = {"Items": ITEMS}

    result = _mod._find_quality_issue_finding(ddb, "staging", "OUR-THREAD")
    assert result is None, (
        f"S8/n06: >1 quality.issue with subject_key='OUR-THREAD/issue' must return None "
        f"(ambiguous); got {result!r}. "
        "Catches n06: removes len(matched)!=1 guard → would return FIND-qi-001 instead."
    )


def test_s8_multiple_quality_issues_causes_check_fail() -> None:
    """S8/n06: _check_quality_issue_finding records FAIL when >1 matching Findings exist.

    Exercises the part-level behavior: two ambiguous quality.issue Findings cause
    issue-quality-issue-finding to FAIL.
    """
    ddb = MagicMock()
    ITEMS = [
        {
            "finding_id": {"S": "FIND-qi-001"},
            "finding_kind": {"S": "quality.issue"},
            "subject_key": {"S": "AMBIG-THREAD/issue"},
            "evidence": {"L": []},
        },
        {
            "finding_id": {"S": "FIND-qi-002"},
            "finding_kind": {"S": "quality.issue"},
            "subject_key": {"S": "AMBIG-THREAD/issue"},
            "evidence": {"L": []},
        },
    ]
    ddb.scan.return_value = {"Items": ITEMS}
    res = Results()
    fid, tid, did = _mod._check_quality_issue_finding(res, ddb, "staging", "AMBIG-THREAD")
    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("issue-quality-issue-finding") == "FAIL", (
        f"S8/n06: >1 quality.issue must cause issue-quality-issue-finding FAIL; "
        f"rows={res.rows}"
    )
    assert fid == "", f"S8/n06: fid must be empty on ambiguous match; got {fid!r}"


# ── W2/n19: S7 early-close skip must be tested via the ground part ─────────────

def test_s7_ground_stand_in_skips_early_close_ro_via_part(tmp_path: Any) -> None:
    """W2/n19 (red→fix): early-close RO causes ground-stand-in SKIP when driven via the part.

    The previous test called _would_early_close directly; n19 mutation removes the
    early-close check from the stand-in invocation path, which that direct test cannot detect.
    This test drives the full ground part through _ground_stub_result and asserts SKIP.
    Catches n19 (early-close check removed from stand-in invoke → stand-in is invoked
    even for early-close ROs → ground-stand-in becomes PASS or FAIL, not SKIP).
    """
    import hashlib as _hashlib  # noqa: PLC0415

    # Find an RO id that _would_early_close returns True for
    early_close_ro: str = ""
    for i in range(500):
        candidate = f"RO-S7N19-EARLY-{i:04d}"
        digest = int(_hashlib.sha256(candidate.encode()).hexdigest(), 16)
        if (digest % 100) < 5:
            early_close_ro = candidate
            break
    assert early_close_ro, "Could not find an early-close RO in 500 attempts"

    # Verify the property holds
    assert _mod._would_early_close(early_close_ro), (
        f"n19 test setup: {early_close_ro!r} must early-close"
    )

    # Drive the full ground part using _ground_stub_result with:
    # - stand_in_counts=(1, 1) so all open bookings are ours (would invoke if not early-close)
    # - _find_ro_id_for_action returning the early-close RO
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415
    import uuid as _uuid  # noqa: PLC0415

    VIN = seed.vin(1)
    FLEET_ID = seed.VIN_FLEET[1]
    FINDING_ID = f"FIND-{_uuid.uuid4()}"
    BOOKING_FINDING_ID = f"FIND-{_uuid.uuid4()}"
    FAULT_CODE = "P0420"
    RUN_ID = "fi-loop-20261022T110000-1900b501"
    STAGE = "staging"

    with _mock_aws():
        with FiLoopWorld(auto_pump=False) as w:
            ddb = w.internal("dynamodb")
            findings_table = _mod._FINDINGS_TABLE.format(stage=STAGE)
            ddb.put_item(
                TableName=findings_table,
                Item={
                    "finding_id": {"S": FINDING_ID},
                    "finding_kind": {"S": _mod._FLEET_HEALTH_FINDING_KIND},
                    "severity": {"S": "p0"},
                    "fleet_id": {"S": FLEET_ID},
                    "scope": {"M": {"vin": {"S": VIN}}},
                    "recommended_action": {"M": {
                        "action_kind": {"S": _mod._GROUND_VEHICLE_KIND},
                        "target_system": {"S": "cms"},
                        "parameters": {"M": {
                            "vehicle_vin": {"S": VIN},
                            "fault_codes": {"L": [{"S": FAULT_CODE}]},
                        }},
                    }},
                    "subject_key": {"S": "ground/1"},
                    "headline": {"S": "Brake fault"},
                    "evidence": {"M": {}},
                },
            )
            ddb.put_item(
                TableName=findings_table,
                Item={
                    "finding_id": {"S": BOOKING_FINDING_ID},
                    "finding_kind": {"S": _mod._FLEET_HEALTH_FINDING_KIND},
                    "severity": {"S": "p0"},
                    "fleet_id": {"S": FLEET_ID},
                    "scope": {"M": {"vin": {"S": VIN}}},
                    "recommended_action": {"M": {
                        "action_kind": {"S": _mod._BOOK_FLEET_SERVICE_KIND},
                        "target_system": {"S": "dms"},
                        "parameters": {"M": {
                            "vehicle_vin": {"S": VIN},
                            "needs": {"L": [{"M": {
                                "labor_op": {"S": "brake-inspect-001"},
                                "pay_type": {"S": "customer_pay"},
                            }}]},
                            "dealer_id": {"S": "dealer-001"},
                        }},
                    }},
                    "subject_key": {"S": "service/1"},
                    "headline": {"S": "Service booking"},
                    "evidence": {"M": {}},
                },
            )
            w.seed_recall_cache(fleet_id=FLEET_ID, vin_list=[VIN])

            def _world_client(service: str, region: str, **_kw: Any) -> Any:
                if service == "cognito-idp":
                    return w.idp_client()
                return w.internal(service, region=region)

            def _stub_http(api_url: str, method: str, route: str,
                           token: str, body: Any, **_kw: Any) -> tuple:
                if method == "POST" and "approve" in route:
                    if "book_fleet_service" in str(body):
                        return (200, {"status": "executed",
                                      "action_kind": _mod._BOOK_FLEET_SERVICE_KIND,
                                      "action_id": "act-book-n19",
                                      "finding_id": BOOKING_FINDING_ID})
                    return (200, {"status": "executed",
                                  "action_kind": _mod._GROUND_VEHICLE_KIND,
                                  "action_id": "act-ground-n19",
                                  "finding_id": FINDING_ID})
                if method == "POST" and "return-to-service" in route:
                    return (409, {"reason": "fault_not_repaired",
                                  "fault_codes": [FAULT_CODE]})
                return (200, {})

            def _athena_stub_ground(athena: Any, stage_: str, sql: str,
                                    label: str) -> list[dict]:
                return []  # no fault view rows

            res_holder: list[Results] = []
            real_rc = _mod.Results

            class _Cap(real_rc):  # type: ignore[misc,valid-type]
                def __init__(self) -> None:
                    super().__init__()
                    res_holder.append(self)

            mf_path = str(tmp_path / f"{RUN_ID}-manifest.json")
            # S1 fix: pre-write manifest.
            import json as _jj_s7via  # noqa: PLC0415
            Path(mf_path).write_text(_jj_s7via.dumps(
                {"stage": STAGE, "run_id": RUN_ID, "account": "", "records": {}}))

            with (
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_utc_now",
                             lambda: __import__("datetime").datetime(
                                 2026, 10, 22, 11, 0,
                                 tzinfo=__import__("datetime").timezone.utc)),
                patch.object(_mod, "_athena_query_paged", _athena_stub_ground),
                patch.object(_mod, "_get_avx_api_url",
                             lambda cfn, s: "http://fake-avx/"),
                patch.object(_mod, "_get_cms_api_url",
                             lambda cfn, s: "http://fake-cms/"),
                patch.object(_mod, "_http", _stub_http),
                # (1, 1): all open bookings are ours → would invoke if not early-close
                patch.object(_mod, "_count_open_fi_bookings",
                             lambda *a, **k: (1, 1)),
                # Return the early-close RO for the booking action
                patch.object(_mod, "_find_ro_id_for_action",
                             lambda *a, **k: early_close_ro),
                patch.object(_mod, "_manifest_path", lambda rid: mf_path),
                patch.object(_mod, "Results", _Cap),
            ):
                main(["--stage", STAGE, "--run-id", RUN_ID,
                      "--part", "ground",
                      "--allow-writes", "--allow-managed-writes"])

    assert res_holder, "Results not collected"
    labels = {r[0]: r[1] for r in res_holder[-1].rows}
    assert labels.get("ground-stand-in") == "SKIP", (
        f"W2/n19: early-close RO {early_close_ro!r} must cause ground-stand-in SKIP; "
        f"catches n19 (early-close check removed → stand-in invoked → PASS or FAIL). "
        f"labels={labels}"
    )


# ── F2d: C4 / W6 / W9 / S5 / S12 / New-thread-lake tests ────────────────────


def test_f2d_w6_username_recorded_before_create(tmp_path: Any) -> None:
    """W6 (red): temp username must be in the manifest BEFORE AdminCreateUser.

    Mutant: record username AFTER the create call.
    The test simulates AdminCreateUser succeeding but a subsequent call
    (admin_set_user_password) failing.  With the fix, the username is already
    in the manifest before the exception propagates; without the fix, it isn't.
    """
    import json as _json  # noqa: PLC0415

    RUN_ID = "fi-loop-20261021T120000-w6fix001"
    STAGE = "staging"
    POOL_ID = "us-west-2_W6FIX"
    PATTERN_ID = "pat-w6-001"

    # Manifest with the minimum pre data
    manifest_data = {
        "run_id": RUN_ID, "stage": STAGE,
        "account": "123456789012",
        "pattern_id": PATTERN_ID,
        "pre_verdict": "passed",
        "expected_vins": ["VIN00000000000001"],
        "safe_failure_modes": {"fm-001": "opt-recall-001"},  # F6b
        "records": {},
    }
    p = tmp_path / f"{RUN_ID}.json"
    p.write_text(_json.dumps(manifest_data))

    create_calls: list[str] = []

    class _FailAfterCreate:
        """Fake IdP: AdminCreateUser succeeds; all other calls raise."""
        def admin_create_user(self, **kw: Any) -> None:
            create_calls.append(kw.get("Username", ""))
        def admin_set_user_password(self, **kw: Any) -> None:
            raise RuntimeError("simulate set-password failure")
        def list_user_pools(self, **kw: Any) -> dict:
            return {"UserPools": [{"Id": POOL_ID, "Name": _mod._CMS_POOL_NAME}]}
        def list_users(self, **kw: Any) -> dict:
            return {"Users": []}

    expected_email = f"{_mod._LIVETEST_USER_PREFIX}{RUN_ID}-pe@example.invalid"

    def _fake_client(svc: str, reg: str, **kw: Any) -> Any:
        if svc == "cognito-idp":
            return _FailAfterCreate()
        from unittest.mock import MagicMock  # noqa: PLC0415
        return MagicMock()  # cloudformation etc. - stubs will intercept before use

    def _resolve_pool_id_stub(idp: Any) -> str:
        return POOL_ID

    with (
        patch.object(_mod, "_manifest_path", lambda rid: str(p)),
        patch.object(_mod, "_client", _fake_client),
        patch.object(_mod, "_resolve_pool_id", _resolve_pool_id_stub),
        patch.object(_mod, "_password_client", lambda idp, pid: "client-w6"),
        patch.object(_mod, "_maint_window_guard", lambda now: None),
        patch.object(_mod, "_schedule_guard", lambda cl, sch, st, now: None),
        patch.object(_mod, "_check_esm_enabled", lambda res, lam, st, reg: True),
        patch.object(_mod, "_check_tier2_code", lambda res, lam, fn: True),
        patch.object(_mod, "_check_recall_table_exists", lambda res, glue, st: True),
        patch.object(_mod, "_check_view_sql_unions_issued", lambda res, glue, st: True),
        patch.object(_mod, "_check_dlq_empty", lambda res, sqs, st: True),
        patch.object(_mod, "_check_no_open_livetest", lambda res, idp, st: True),
        patch.object(_mod, "_get_avx_api_url", lambda cfn, st: "http://fake-avx/"),
        # Stop after user creation failure (issue-create-user FAIL → return)
    ):
        res = Results()
        _mod._part_issue(res, stage=STAGE, run_id=RUN_ID, allow_writes=True)

    # Username must be in manifest even though create failed midway
    written_manifest = _json.loads(p.read_text())
    users_in_manifest = written_manifest.get("records", {}).get("users", [])
    assert expected_email in users_in_manifest, (
        f"W6: username {expected_email!r} must be in manifest BEFORE AdminCreateUser; "
        f"manifest users={users_in_manifest!r}"
    )
    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("issue-create-user") == "FAIL", (
        f"W6: expected issue-create-user FAIL when set-password raises; rows={res.rows}"
    )


def test_f2d_w9_rerun_partial_issue_refuses_overwrite(tmp_path: Any) -> None:
    """W9 (red): a re-run after a partial issue must NOT overwrite recorded ids.

    Mutant: remove the investigation_id overwrite guard → second run records
    a different UUID and orphans the first investigation.
    """
    import json as _json  # noqa: PLC0415
    import uuid as _uuid  # noqa: PLC0415

    RUN_ID = "fi-loop-20261021T120000-w9fix001"
    STAGE = "staging"
    POOL_ID = "us-west-2_W9FIX"
    EXISTING_INV_ID = _uuid.uuid4().hex  # already in manifest from first run
    NEW_INV_ID = _uuid.uuid4().hex       # server would assign this on second POST

    manifest_data = {
        "run_id": RUN_ID, "stage": STAGE,
        "account": "123456789012",
        "pattern_id": "pat-w9-001",
        "pre_verdict": "passed",
        "expected_vins": ["VIN00000000000001"],
        "safe_failure_modes": {"fm-001": "opt-recall-001"},
        "records": {
            "investigation_id": EXISTING_INV_ID,
            "users": [f"{_mod._LIVETEST_USER_PREFIX}{RUN_ID}-pe@example.invalid"],
        },
    }
    p = tmp_path / f"{RUN_ID}.json"
    p.write_text(_json.dumps(manifest_data))

    class _FakeIdp:
        def list_user_pools(self, **kw: Any) -> dict:
            return {"UserPools": [{"Id": POOL_ID, "Name": _mod._CMS_POOL_NAME}]}
        def admin_create_user(self, **kw: Any) -> None:
            pass
        def admin_set_user_password(self, **kw: Any) -> None:
            pass
        def admin_add_user_to_group(self, **kw: Any) -> None:
            pass
        def initiate_auth(self, **kw: Any) -> dict:
            return {"AuthenticationResult": {"IdToken": "tok-w9"}}

    post_calls: list[str] = []

    def _fake_http(url: str, method: str, path: str, token: str, body: Any = None) -> tuple:
        if method == "POST" and "investigations" in path and not path.count("/") > 1:
            post_calls.append(path)
            return 202, {"investigation_id": NEW_INV_ID, "status": "queued",
                          "pattern_id": "pat-w9-001", "requested_at": "2026-10-21T12:00:00Z"}
        return 200, {}

    def _fake_client(svc: str, reg: str, **kw: Any) -> Any:
        if svc == "cognito-idp":
            return _FakeIdp()
        from unittest.mock import MagicMock  # noqa: PLC0415
        return MagicMock()  # stubbed helpers intercept before use

    def _resolve_pool_id_stub(idp: Any) -> str:
        return POOL_ID

    with (
        patch.object(_mod, "_manifest_path", lambda rid: str(p)),
        patch.object(_mod, "_client", _fake_client),
        patch.object(_mod, "_resolve_pool_id", _resolve_pool_id_stub),
        patch.object(_mod, "_password_client", lambda idp, pid: "client-w9"),
        patch.object(_mod, "_http", _fake_http),
        patch.object(_mod, "_read_ddb_item",
                     lambda ddb, tbl, key: {"cohort_dimension": {"S": "supplier_lot"}}),
        patch.object(_mod, "_maint_window_guard", lambda now: None),
        patch.object(_mod, "_schedule_guard", lambda cl, sch, st, now: None),
        patch.object(_mod, "_check_esm_enabled", lambda res, lam, st, reg: True),
        patch.object(_mod, "_check_tier2_code", lambda res, lam, fn: True),
        patch.object(_mod, "_check_recall_table_exists", lambda res, glue, st: True),
        patch.object(_mod, "_check_view_sql_unions_issued", lambda res, glue, st: True),
        patch.object(_mod, "_check_dlq_empty", lambda res, sqs, st: True),
        patch.object(_mod, "_check_no_open_livetest", lambda res, idp, st: True),
        patch.object(_mod, "_get_avx_api_url", lambda cfn, st: "http://fake-avx/"),
    ):
        res = Results()
        _mod._part_issue(res, stage=STAGE, run_id=RUN_ID, allow_writes=True)

    labels = {r[0]: r[1] for r in res.rows}
    written_manifest = _json.loads(p.read_text())
    inv_in_manifest = written_manifest.get("records", {}).get("investigation_id", "")

    # Must not overwrite the existing investigation_id with the new one
    assert inv_in_manifest == EXISTING_INV_ID, (
        f"W9: must not overwrite existing investigation_id={EXISTING_INV_ID!r} "
        f"with {NEW_INV_ID!r}; got {inv_in_manifest!r}"
    )
    assert labels.get("issue-post-investigation") == "FAIL", (
        f"W9: expected FAIL when re-run would overwrite ids; rows={res.rows}"
    )

    # Must not overwrite the existing investigation_id with the new one
    assert inv_in_manifest == EXISTING_INV_ID, (
        f"W9: must not overwrite existing investigation_id={EXISTING_INV_ID!r} "
        f"with {NEW_INV_ID!r}; got {inv_in_manifest!r}"
    )
    assert labels.get("issue-post-investigation") == "FAIL", (
        f"W9: expected FAIL when re-run would overwrite ids; rows={res.rows}"
    )


