def test_f2d_s5_clienterror_codes_not_text(tmp_path: Any) -> None:
    """S5 (red): _delete_s3_object must match ClientError Code, not exception text.

    Mutant: check '404' in str(exc2) instead of exc2.response['Error']['Code'] == '404'.
    Catches the case where the error message is 'S3 object still present after delete'
    which contains no '404' but IS a RuntimeError from _delete_s3_object itself
    (the 'still present' check).  The Code-based check correctly re-raises it.
    Also: a proper ClientError with Code='404' must return True (gone).
    """
    from botocore.exceptions import ClientError as _ClientError  # noqa: PLC0415

    class _S3WithVersionedDelete:
        """Returns 404 ClientError on HeadObject (object gone after delete)."""
        def delete_object(self, **kw: Any) -> None:
            pass  # delete succeeds

        def head_object(self, **kw: Any) -> None:
            raise _ClientError(
                {"Error": {"Code": "404", "Message": "Not Found"}},
                "HeadObject",
            )

    result = _mod._delete_s3_object(_S3WithVersionedDelete(), "buck", "key/obj.json")
    assert result is True, (
        f"S5: ClientError Code='404' on HeadObject must return True (object gone); "
        f"got {result!r}"
    )

    # Verify still-present raises RuntimeError (not caught as '404')
    class _S3StillPresent:
        def delete_object(self, **kw: Any) -> None:
            pass
        def head_object(self, **kw: Any) -> dict:
            return {"ContentLength": 42}  # object still exists → must RuntimeError

    import pytest as _pytest  # noqa: PLC0415
    with _pytest.raises(RuntimeError, match="still present"):
        _mod._delete_s3_object(_S3StillPresent(), "buck", "key/obj.json")


