def test_f2d_thread_lake_objects_deleted_when_present(tmp_path: Any) -> None:
    """F2d2 / F2g: flat thread-lake objects deleted; flat layout confirmed.

    F2g drops the nested prefix (curated/engineering/digital_thread/<id>/v<n>.json).
    Only the flat prefix (curated/engineering/digital_thread/<id>.v<n>.json) is
    cleaned up.  thread_id must match ^thread-[0-9a-f]{16}$.

    Also verifies: when no objects exist (writer not deployed), check passes.
    """
    import json as _json  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world.world import LAKE_BUCKET  # noqa: PLC0415

    STAGE = "staging"
    ACCOUNT = "123456789012"
    THREAD_ID = "thread-0123456789abcdef"   # must match ^thread-[0-9a-f]{16}$
    RUN_ID = "fi-loop-20261021T150000-thrdlake"
    DEC_ACTION_ID_TL = "act-tl-001"
    ISS_ACTION_ID_TL = "act-tl-002"
    VIN_KEY_TL = f"digital-thread/staging/{THREAD_ID}/v1/affected-vins.json"

    # VIN-list bucket (adp-staging-engineering-vins-<account>-us-east-1)
    VIN_BUCKET = f"adp-{STAGE}-engineering-vins-{ACCOUNT}-us-east-1"

    manifest_data = {
        "run_id": RUN_ID, "stage": STAGE,
        "pattern_id": "pat-tl-001",
        "records": {
            "users": [],
            "thread_id": THREAD_ID,
            "thread_versions": [1, 2],  # F2g: recorded by issue step
            "decision_action_id": DEC_ACTION_ID_TL,
            "issue_action_id": ISS_ACTION_ID_TL,
            "vin_s3_keys": [VIN_KEY_TL],  # S4 F3b: recorded per-version keys
        },
        "account": ACCOUNT,
        "residue": {},
        "expected_vins": [],
    }

    # ── Case 1: flat objects present ──────────────────────────────────────────
    with _mock_aws():
        with FiLoopWorld(auto_pump=True) as w:
            s3_adp = w.internal("s3", region="us-east-1")
            ddb_adp = w.internal("dynamodb", region="us-east-1")

            # Insert DDB thread rows (step 6: F2g deletes them with ConditionExpression)
            dt_table = f"adp-{STAGE}-digital-thread"
            for ver, aid in ((1, DEC_ACTION_ID_TL), (2, ISS_ACTION_ID_TL)):
                ddb_adp.put_item(
                    TableName=dt_table,
                    Item={
                        "thread_id": {"S": THREAD_ID},
                        "version": {"N": str(ver)},
                        "status": {"S": "decided"},
                        "action_id": {"S": aid},
                    },
                )

            # Flat objects: curated/engineering/digital_thread/<id>.v<n>.json
            for ver in (1, 2):
                s3_adp.put_object(
                    Bucket=LAKE_BUCKET,
                    Key=f"curated/engineering/digital_thread/{THREAD_ID}.v{ver}.json",
                    Body=b"{}",
                )

            # VIN-list bucket + object at the recorded key (v1 only — S4 F3b)
            try:
                s3_adp.create_bucket(Bucket=VIN_BUCKET)
            except Exception:  # noqa: BLE001
                pass
            s3_adp.put_object(
                Bucket=VIN_BUCKET,
                Key=VIN_KEY_TL,
                Body=b"[]",
            )

            p = tmp_path / f"{RUN_ID}.json"
            p.write_text(_json.dumps(manifest_data))

            def _world_client(service: str, region: str, **_kw: Any) -> Any:
                return w.internal(service, region=region)

            with (
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_manifest_path", lambda rid: str(p)),
                patch.object(_mod, "_resolve_pool_id", lambda idp: "pool-tl"),
                patch.object(_mod, "_check_residue", lambda *a, **kw: None),
                patch.object(_mod, "_run_reconcile_check", lambda *a, **kw: None),
            ):
                res = Results()
                _mod._part_cleanup(res, stage=STAGE, run_id=RUN_ID, allow_writes=True)

            labels = {r[0]: r[1] for r in res.rows}
            assert labels.get("cleanup-thread-lake-objects") == "PASS", (
                f"F2d2/F2g: flat thread-lake objects must be deleted; rows={res.rows}"
            )
            assert labels.get("cleanup-vin-list-objects") == "PASS", (
                f"F2d2: VIN-list objects must be deleted; rows={res.rows}"
            )

            # Direct S3 check: flat objects gone
            flat_pfx = f"curated/engineering/digital_thread/{THREAD_ID}.v"
            flat_rem = [
                o["Key"] for o in s3_adp.list_objects_v2(
                    Bucket=LAKE_BUCKET, Prefix=flat_pfx,
                ).get("Contents", [])
            ]
            assert not flat_rem, (
                f"F2d2: flat thread-lake objects must be gone; remaining={flat_rem!r}"
            )

    # ── Case 2: no objects (writer not deployed) ─────────────────────────────
    with _mock_aws():
        with FiLoopWorld(auto_pump=True) as w:
            s3_adp2 = w.internal("s3", region="us-east-1")
            ddb_adp2 = w.internal("dynamodb", region="us-east-1")
            dt_table2 = f"adp-{STAGE}-digital-thread"
            # Insert DDB rows so step 7c can proceed (even if VIN bucket missing,
            # it raises and FAIL; but for this case we don't care about 7c PASS —
            # we only check 7b and residue).
            ddb_adp2.put_item(
                TableName=dt_table2,
                Item={
                    "thread_id": {"S": THREAD_ID},
                    "version": {"N": "1"},
                    "status": {"S": "decided"},
                    "action_id": {"S": DEC_ACTION_ID_TL},
                },
            )
            # VIN bucket so 7c doesn't raise NoSuchBucket
            try:
                s3_adp2.create_bucket(Bucket=VIN_BUCKET)
            except Exception:  # noqa: BLE001
                pass

            p2 = tmp_path / f"{RUN_ID}-case2.json"
            p2.write_text(_json.dumps(manifest_data))

            def _world_client2(service: str, region: str, **_kw: Any) -> Any:
                return w.internal(service, region=region)

            with (
                patch.object(_mod, "_client", _world_client2),
                patch.object(_mod, "_manifest_path", lambda rid: str(p2)),
                patch.object(_mod, "_resolve_pool_id", lambda idp: "pool-tl"),
                patch.object(_mod, "_check_residue", lambda *a, **kw: None),
                patch.object(_mod, "_run_reconcile_check", lambda *a, **kw: None),
            ):
                res2 = Results()
                _mod._part_cleanup(res2, stage=STAGE, run_id=RUN_ID, allow_writes=True)

            labels2 = {r[0]: r[1] for r in res2.rows}
            assert labels2.get("cleanup-thread-lake-objects") == "PASS", (
                f"F2d2: cleanup-thread-lake-objects must PASS when no objects exist; "
                f"rows={res2.rows}"
            )


def test_f2d2_key_format_matches_adp_handler(tmp_path: Any) -> None:
    """F2d2 fixture: script's thread-lake and VIN-list key derivations match ADP handler.

    Loads thread_lake_key() and THREAD_LAKE_PREFIX from a946eb98 source and asserts
    that the flat prefix the script uses starts every key the handler produces.
    Also asserts the VIN-list key format matches a946eb98:handler.py:1288.
    Skipped if ADP repo absent (like CI without the repo checkout).
    """
    _ADP_REPO = Path(
        __import__("os").environ.get(
            "FI_LOOP_WORLD_ADP_REPO",
            str(Path.home() / "automotive-data-platform-on-aws"),
        )
    )
    handler_py = (
        _ADP_REPO / "platform-foundation" / "source"
        / "lambda" / "digital_thread_writer" / "handler.py"
    )
    if not handler_py.exists():
        pytest.skip("ADP handler not present; set FI_LOOP_WORLD_ADP_REPO")

    # Load thread_lake_key from the deployed source at a946eb98
    import importlib.util as _ilu  # noqa: PLC0415
    _spec_h = _ilu.spec_from_file_location("_adp_handler_f2d2", handler_py)
    _mod_h = _ilu.module_from_spec(_spec_h)  # type: ignore[arg-type]
    # The handler has module-level boto3 calls guarded by env vars; set them
    # to empty so the module imports cleanly without real AWS calls.
    import os as _os  # noqa: PLC0415
    _old_env = {}
    for _k in ("STAGE", "VIN_BUCKET", "ISSUED_RECALLS_BUCKET", "THREAD_LAKE_BUCKET"):
        _old_env[_k] = _os.environ.get(_k)
        _os.environ[_k] = f"_fixture_{_k.lower()}_placeholder"
    try:
        _spec_h.loader.exec_module(_mod_h)  # type: ignore[union-attr]
    except Exception:  # noqa: BLE001
        # Import failure in isolated fixture - still derive what we need from source
        _mod_h = None
    finally:
        for _k, _v in _old_env.items():
            if _v is None:
                _os.environ.pop(_k, None)
            else:
                _os.environ[_k] = _v

    SAMPLE_ID = "thread-0123456789abcdef"
    SAMPLE_VERSION = 2
    SAMPLE_STAGE = "staging"

    # ── thread-lake flat key format ───────────────────────────────────────────
    # Handler: THREAD_LAKE_PREFIX = "curated/engineering/digital_thread/"
    #          key = f"{THREAD_LAKE_PREFIX}{thread_id}.v{version}.json"
    expected_lake_key = (
        f"curated/engineering/digital_thread/{SAMPLE_ID}.v{SAMPLE_VERSION}.json"
    )
    if _mod_h is not None:
        adp_lake_key = _mod_h.thread_lake_key(SAMPLE_ID, SAMPLE_VERSION)
        assert adp_lake_key == expected_lake_key, (
            f"F2d2 fixture: ADP handler thread_lake_key({SAMPLE_ID!r}, {SAMPLE_VERSION}) "
            f"= {adp_lake_key!r}, expected {expected_lake_key!r}"
        )
    # The script's flat prefix must start every key the handler produces.
    expected_flat_prefix = f"curated/engineering/digital_thread/{SAMPLE_ID}.v"
    assert expected_lake_key.startswith(expected_flat_prefix), (
        f"F2d2 fixture: thread_lake_key output {expected_lake_key!r} must start with "
        f"flat prefix {expected_flat_prefix!r}"
    )

    # ── VIN-list key format ───────────────────────────────────────────────────
    # Handler a946eb98:1288: f"digital-thread/{_STAGE}/{thread_id}/v{version}/affected-vins.json"
    # Script: f"digital-thread/{stage}/{thread_id}/v{v}/affected-vins.json" (same format)
    adp_vin_key = (
        f"digital-thread/{SAMPLE_STAGE}/{SAMPLE_ID}/v{SAMPLE_VERSION}/affected-vins.json"
    )
    script_vin_key = (
        f"digital-thread/{SAMPLE_STAGE}/{SAMPLE_ID}/v{SAMPLE_VERSION}/affected-vins.json"
    )
    assert script_vin_key == adp_vin_key, (
        f"F2d2 fixture: VIN-list key mismatch: "
        f"script={script_vin_key!r} ADP={adp_vin_key!r}"
    )


def test_f2d2_mutant_old_folder_prefix_misses_flat_objects(tmp_path: Any) -> None:
    """F2d2 mutant 1: using <thread_id>/ as the only prefix misses flat objects.

    The correct code deletes under BOTH curated/engineering/digital_thread/<id>.v
    (flat, original format) and curated/engineering/digital_thread/<id>/ (new nested).
    A mutant using the old folder prefix only:
        flat_prefix = f".../{thread_id}/"   ← WRONG: was .v, now /
    would list nothing under the flat prefix (since flat objects use .v),
    emit PASS ("no objects found"), and leave flat objects behind.

    This test catches that mutant: it creates ONLY flat objects and asserts the
    flat prefix has no remaining current objects after cleanup.
    """
    import json as _json  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world.world import LAKE_BUCKET  # noqa: PLC0415

    STAGE = "staging"
    ACCOUNT = "123456789012"
    THREAD_ID = "thread-0123456789abcdef"
    RUN_ID = "fi-loop-20261021T160000-mutant1"
    VIN_BUCKET = f"adp-{STAGE}-engineering-vins-{ACCOUNT}-us-east-1"

    manifest_data = {
        "run_id": RUN_ID, "stage": STAGE,
        "pattern_id": "pat-mut1-001",
        "records": {
            "users": [],
            "thread_id": THREAD_ID,
            "thread_versions": [1],
            "decision_action_id": "act-mut1",
            "vin_s3_keys": [f"digital-thread/{STAGE}/{THREAD_ID}/v1/affected-vins.json"],
        },
        "account": ACCOUNT,
        "residue": {},
        "expected_vins": [],
    }

    with _mock_aws():
        with FiLoopWorld(auto_pump=True) as w:
            s3_adp = w.internal("s3", region="us-east-1")
            ddb_adp = w.internal("dynamodb", region="us-east-1")
            dt_table = f"adp-{STAGE}-digital-thread"
            ddb_adp.put_item(
                TableName=dt_table,
                Item={
                    "thread_id": {"S": THREAD_ID},
                    "version": {"N": "1"},
                    "status": {"S": "decided"},
                    "action_id": {"S": "act-mut1"},  # matches decision_action_id
                },
            )

            # Create ONLY flat objects for recorded versions (v1 only in manifest)
            s3_adp.put_object(
                Bucket=LAKE_BUCKET,
                Key=f"curated/engineering/digital_thread/{THREAD_ID}.v1.json",
                Body=b"{}",
            )

            # VIN bucket so 7c can complete; use recorded key
            try:
                s3_adp.create_bucket(Bucket=VIN_BUCKET)
            except Exception:  # noqa: BLE001
                pass
            s3_adp.put_object(
                Bucket=VIN_BUCKET,
                Key=f"digital-thread/{STAGE}/{THREAD_ID}/v1/affected-vins.json",
                Body=b"[]",
            )

            p = tmp_path / f"{RUN_ID}.json"
            p.write_text(_json.dumps(manifest_data))

            def _world_client(service: str, region: str, **_kw: Any) -> Any:
                return w.internal(service, region=region)

            with (
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_manifest_path", lambda rid: str(p)),
                patch.object(_mod, "_resolve_pool_id", lambda idp: "pool-mut1"),
                patch.object(_mod, "_check_residue", lambda *a, **kw: None),
                patch.object(_mod, "_run_reconcile_check", lambda *a, **kw: None),
            ):
                res = Results()
                _mod._part_cleanup(res, stage=STAGE, run_id=RUN_ID, allow_writes=True)

            # Correct code: flat objects deleted → none remaining
            flat_pfx = f"curated/engineering/digital_thread/{THREAD_ID}.v"
            remaining = [
                o["Key"] for o in s3_adp.list_objects_v2(
                    Bucket=LAKE_BUCKET, Prefix=flat_pfx,
                ).get("Contents", [])
            ]
            assert not remaining, (
                f"F2d2 mutant-1: flat thread-lake objects must be gone after cleanup "
                f"(mutant using old <thread_id>/ prefix misses them); "
                f"remaining={remaining!r}"
            )
            labels = {r[0]: r[1] for r in res.rows}
            assert labels.get("cleanup-thread-lake-objects") == "PASS", (
                f"F2d2 mutant-1: cleanup-thread-lake-objects must PASS; rows={res.rows}"
            )


def test_f2d2_mutant_vin_list_left_undeleted(tmp_path: Any) -> None:
    """F2d2 mutant 2: a skip of step 7c leaves VIN-list objects behind.

    If step 7c (VIN-list deletion) is removed (mutant: skip 7c entirely),
    cleanup-vin-list-objects label would not appear, and VIN-list objects remain.
    This test asserts cleanup-vin-list-objects == PASS and VIN-list objects are gone.
    Caught by: PASS assertion + direct S3 assertion.
    """
    import json as _json  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world.world import LAKE_BUCKET  # noqa: PLC0415

    STAGE = "staging"
    ACCOUNT = "123456789012"
    THREAD_ID = "thread-abcdef0123456789"
    RUN_ID = "fi-loop-20261021T170000-mutant2"
    VIN_BUCKET = f"adp-{STAGE}-engineering-vins-{ACCOUNT}-us-east-1"

    manifest_data = {
        "run_id": RUN_ID, "stage": STAGE,
        "pattern_id": "pat-mut2-001",
        "records": {
            "users": [],
            "thread_id": THREAD_ID,
            "thread_versions": [1, 2],
            "decision_action_id": "act-mut2-1",
            "issue_action_id": "act-mut2-2",
            # S4 F3b: recorded VIN-list key (v1's path; v2 copies it)
            "vin_s3_keys": [f"digital-thread/{STAGE}/{THREAD_ID}/v1/affected-vins.json"],
        },
        "account": ACCOUNT,
        "residue": {},
        "expected_vins": [],
    }

    with _mock_aws():
        with FiLoopWorld(auto_pump=True) as w:
            s3_adp = w.internal("s3", region="us-east-1")
            ddb_adp = w.internal("dynamodb", region="us-east-1")
            dt_table = f"adp-{STAGE}-digital-thread"
            for ver, aid in ((1, "act-mut2-1"), (2, "act-mut2-2")):
                ddb_adp.put_item(
                    TableName=dt_table,
                    Item={
                        "thread_id": {"S": THREAD_ID},
                        "version": {"N": str(ver)},
                        "status": {"S": "decided"},
                        "action_id": {"S": aid},
                    },
                )

            # Put flat thread-lake objects
            for ver in (1, 2):
                s3_adp.put_object(
                    Bucket=LAKE_BUCKET,
                    Key=f"curated/engineering/digital_thread/{THREAD_ID}.v{ver}.json",
                    Body=b"{}",
                )

            # VIN bucket + object at the recorded key
            try:
                s3_adp.create_bucket(Bucket=VIN_BUCKET)
            except Exception:  # noqa: BLE001
                pass
            s3_adp.put_object(
                Bucket=VIN_BUCKET,
                Key=f"digital-thread/{STAGE}/{THREAD_ID}/v1/affected-vins.json",
                Body=b"[]",
            )

            p = tmp_path / f"{RUN_ID}.json"
            p.write_text(_json.dumps(manifest_data))

            def _world_client(service: str, region: str, **_kw: Any) -> Any:
                return w.internal(service, region=region)

            with (
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_manifest_path", lambda rid: str(p)),
                patch.object(_mod, "_resolve_pool_id", lambda idp: "pool-mut2"),
                patch.object(_mod, "_check_residue", lambda *a, **kw: None),
                patch.object(_mod, "_run_reconcile_check", lambda *a, **kw: None),
            ):
                res = Results()
                _mod._part_cleanup(res, stage=STAGE, run_id=RUN_ID, allow_writes=True)

            labels = {r[0]: r[1] for r in res.rows}
            assert labels.get("cleanup-vin-list-objects") == "PASS", (
                f"F2d2 mutant-2: cleanup-vin-list-objects must PASS; rows={res.rows}"
            )

            # Direct S3 check: recorded VIN-list key gone
            vin_key = f"digital-thread/{STAGE}/{THREAD_ID}/v1/affected-vins.json"
            resp = s3_adp.list_objects_v2(Bucket=VIN_BUCKET, Prefix=vin_key)
            vin_rem = [o["Key"] for o in resp.get("Contents", [])]
            assert not vin_rem, (
                f"F2d2 mutant-2: VIN-list key {vin_key!r} must be gone after "
                f"cleanup (mutant skipping 7c leaves it); remaining={vin_rem!r}"
            )


