def test_carried_groundings_table_miss_fails_pick(tmp_path: Any) -> None:
    """Carried fix: _has_open_grounding raises on ResourceNotFoundException.

    The pick must FAIL (not silently skip to the next candidate) when the groundings
    table is missing — it means FleetHealthStack hasn't been deployed and the leg
    cannot run safely.

    Mutant caught: restoring `return False` on ResourceNotFoundException makes
    _has_open_grounding return False (not grounded), the pick succeeds, and the
    run continues. With the fix, it raises instead, and the pick FAILs.

    This test uses the REAL _has_open_grounding (not patched) so the mutant in
    its body is visible. The groundings table is NOT in SHAPES so moto raises
    ResourceNotFoundException when queried.
    """
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415
    import uuid as _uuid  # noqa: PLC0415

    VIN = seed.vin(1)
    FLEET_ID = seed.VIN_FLEET[1]
    FINDING_ID = f"FIND-{_uuid.uuid4()}"
    RUN_ID = "fi-loop-20261022T090000-ca771ed0"
    STAGE = "staging"

    with _mock_aws():
        with FiLoopWorld(auto_pump=False, groundings_table=False) as w:
            ddb = w.internal("dynamodb")
            findings_table = _mod._FINDINGS_TABLE.format(stage=STAGE)
            ddb.put_item(
                TableName=findings_table,
                Item={
                    "finding_id": {"S": FINDING_ID},
                    "finding_kind": {"S": _mod._FLEET_HEALTH_FINDING_KIND},
                    "severity": {"S": "p0"},
                    "fleet_id": {"S": FLEET_ID},
                    "scope": {"M": {"vin": {"S": VIN}}},
                    "recommended_action": {"M": {
                        "action_kind": {"S": _mod._GROUND_VEHICLE_KIND},
                        "target_system": {"S": "cms"},
                        "parameters": {"M": {
                            "vehicle_vin": {"S": VIN},
                            "fault_codes": {"L": [{"S": "P0420"}]},
                        }},
                    }},
                    "subject_key": {"S": "ground/1"},
                    "headline": {"S": "Brake fault"},
                    "evidence": {"M": {}},
                },
            )
            w.seed_recall_cache(fleet_id=FLEET_ID, vin_list=[VIN])

            # NOTE: The groundings table (cms-staging-storage-vehicle-groundings) is NOT
            # in SHAPES, so it doesn't exist in moto. The real _has_open_grounding will
            # raise ResourceNotFoundException when it queries this table.
            # We do NOT patch _has_open_grounding so the mutant in its body is visible.

            res_holder: list[Results] = []
            real_rc = _mod.Results

            class _Cap(real_rc):  # type: ignore[misc,valid-type]
                def __init__(self) -> None:
                    super().__init__()
                    res_holder.append(self)

            def _world_client(service: str, region: str, **_kw: Any) -> Any:
                if service == "cognito-idp":
                    return w.idp_client()
                return w.internal(service, region=region)

            mf_path = str(tmp_path / f"{RUN_ID}-manifest.json")
            # S1 fix: pre-write manifest.
            import json as _jj_ca77  # noqa: PLC0415
            Path(mf_path).write_text(_jj_ca77.dumps(
                {"stage": STAGE, "run_id": RUN_ID, "account": "", "records": {}}))
            with (
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_utc_now",
                             lambda: __import__("datetime").datetime(
                                 2026, 10, 22, 9, 0,
                                 tzinfo=__import__("datetime").timezone.utc)),
                # Do NOT patch _has_open_grounding — the mutant is in its body.
                patch.object(_mod, "_get_avx_api_url",
                             lambda cfn, s: "http://fake-avx/"),
                patch.object(_mod, "_get_cms_api_url",
                             lambda cfn, s: "http://fake-cms/"),
                patch.object(_mod, "_manifest_path", lambda rid: mf_path),
                patch.object(_mod, "Results", _Cap),
            ):
                main(["--stage", STAGE, "--run-id", RUN_ID,
                      "--part", "ground",
                      "--allow-writes", "--allow-managed-writes"])

    assert res_holder, "Results not instantiated"
    labels = {r[0]: r[1] for r in res_holder[-1].rows}
    assert labels.get("ground-finding-pick") == "FAIL", (
        "Carried fix: ResourceNotFoundException on groundings table must cause pick FAIL "
        f"(not be swallowed with return False); labels={labels}"
    )


def test_c7_resume_skips_user_creation(tmp_path: Any) -> None:
    """C7: re-run with 'user' already in manifest must NOT call admin_create_user.

    Mutant caught: removing the `manifest_records.get('user') == fleet_op_username`
    resume branch causes a second AdminCreateUser to be made, which the test detects
    by counting AdminCreateUser calls.
    """
    import json as _jj  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415
    import uuid as _uuid  # noqa: PLC0415

    VIN = seed.vin(1)
    FLEET_ID = seed.VIN_FLEET[1]
    FINDING_ID = f"FIND-{_uuid.uuid4()}"
    BOOKING_FINDING_ID = f"FIND-{_uuid.uuid4()}"
    RUN_ID = "fi-loop-20261022T100000-c71e5001"
    STAGE = "staging"
    USERNAME = f"livetest-fi-loop-{RUN_ID}-fo@example.invalid"

    # Pre-write manifest with user + grounded sub-steps already done.
    mf_path = str(tmp_path / f"{RUN_ID}-manifest.json")
    Path(mf_path).write_text(_jj.dumps({
        "run_id": RUN_ID,
        "stage": STAGE,
        "records": {
            "user": USERNAME,
            "ground_vin": VIN,
            "ground_fleet_id": FLEET_ID,
            "ground_finding_id": FINDING_ID,
            "ground_fault_codes": "P0420",
            "ground_action_id": "act-ground-prior",
            "grounded": "true",
            "booking_finding_id": BOOKING_FINDING_ID,
            "book_action_id": "act-book-prior",
            "booked": "true",
        },
    }))

    admin_create_calls = [0]

    with _mock_aws():
        with FiLoopWorld(auto_pump=False) as w:
            ddb = w.internal("dynamodb")
            findings_table = _mod._FINDINGS_TABLE.format(stage=STAGE)
            for fid, kind, skey in [
                (FINDING_ID, _mod._GROUND_VEHICLE_KIND, "ground/1"),
                (BOOKING_FINDING_ID, _mod._BOOK_FLEET_SERVICE_KIND, "service/1"),
            ]:
                ddb.put_item(
                    TableName=findings_table,
                    Item={
                        "finding_id": {"S": fid},
                        "finding_kind": {"S": _mod._FLEET_HEALTH_FINDING_KIND},
                        "severity": {"S": "p0"},
                        "fleet_id": {"S": FLEET_ID},
                        "scope": {"M": {"vin": {"S": VIN}}},
                        "recommended_action": {"M": {
                            "action_kind": {"S": kind},
                            "target_system": {"S": "cms" if kind == _mod._GROUND_VEHICLE_KIND else "dms"},
                            "parameters": {"M": {
                                "vehicle_vin": {"S": VIN},
                                "fault_codes": {"L": [{"S": "P0420"}]},
                            }},
                        }},
                        "subject_key": {"S": skey},
                        "headline": {"S": "Test"},
                        "evidence": {"M": {}},
                    },
                )
            w.seed_recall_cache(fleet_id=FLEET_ID, vin_list=[VIN])

            real_idp = w.idp_client()
            # Pre-create the user so re-auth works.
            pool_id = _mod._resolve_pool_id(real_idp)
            real_idp.admin_create_user(
                UserPoolId=pool_id,
                Username=USERNAME,
                MessageAction="SUPPRESS",
                UserAttributes=[
                    {"Name": "email", "Value": USERNAME},
                    {"Name": "email_verified", "Value": "true"},
                    {"Name": "custom:fleetIds", "Value": FLEET_ID},
                ],
            )
            real_idp.admin_add_user_to_group(
                UserPoolId=pool_id, Username=USERNAME, GroupName="fleet-operator"
            )

            # Wrap to count AdminCreateUser calls.
            orig_admin_create = real_idp.admin_create_user

            def _counting_admin_create(**kwargs: Any) -> Any:
                admin_create_calls[0] += 1
                return orig_admin_create(**kwargs)

            real_idp.admin_create_user = _counting_admin_create  # type: ignore[method-assign]

            res_holder: list[Results] = []
            real_rc = _mod.Results

            class _Cap(real_rc):  # type: ignore[misc,valid-type]
                def __init__(self) -> None:
                    super().__init__()
                    res_holder.append(self)

            def _world_client(service: str, region: str, **_kw: Any) -> Any:
                if service == "cognito-idp":
                    return real_idp
                return w.internal(service, region=region)

            def _stub_http(api_url: str, method: str, route: str,
                           token: str, body: Any, **_kw: Any) -> tuple[int, dict]:
                if method == "POST" and "return-to-service" in route:
                    return (409, {"reason": "fault_not_repaired", "fault_codes": ["P0420"]})
                return (200, {})

            with (
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_utc_now",
                             lambda: __import__("datetime").datetime(
                                 2026, 10, 22, 10, 0,
                                 tzinfo=__import__("datetime").timezone.utc)),
                patch.object(_mod, "_athena_query_paged", lambda *a, **k: []),
                patch.object(_mod, "_get_avx_api_url", lambda cfn, s: "http://fake-avx/"),
                patch.object(_mod, "_get_cms_api_url", lambda cfn, s: "http://fake-cms/"),
                patch.object(_mod, "_http", _stub_http),
                patch.object(_mod, "_count_open_fi_bookings", lambda *a, **k: (1, 1)),
                # Our RO, outside the early-close set (sha256 % 100 = 96): the stand-in
                # step now fails closed without it (2026-10-26 fix).
                patch.object(_mod, "_find_ro_id_for_action", lambda *a, **k: _LIVE_RO_ID),
                patch.object(_mod, "_manifest_path", lambda rid: mf_path),
                patch.object(_mod, "Results", _Cap),
            ):
                main(["--stage", STAGE, "--run-id", RUN_ID,
                      "--part", "ground",
                      "--allow-writes", "--allow-managed-writes"])

    # With resume path: no new user should be created (the existing user is re-authenticated).
    assert admin_create_calls[0] == 0, (
        "C7 resume: re-run with 'user' in manifest must NOT call admin_create_user "
        f"(got {admin_create_calls[0]} calls); did the resume branch get removed?"
    )


