def test_f2g_issue_records_thread_versions_in_manifest(tmp_path: Any) -> None:
    """F2g: _check_thread_versions returns list[int] that issue records in manifest.

    Mutant caught (m-issue-versions): removing the manifest["records"]["thread_versions"]
    assignment means the cleanup step can't determine which rows to delete conditionally.
    """
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415

    STAGE = "staging"
    THREAD_ID = "thread-f2g1111111111111"

    # _check_thread_versions must return [1, 2] → manifest records them.
    with _mock_aws():
        with FiLoopWorld(auto_pump=True) as w:
            ddb_adp = w.internal("dynamodb", region="us-east-1")
            dt_table = f"adp-{STAGE}-digital-thread"
            for ver, status in ((1, "decided"), (2, "issued")):
                ddb_adp.put_item(
                    TableName=dt_table,
                    Item={
                        "thread_id": {"S": THREAD_ID},
                        "version": {"N": str(ver)},
                        "status": {"S": status},
                    },
                )

            res = Results()
            ddb = w.internal("dynamodb", region="us-east-1")
            versions = _mod._check_thread_versions(res, ddb, STAGE, THREAD_ID)

    # F2g: function must return the int versions found, not a bool.
    assert versions == [1, 2], (
        f"F2g: _check_thread_versions must return [1, 2] (found versions); got {versions!r}. "
        f"Mutant: function still returning bool would fail this check."
    )
    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("issue-thread-versions") == "PASS", (
        f"F2g: issue-thread-versions must PASS; rows={res.rows}"
    )


def test_f2g_cleanup_uses_condition_expression(tmp_path: Any) -> None:
    """F2g mutant 1: cleanup must delete DDB rows with ConditionExpression.

    Mutant caught (m-no-condition): removing ConditionExpression from DeleteItem
    would delete rows unconditionally; cleanup must FAIL if the condition is absent
    (simulated by stubbing delete_item to check kwargs).

    The test verifies: DeleteItem is called with ConditionExpression set.
    """
    import json as _json  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415

    STAGE = "staging"
    ACCOUNT = "123456789012"
    THREAD_ID = "thread-ff22222222222222"
    RUN_ID = "fi-loop-20261021T202000-f2g-cond"
    VIN_BUCKET = f"adp-{STAGE}-engineering-vins-{ACCOUNT}-us-east-1"
    LAKE_BUCKET_COND = f"adp-{STAGE}-foundation-lake-{ACCOUNT}-us-east-1"
    DEC_ACTION_ID = "act-dec-f2g-cond-001"
    ISS_ACTION_ID = "act-iss-f2g-cond-002"

    manifest_data = {
        "run_id": RUN_ID, "stage": STAGE,
        "pattern_id": "pat-f2g-cond",
        "records": {
            "users": [],
            "thread_id": THREAD_ID,
            "thread_versions": [1, 2],
            "decision_action_id": DEC_ACTION_ID,
            "issue_action_id": ISS_ACTION_ID,
            "vin_s3_keys": [f"digital-thread/{STAGE}/{THREAD_ID}/v1/affected-vins.json"],
        },
        "account": ACCOUNT,
        "residue": {},
        "expected_vins": [],
    }

    condition_kwargs_seen: list[dict] = []

    with _mock_aws():
        with FiLoopWorld(auto_pump=True) as w:
            ddb_adp = w.internal("dynamodb", region="us-east-1")
            dt_table = f"adp-{STAGE}-digital-thread"
            for ver, aid in ((1, DEC_ACTION_ID), (2, ISS_ACTION_ID)):
                ddb_adp.put_item(
                    TableName=dt_table,
                    Item={
                        "thread_id": {"S": THREAD_ID},
                        "version": {"N": str(ver)},
                        "status": {"S": "decided"},
                        "action_id": {"S": aid},
                    },
                )

            # Stub to capture kwargs while still delegating to moto.
            _real_delete = ddb_adp.delete_item

            def _spy_delete(**kwargs: Any) -> Any:
                condition_kwargs_seen.append(kwargs)
                return _real_delete(**kwargs)

            # Patch the real client at the method level.
            ddb_adp.delete_item = _spy_delete  # type: ignore[method-assign]

            # S3 setup (step 7b lake bucket + 7c VIN bucket).
            try:
                s3_adp = w.internal("s3", region="us-east-1")
                s3_adp.create_bucket(Bucket=LAKE_BUCKET_COND)
                s3_adp.create_bucket(Bucket=VIN_BUCKET)
            except Exception:  # noqa: BLE001
                pass
            # Lake objects for versions 1 and 2 (flat layout).
            for ver in (1, 2):
                w.internal("s3", region="us-east-1").put_object(
                    Bucket=LAKE_BUCKET_COND,
                    Key=f"curated/engineering/digital_thread/{THREAD_ID}.v{ver}.json",
                    Body=b"{}",
                )
            # VIN-list object at the recorded key (v1's path — v2 copies it).
            w.internal("s3", region="us-east-1").put_object(
                Bucket=VIN_BUCKET,
                Key=f"digital-thread/{STAGE}/{THREAD_ID}/v1/affected-vins.json",
                Body=b"[]",
            )

            p = tmp_path / f"{RUN_ID}.json"
            p.write_text(_json.dumps(manifest_data))

            def _world_client(service: str, region: str, **_kw: Any) -> Any:
                cl = w.internal(service, region=region)
                if service == "dynamodb":
                    # Attach spy.
                    cl.delete_item = _spy_delete  # type: ignore[method-assign]
                return cl

            with (
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_manifest_path", lambda rid: str(p)),
                patch.object(_mod, "_resolve_pool_id", lambda idp: "pool-f2g-cond"),
                patch.object(_mod, "_check_residue", lambda *a, **kw: None),
                patch.object(_mod, "_run_reconcile_check", lambda *a, **kw: None),
            ):
                res = Results()
                _mod._part_cleanup(res, stage=STAGE, run_id=RUN_ID, allow_writes=True)

    # Every delete_item call against the digital-thread table must carry ConditionExpression.
    thread_deletes = [
        kw for kw in condition_kwargs_seen
        if kw.get("TableName", "").endswith("digital-thread")
    ]
    assert thread_deletes, (
        "F2g mutant-1: no delete_item calls against digital-thread table; "
        "step 6 deletion logic missing"
    )
    for kw in thread_deletes:
        assert "ConditionExpression" in kw, (
            f"F2g mutant-1: delete_item call against digital-thread has no "
            f"ConditionExpression — would delete without a condition: {kw}"
        )

    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("cleanup-thread-rows-deleted") == "PASS", (
        f"F2g mutant-1: cleanup-thread-rows-deleted must PASS; rows={res.rows}"
    )


