def test_w3_f3b_thread_id_recorded_at_decision_time(tmp_path: Any) -> None:
    """W3 F3b / t5 re-anchored: issue must record thread_id and v1 inside the
    decision-approve signal hold, before any later step can fail.

    Mutant caught (t5-reanchored): removing the inside-hold recording means thread_id
    is only set from the quality.issue Finding; if issue stops after the decision but
    before finding the Finding, cleanup has no thread_id and silently skips steps 6-7e.

    Verifies:
    - After the decision approve 202 (and no further approves), the manifest has
      thread_id == target_ref and thread_versions includes 1.
    """
    import json as _json  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415

    STAGE = "staging"
    THREAD_ID_W3 = "thread-0300000000000003"
    DEC_ACTION_ID_W3 = "act-dec-w3-issue-001"
    RUN_ID = "fi-loop-20261022T103000-f3b-w3"

    # The decision response: sets target_ref = THREAD_ID_W3.
    decision_resp = {
        "action_id": DEC_ACTION_ID_W3,
        "status": "executed",
        "action_kind": "record_engineering_decision",
        "target_ref": THREAD_ID_W3,
    }
    call_count: list[int] = [0]

    approve_done: list[bool] = [False]

    def _capturing_http(url: str, method: str, path: str, token: str, body: Any) -> tuple:
        call_count[0] += 1
        if "investigations" in path and method == "POST" and "approve" not in path:
            # Investigation POST: return investigation_id.
            return 202, {"investigation_id": "inv-w3-test-001", "status": "pending"}
        if "approve" in path and not approve_done[0]:
            approve_done[0] = True
            return 202, decision_resp
        # Any call after the decision approve → raise to stop issue.
        raise RuntimeError("test: stop after decision approve")

    def _check_tier2_stub(res: Any, lam: Any, fn: str) -> bool:
        check(res, "pre-tier2-code-readers", True, "stub")
        return True

    p = tmp_path / f"{RUN_ID}.json"
    p.write_text(_json.dumps({
        "run_id": RUN_ID, "stage": STAGE,
        "pattern_id": "FM-W3-001",
        "account": "123456789012",
        "safe_failure_modes": {"fm-w3-001": "opt-hardware-recall"},  # F6b
        "pre_verdict": "passed",
        "records": {
            "users": [],
        },
        "expected_vins": ["VIN-W3-001"],
        "residue": {},
    }))

    with _mock_aws():
        with FiLoopWorld(auto_pump=True) as w:
            # Seed the fault-patterns table with the test pattern so the W1 re-read passes.
            ddb_adp_w3 = w.internal("dynamodb", region="us-east-1")
            patterns_table_w3 = f"adp-{STAGE}-fault-patterns"
            ddb_adp_w3.put_item(
                TableName=patterns_table_w3,
                Item={
                    "pattern_id": {"S": "FM-W3-001"},
                    "cohort_dimension": {"S": "supplier_lot"},
                    "cohort_value": {"S": "SUP-W3/LOT-W3"},
                    "supplier_id": {"S": "SUP-W3"},
                    "supplier_lot": {"S": "LOT-W3"},
                },
            )

            def _check_tier2_stub_w3(res2: Any, lam: Any, fn: str) -> bool:
                check(res2, "pre-tier2-code-readers", True, "stub")
                return True

            import contextlib as _ctx_w3  # noqa: PLC0415
            _w3_patchers = [
                patch.object(_mod, "_client", lambda svc, region, **_: w.internal(svc, region=region)),
                patch.object(_mod, "_manifest_path", lambda rid: str(p)),
                patch.object(_mod, "_http", _capturing_http),
                patch.object(_mod, "_check_tier2_code", _check_tier2_stub_w3),
                patch.object(_mod, "_check_recall_table_exists", lambda *a, **kw: True),
                patch.object(_mod, "_check_view_sql_unions_issued", lambda *a, **kw: True),
                patch.object(_mod, "_check_esm_enabled", lambda *a, **kw: True),
                patch.object(_mod, "_check_dlq_empty", lambda *a, **kw: True),
                patch.object(_mod, "_check_no_open_livetest", lambda *a, **kw: True),
                patch.object(_mod, "_maint_window_guard", lambda ts: None),
                patch.object(_mod, "_schedule_guard", lambda *a, **kw: None),
                patch.object(_mod, "_create_temp_user",
                             lambda *a, **kw: ("test-user-w3", "pass-w3", "tok-w3")),
                patch.object(_mod, "_delete_temp_user", lambda *a, **kw: None),
                patch.object(_mod, "_pick_pattern",
                             lambda *a, **kw: ("FM-W3-001", "fmd-001",
                                               "PAT-W3-001", "v-value",
                                               "opt-w3-hardware")),
                patch.object(_mod, "_get_avx_api_url",
                             lambda *a, **kw: "https://api.example.com"),
                patch.object(_mod, "_resolve_pool_id",
                             lambda *a, **kw: "pool-w3-test"),
                patch.object(_mod, "_password_client",
                             lambda *a, **kw: "client-w3-test"),
                patch.object(_mod, "_poll_investigation",
                             lambda *a, **kw: {"status": "completed",
                                              "finding_id": "fnd-inv-w3-finding-001",
                                              "investigation_id": "inv-w3-test-001"}),
                # F6b: stub re-check to PASS so test reaches decision approve
                patch.object(
                    _mod, "_recheck_investigation_finding",
                    lambda res, ddb_avx, ddb_adp, stage, fid, sfms: (
                        "fm-w3-001", "opt-hardware-recall", True
                    ),
                ),
                patch.object(_mod, "_check_quality_issue_finding",
                             lambda *a, **kw: ("fnd-iss-w3", THREAD_ID_W3, "draft-w3")),
            ]
            with _ctx_w3.ExitStack() as _stk_w3:
                for _pt in _w3_patchers:
                    _stk_w3.enter_context(_pt)
                res = Results()
                try:
                    _mod._part_issue(res, stage=STAGE, run_id=RUN_ID, allow_writes=True)
                except Exception:  # noqa: BLE001
                    pass

    manifest_after = _json.loads(p.read_text())
    recs = manifest_after.get("records", {})

    assert recs.get("thread_id") == THREAD_ID_W3, (
        f"W3 F3b / t5: manifest must have thread_id={THREAD_ID_W3!r} recorded "
        f"inside the decision signal hold; got thread_id={recs.get('thread_id')!r}. "
        f"Mutant (no inside-hold recording) would leave thread_id empty here."
    )
    tv = recs.get("thread_versions") or []
    assert 1 in [int(v) for v in tv], (
        f"W3 F3b / t5: manifest must have version 1 in thread_versions (recorded "
        f"at decision time); got thread_versions={tv!r}. "
        f"Mutant (only records versions after issue_recall) would leave this empty."
    )


