def test_w5_f3b_reconcile_command_has_no_apply(tmp_path: Any) -> None:
    """W5 F3b / r2 re-anchored: reconcile subprocess must never include --apply.

    Captures subprocess.run to check the exact command line.

    Mutant caught (r2-reanchored): adding --apply to the command list would cause
    this test to fail (assert "--apply" not in args).  In a live run with --apply,
    ADP's reconcile puts missing lake objects — a write from a part supposed to be
    read-only.
    """
    import subprocess as _sub  # noqa: PLC0415
    import tempfile as _tmp  # noqa: PLC0415
    import os as _os  # noqa: PLC0415

    STAGE = "staging"
    captured_args: list[list[str]] = []

    def _fake_subprocess_run(args: Any, **kwargs: Any) -> Any:
        """Capture args; return plausible output for git archive and reconcile."""
        import types as _t  # noqa: PLC0415
        import tarfile as _tf  # noqa: PLC0415
        import io as _io_fake  # noqa: PLC0415
        if isinstance(args, list):
            captured_args.append(list(str(a) for a in args))
        # git archive call: return a minimal valid tar archive containing
        # the required paths so the script proceeds past the extraction.
        if any("git" in str(a) and "archive" in str(a) for a in args) or (
            isinstance(args, list) and "git" in str(args[0])
        ):
            # Create a minimal tar with the two required files.
            buf = _io_fake.BytesIO()
            with _tf.open(fileobj=buf, mode="w:") as tar:
                for rel_path in ["platform-foundation/scripts/reconcile_thread_lake.py",
                                  "platform-foundation/source/lambda/digital_thread_writer/handler.py"]:
                    content = b"# stub\n"
                    info = _tf.TarInfo(name=rel_path)
                    info.size = len(content)
                    tar.addfile(info, _io_fake.BytesIO(content))
            buf.seek(0)
            return _t.SimpleNamespace(returncode=0, stdout=buf.read(), stderr=b"")
        # Reconcile script call: return a clean dry-run JSON report.
        reconcile_json = ('{"mode": "dry-run", "stage": "staging", '
                          '"missing": [], "differs": [], "extra": [], '
                          '"unprojectable": [], "applied": []}')
        return _t.SimpleNamespace(returncode=0, stdout=reconcile_json, stderr="")

    # Build a fake temp dir with the required script path so the subprocess
    # invocation passes the pre-checks in _run_reconcile_subprocess.
    with _tmp.TemporaryDirectory(prefix="test_w5_f3b_") as td:
        script_dir = _os.path.join(td, "platform-foundation", "scripts")
        _os.makedirs(script_dir, exist_ok=True)
        script_path = _os.path.join(script_dir, "reconcile_thread_lake.py")
        open(script_path, "w").close()  # noqa: WPS515

        fake_python = _os.path.join(td, "python3")
        open(fake_python, "w").close()  # noqa: WPS515

        with (
            patch.object(_mod, "_ADP_REPO", td),
            patch.object(_mod, "_ADP_PYTHON", fake_python),
            patch(_sub.__name__ + ".run", _fake_subprocess_run),
        ):
            rc, report = _mod._run_reconcile_subprocess(STAGE)

    assert captured_args, (
        "W5 F3b: subprocess.run was not called; "
        "the reconcile command must be executed via subprocess.run"
    )
    for args in captured_args:
        # Only check the script invocation (not git archive).
        if any("reconcile_thread_lake" in a for a in args):
            assert "--apply" not in args, (
                f"W5 F3b / r2: reconcile command must NEVER include --apply; "
                f"got args={args!r}.  Mutant (adds --apply) caught by this assertion."
            )


def test_w5_f3b_reconcile_dict_unprojectable_fails() -> None:
    """W5 F3b / r3 re-anchored: a dict unprojectable entry whose 'key' contains this
    thread's id must cause FAIL.

    reconcile() emits dict entries for unprojectable versions:
        {"key": "curated/.../thread-X.v1.json", "missing_columns": [...]}

    Mutant caught (r3-reanchored): replacing dict key extraction with empty string
    (``entry.get("key") or ""`` → ``""``) means the thread_id check never fires
    and the dict entry is silently ignored.

    Loads the real reconcile() from ADP f54ea20d via git show to build a report
    with a genuine dict unprojectable entry.
    """
    import subprocess as _sub  # noqa: PLC0415
    import tempfile as _tmp  # noqa: PLC0415
    import importlib.util as _ilu  # noqa: PLC0415
    import os as _os  # noqa: PLC0415

    adp_repo = str(Path.home() / "automotive-data-platform-on-aws")
    THREAD_ID_R3 = "thread-aabbccdd11223344"

    # 1. Load reconcile() from ADP f54ea20d.
    res_script = _sub.run(
        ["git", "-C", adp_repo, "show",
         "f54ea20d:platform-foundation/scripts/reconcile_thread_lake.py"],
        capture_output=True, text=True,
    )
    assert res_script.returncode == 0, (
        f"git show f54ea20d reconcile_thread_lake.py failed: {res_script.stderr!r}"
    )
    reconcile_src = res_script.stdout

    # Also need the handler (writer) for _writer() inside reconcile.
    res_handler = _sub.run(
        ["git", "-C", adp_repo, "show",
         "f54ea20d:platform-foundation/source/lambda/digital_thread_writer/handler.py"],
        capture_output=True, text=True,
    )
    assert res_handler.returncode == 0, (
        f"git show f54ea20d handler.py failed: {res_handler.stderr!r}"
    )

    with _tmp.TemporaryDirectory(prefix="test_w5_f3b_reconcile_") as td:
        # Write both files so reconcile_thread_lake.py can import handler via its path.
        pf_dir = _os.path.join(td, "platform-foundation")
        scripts_dir = _os.path.join(pf_dir, "scripts")
        handler_dir = _os.path.join(
            pf_dir, "source", "lambda", "digital_thread_writer"
        )
        _os.makedirs(scripts_dir, exist_ok=True)
        _os.makedirs(handler_dir, exist_ok=True)
        reconcile_path = _os.path.join(scripts_dir, "reconcile_thread_lake.py")
        handler_path = _os.path.join(handler_dir, "handler.py")
        open(_os.path.join(handler_dir, "__init__.py"), "w").close()  # noqa: WPS515
        with open(reconcile_path, "w") as fh:
            fh.write(reconcile_src)
        with open(handler_path, "w") as fh:
            fh.write(res_handler.stdout)

        spec = _ilu.spec_from_file_location("reconcile_tl_f54ea20d", reconcile_path)
        assert spec and spec.loader
        rec_mod = _ilu.module_from_spec(spec)
        spec.loader.exec_module(rec_mod)  # type: ignore[union-attr]

        # 2. Build a report with a dict unprojectable entry by calling reconcile()
        #    with a thread item that has a missing THREAD_LAKE_REQUIRED column.
        #    THREAD_LAKE_REQUIRED = ("thread_id", "version", "status", "code_family")
        #    Omit "code_family" → unprojectable dict entry.
        thread_item = {
            "thread_id": THREAD_ID_R3,
            "version": 1,
            "status": "decided",
            # "code_family" intentionally omitted → unprojectable
        }
        # listed = empty set (no existing lake keys), read_body = never called.
        report = rec_mod.reconcile(
            items=[thread_item],
            listed=set(),
            read_body=lambda key: b"",
        )

        # The reconcile() output includes a dict unprojectable entry.
        assert report.get("unprojectable"), (
            f"expected non-empty unprojectable list; got report={report!r}"
        )
        unprojectable_entry = report["unprojectable"][0]
        assert isinstance(unprojectable_entry, dict), (
            f"reconcile() must emit dict for unprojectable; got {unprojectable_entry!r}"
        )

    # 3. Feed this real report to _run_reconcile_check via patched subprocess.
    fake_report = {
        "mode": "dry-run",
        "stage": "staging",
        "missing": [],
        "differs": [],
        "extra": [],
        "unprojectable": [unprojectable_entry],  # the real dict from reconcile()
        "applied": [],
    }

    with patch.object(_mod, "_run_reconcile_subprocess",
                      lambda stage: (1, fake_report)):
        res = Results()
        _mod._run_reconcile_check(
            res, "staging", THREAD_ID_R3,
            label_prefix="test-r3-reanchored",
            after_cleanup=False,
        )

    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("test-r3-reanchored-ok") == "FAIL", (
        "W5 F3b / r3: a dict unprojectable entry whose 'key' contains this thread's "
        "id must cause FAIL.  Mutant (extracts empty string from dict) would ignore "
        f"the entry and PASS; rows={res.rows}"
    )


def test_s4_f3b_vin_list_uses_recorded_key_not_derived(tmp_path: Any) -> None:
    """S4 F3b: step 7c must delete the key named by recorded vin_s3_keys, not a
    derived v2/affected-vins.json path.

    The issued version (v2) copies v1's affected_vins_s3_key; the current writer
    never creates a v2/affected-vins.json object.  If cleanup derived keys from
    version numbers, it would add a delete marker on an object it never wrote.

    Verifies:
    - v1/affected-vins.json IS deleted (the recorded key).
    - v2/affected-vins.json is NOT deleted (derived but not in vin_s3_keys).
    """
    import json as _json  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415

    STAGE = "staging"
    ACCOUNT = "123456789012"
    THREAD_ID = "thread-0400000000004400"
    RUN_ID = "fi-loop-20261022T105000-f3b-s4"
    VIN_BUCKET = f"adp-{STAGE}-engineering-vins-{ACCOUNT}-us-east-1"
    LAKE_BUCKET_S4 = f"adp-{STAGE}-foundation-lake-{ACCOUNT}-us-east-1"
    DEC_ACTION_ID_S4 = "act-dec-s4-001"
    ISS_ACTION_ID_S4 = "act-iss-s4-002"
    VIN_KEY_V1 = f"digital-thread/{STAGE}/{THREAD_ID}/v1/affected-vins.json"
    VIN_KEY_V2 = f"digital-thread/{STAGE}/{THREAD_ID}/v2/affected-vins.json"  # never written

    manifest_data = {
        "run_id": RUN_ID, "stage": STAGE,
        "pattern_id": "pat-f3b-s4",
        "records": {
            "users": [],
            "thread_id": THREAD_ID,
            "thread_versions": [1, 2],
            "decision_action_id": DEC_ACTION_ID_S4,
            "issue_action_id": ISS_ACTION_ID_S4,
            # Only v1's key — v2 copies it; v2's derived path was never written.
            "vin_s3_keys": [VIN_KEY_V1],
        },
        "account": ACCOUNT,
        "residue": {},
        "expected_vins": [],
    }

    with _mock_aws():
        with FiLoopWorld(auto_pump=True) as w:
            ddb_adp = w.internal("dynamodb", region="us-east-1")
            dt_table = f"adp-{STAGE}-digital-thread"
            for ver, aid in ((1, DEC_ACTION_ID_S4), (2, ISS_ACTION_ID_S4)):
                ddb_adp.put_item(
                    TableName=dt_table,
                    Item={
                        "thread_id": {"S": THREAD_ID},
                        "version": {"N": str(ver)},
                        "status": {"S": "decided"},
                        "action_id": {"S": aid},
                    },
                )

            s3 = w.internal("s3", region="us-east-1")
            try:
                s3.create_bucket(Bucket=LAKE_BUCKET_S4)
                s3.create_bucket(Bucket=VIN_BUCKET)
            except Exception:  # noqa: BLE001
                pass
            for ver in (1, 2):
                s3.put_object(
                    Bucket=LAKE_BUCKET_S4,
                    Key=f"curated/engineering/digital_thread/{THREAD_ID}.v{ver}.json",
                    Body=b"{}",
                )
            # Both VIN keys exist in the bucket.
            for key in (VIN_KEY_V1, VIN_KEY_V2):
                s3.put_object(Bucket=VIN_BUCKET, Key=key, Body=b"[]")

            p = tmp_path / f"{RUN_ID}.json"
            p.write_text(_json.dumps(manifest_data))

            def _world_client(svc: str, region: str, **_: Any) -> Any:
                return w.internal(svc, region=region)

            with (
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_manifest_path", lambda rid: str(p)),
                patch.object(_mod, "_resolve_pool_id", lambda idp: "pool-f3b-s4"),
                patch.object(_mod, "_check_residue", lambda *a, **kw: None),
                patch.object(_mod, "_run_reconcile_check", lambda *a, **kw: None),
            ):
                res = Results()
                _mod._part_cleanup(res, stage=STAGE, run_id=RUN_ID, allow_writes=True)

            # After cleanup: v1 deleted, v2 still present.
            try:
                s3.head_object(Bucket=VIN_BUCKET, Key=VIN_KEY_V1)
                v1_present = True
            except Exception:  # noqa: BLE001
                v1_present = False
            try:
                s3.head_object(Bucket=VIN_BUCKET, Key=VIN_KEY_V2)
                v2_present = True
            except Exception:  # noqa: BLE001
                v2_present = False

    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("cleanup-vin-list-objects") == "PASS", (
        "S4 F3b: cleanup-vin-list-objects must PASS for the recorded v1 key; "
        f"rows={res.rows}"
    )
    assert not v1_present, (
        "S4 F3b: v1/affected-vins.json (the recorded key) must be deleted by cleanup."
    )
    assert v2_present, (
        "S4 F3b: v2/affected-vins.json must NOT be deleted (not in vin_s3_keys). "
        "Mutant (derives keys from version numbers) would delete it and this assertion "
        "would fail."
    )


