# ── F3e: W7 pre_verdict gate in issue ─────────────────────────────────────────

def test_w7_issue_refuses_when_pre_verdict_failed(tmp_path: Any) -> None:
    """W7 fix: issue refuses when pre_verdict is 'failed' in the manifest.

    New mutant (pre_verdict_gate): if the pre_verdict check is removed, issue
    proceeds to approve even when pre had FAIL rows or empty expected_vins.

    Catches the mutant: replace
      if pre_verdict_chk != "passed": → if False:
    With the check, issue-pre-verdict is FAIL and no approve happens.
    Without the check, it proceeds past the gate.
    """
    import json as _json_w7  # noqa: PLC0415

    RUN_ID = "fi-loop-20261021T120000-pv-failed"
    manifest_data = {
        "run_id": RUN_ID, "stage": "staging",
        "part": "pre", "account": "123456789012",
        "pattern_id": "pat-pv-001",
        "failure_mode_id": "",
        "remedy_option_id": "opt-recall-001",
        # W7: pre_verdict is "failed" — expected_vins was empty
        "pre_verdict": "failed",
        "expected_vins": [],
        "records": {},
    }
    p = tmp_path / f"{RUN_ID}.json"
    p.write_text(_json_w7.dumps(manifest_data))

    approve_calls: list[str] = []

    def _fake_http(url: str, method: str, path: str, token: str,
                   body: dict | None = None) -> tuple[int, dict]:
        if method == "POST":
            approve_calls.append(path)
        return 200, {}

    def _fake_client(svc: str, reg: str, **kw: Any) -> Any:
        m = MagicMock()
        if svc == "cognito-idp":
            m.admin_create_user.return_value = {"User": {"Username": "u"}}
        elif svc == "scheduler":
            m.list_schedules.return_value = {"Schedules": []}
        return m

    with (
        patch.object(_mod, "_manifest_path", lambda rid: str(p)),
        patch.object(_mod, "_client", _fake_client),
        patch.object(_mod, "_http", _fake_http),
        patch.object(_mod, "_utc_now",
                     lambda: __import__("datetime").datetime(
                         2026, 10, 21, 10, 0, tzinfo=__import__("datetime").timezone.utc)),
        patch.object(_mod, "_check_tier2_code",
                     lambda res, lam, fn: (_mod.check(res, "pre-tier2-code-readers", True, "ok"), True)[1]),
        patch.object(_mod, "_check_recall_table_exists",
                     lambda res, glue, stg: (_mod.check(res, "pre-recall-table", True, "ok"), True)[1]),
        patch.object(_mod, "_check_view_sql_unions_issued",
                     lambda res, glue, stg: (_mod.check(res, "pre-view-sql", True, "ok"), True)[1]),
        patch.object(_mod, "_check_esm_enabled",
                     lambda res, lam, stg, reg: (_mod.check(res, "pre-esm-enabled", True, "ok"), True)[1]),
        patch.object(_mod, "_check_dlq_empty",
                     lambda res, sqs, stg: (_mod.check(res, "pre-dlq-empty", True, "ok"), True)[1]),
        patch.object(_mod, "_check_no_open_livetest",
                     lambda res, idp, stg: (_mod.check(res, "pre-no-open-livetest", True, "ok"), True)[1]),
        patch.object(_mod, "_schedule_guard", lambda *a, **kw: None),
        patch.object(_mod, "_POLL_SLEEP_S", 0.0),
    ):
        res = Results()
        _mod._part_issue(res, stage="staging", run_id=RUN_ID, allow_writes=True)

    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("issue-pre-verdict") == "FAIL", (
        f"W7: pre_verdict='failed' must produce FAIL on issue-pre-verdict; "
        f"rows={res.rows}"
    )
    assert not approve_calls, (
        f"W7: no POST calls should happen when pre_verdict='failed'; "
        f"got approve_calls={approve_calls!r}"
    )


