# ── F3e: W9 _pick_pattern Athena branch + n14 filter ─────────────────────────

def test_c10_pick_pattern_requires_hardware_recall_option_corpus_shaped(
    tmp_path: Any,
) -> None:
    """W9/n14 fix: _pick_pattern must skip a candidate with only supplier_containment.

    Uses corpus-shaped data matching ADP 87d3025b failure_modes.yaml FM-DU-01
    and FM-CHG-01: supplier_containment comes FIRST (positive lead_time), then
    hardware_recall.  Without the remedy_type == 'hardware_recall' filter
    (mutant n14), the pick records the containment option and issue approves it.

    Catches n14: replace
        if rtype != "hardware_recall": continue
      → if False: continue
    which makes the pick accept the first option (containment).
    """
    # FM-DU-01 / FM-CHG-01 shape: containment first, recall second
    corpus_containment_first = _corpus_with_options([
        {
            "remedy_option_id": "OPT-FM-DU-01-A",
            "remedy_type": "supplier_containment",
            "lead_time_weeks": 6,   # positive — mutant would accept this
        },
        {
            "remedy_option_id": "OPT-FM-DU-01-B",
            "remedy_type": "hardware_recall",
            "lead_time_weeks": 18,
        },
    ])
    ddb = _ddb_stub(corpus_item=corpus_containment_first)
    res = Results()
    pattern_row, fmid, pid, cause, oid = _mod._pick_pattern(res, ddb, "staging")
    labels = {r[0]: r[1] for r in res.rows}
    assert pattern_row is not None, (
        f"n14: _pick_pattern should succeed (hardware_recall present); rows={labels}"
    )
    # F6c: _pick_pattern now returns safe_failure_modes = {fm_id: hw_recall_opt_id}
    # instead of a bare option_id string.  The n14 property: the value in the
    # safe_failure_modes dict must be the hardware_recall option (OPT-FM-DU-01-B),
    # not the containment option (OPT-FM-DU-01-A).  Mutant n14 drops the
    # remedy_type filter, so it accepts the first (containment) option and
    # safe_failure_modes would map to OPT-FM-DU-01-A.
    assert isinstance(oid, dict), (
        f"n14: oid must be a dict (safe_failure_modes); got {type(oid).__name__!r}"
    )
    assert list(oid.values()) == ["OPT-FM-DU-01-B"], (
        f"n14: safe_failure_modes must map to hardware_recall OPT-FM-DU-01-B, "
        f"not containment OPT-FM-DU-01-A; got oid={oid!r}. "
        f"Mutant n14 (drop remedy_type filter) would map to OPT-FM-DU-01-A."
    )
    assert labels.get("pre-pattern-pick") == "PASS", (
        f"n14: pre-pattern-pick must PASS; rows={labels}"
    )


def test_c10_pick_pattern_rejects_zero_managed_count_athena_branch(
    tmp_path: Any,
) -> None:
    """W9/c10c fix: _pick_pattern skips a candidate when Athena returns count=0.

    The live pick uses Athena to count managed VINs × lot.  When the count is 0
    (no managed VINs for this lot), the candidate must be skipped.

    Catches c10c: replace
        if int(cnt_str) == 0: continue
      → if False: continue
    which makes the pick accept a candidate with zero managed VINs.

    The pattern has a valid cause_value matching _LOT_RE ("SUP-A/LOT-001") so
    the Athena branch is taken (not the affected_vins fallback).
    """
    CAUSE_VALUE = "SUP-A/LOT-001"
    assert _mod._LOT_RE.fullmatch(CAUSE_VALUE), (
        f"cause_value {CAUSE_VALUE!r} must match _LOT_RE to use Athena branch"
    )

    corpus_ok = _corpus_with_options([{
        "remedy_option_id": "opt-recall-001",
        "remedy_type": "hardware_recall",
        "lead_time_weeks": 8,
    }])

    # F6c: use F6a producer shape — no failure_mode_id; add group-top fields.
    # The old shape (with failure_mode_id, no pattern_group_id/candidate_rank/code_family)
    # would fail the group-top rule (rule 2) before reaching Athena.
    pattern_with_affected_vins = [{
        "pattern_id": {"S": "pat-supplier-lot-001"},
        "pattern_group_id": {"S": "pat-supplier-lot-001"},  # group-top rule (F6a)
        "candidate_rank": {"N": "1"},
        "code_family": {"S": "P1AB"},  # maps to corpus symptom_codes P1AB0/P1AB1 (F6a)
        "cohort_dimension": {"S": "supplier_lot"},
        "cohort_value": {"S": CAUSE_VALUE},
        "affected_vins": {"L": [{"S": "1MRDNA0A4MA000001"}]},  # non-empty: fallback ok
    }]
    ddb = _ddb_stub(pattern_items=pattern_with_affected_vins, corpus_item=corpus_ok)

    # Fake Athena that returns count=0 for the lot
    class _FakeAthena:
        def __init__(self) -> None:
            self.called = False

        def __call__(self, athena: Any, stage: str, sql: str, label: str) -> list[dict]:
            self.called = True
            return [{"cnt": "0"}]  # zero managed VINs for this lot

    fake_paged = _FakeAthena()

    with patch.object(_mod, "_athena_query_paged", fake_paged):
        res = Results()
        # Pass fake_athena object so _pick_pattern takes the Athena branch
        fake_athena_client = MagicMock()
        pattern_row, _, _, _, _ = _mod._pick_pattern(
            res, ddb, "staging", athena=fake_athena_client
        )

    labels = {r[0]: r[1] for r in res.rows}
    assert fake_paged.called, (
        "c10c: Athena query must have been called (cause_value matches _LOT_RE)"
    )
    assert pattern_row is None, (
        f"c10c: _pick_pattern must skip candidate when Athena returns count=0; "
        f"got pattern_row={pattern_row!r}. "
        f"Mutant c10c (if False: continue) would accept the candidate."
    )
    assert labels.get("pre-pattern-pick") == "FAIL", (
        f"c10c: pre-pattern-pick must FAIL (no valid candidate); rows={labels}"
    )


# ── F3e: W8 component_lots content check ─────────────────────────────────────

def test_w8_component_lots_empty_list_fails_with_cause_value(tmp_path: Any) -> None:
    """W8 fix: component_lots: [] FAILs when cause_value is given.

    Probe P6 from the review: component_lots=[] PASSed the old presence-only check.
    With the W8 fix, an empty list has no entry matching the expected supplier_lot.

    Catches the new component_lots presence-only mutant:
        elif cause_value: → drop the elif (presence only)
    """
    CAMPAIGN_ID = "MRD-2026-W8A"
    VIN = "VIN00000000000001"
    FLEET_ID = "fleet-001"
    CAUSE_VALUE = "SUP-1/LOT-A"  # → expected_lot = "LOT-A"

    finding = {
        "finding_id": "FIND-W8A-001",
        "finding_kind": _mod._RECALL_FINDING_KIND,
        "subject_key": f"{CAMPAIGN_ID}/parts_expected/1",
        "fleet_id": FLEET_ID,
        "scope": {"vin": VIN},
        "evidence": [
            {
                "kind": "recall.rule",
                "value": {"component_lots": [], "model_year_min": None, "model_year_max": None},
                "source": "adp",
            }
        ],
        "disclosure_txt": "S\n\nC\n\nR",
    }

    class _FakeDDBW8A:
        def scan(self, **kw: Any) -> dict:
            return {"Items": [{k: {"S": str(v)} if isinstance(v, str) else v
                               for k, v in finding.items()}]}

    res = Results()
    _mod._check_recall_findings(
        res, _FakeDDBW8A(), "staging", CAMPAIGN_ID, [VIN],
        cause_value=CAUSE_VALUE,
    )
    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("after-run-findings-recall-rule") == "FAIL", (
        f"W8: component_lots=[] must FAIL when cause_value={CAUSE_VALUE!r} "
        f"(expected supplier_lot='LOT-A' not found in []); rows={res.rows}"
    )


