# ── F3e: S9 no-booking-Actions check ─────────────────────────────────────────

def test_s9_after_run_fails_when_recall_finding_has_booking_action(
    tmp_path: Any,
) -> None:
    """S9 fix: after-run FAILs when a recall Finding has a booking Action.

    A book_fleet_service Action on a recall Finding means a service booking was
    misrouted to a recall Finding (should only be on fleet.health.service).

    Catches the 'no-booking-Actions check removed' mutant:
        replace `not book_on_recall` check with `True`

    Uses a minimal manifest and stubs all parts except the Actions query.
    """
    import json as _json_s9  # noqa: PLC0415
    from moto import mock_aws as _mock_aws_s9  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415

    RUN_ID = "fi-loop-20261021T070000-aabbccdd"
    STAGE = "staging"
    CAMPAIGN_ID = "MRD-2026-502"
    VIN = seed.vin(1)
    FLEET_ID = seed.VIN_FLEET[1]
    FINDING_ID = "FIND-S9-RECALL-001"
    BOOKING_ACTION_ID = "ACT-S9-BOOK-001"

    manifest_data = {
        "run_id": RUN_ID, "stage": STAGE,
        "records": {
            "issued_campaign_id": CAMPAIGN_ID,
            "part_issue_completed_at": "2026-10-21T06:00:00+00:00",
        },
        "cause_value": "SUP-1/LOT-A",
        "expected_vins": [VIN],
        "account": "123456789012",
    }
    p = tmp_path / f"{RUN_ID}.json"
    p.write_text(_json_s9.dumps(manifest_data))

    with _mock_aws_s9():
        with FiLoopWorld(auto_pump=False) as w:
            ddb_avx = w.internal("dynamodb")

            # Seed recall Finding
            findings_table = _mod._FINDINGS_TABLE.format(stage=STAGE)
            ddb_avx.put_item(
                TableName=findings_table,
                Item={
                    "finding_id": {"S": FINDING_ID},
                    "finding_kind": {"S": _mod._RECALL_FINDING_KIND},
                    "subject_key": {"S": f"{CAMPAIGN_ID}/parts_expected/1"},
                    "fleet_id": {"S": FLEET_ID},
                    "scope": {"M": {"vin": {"S": VIN}}},
                    "evidence": {"L": []},
                    "disclosure_txt": {"S": "S\n\nC\n\nR"},
                },
            )

            # Seed a booking Action on the recall Finding
            actions_table = _mod._ACTIONS_TABLE.format(stage=STAGE)
            ddb_avx.put_item(
                TableName=actions_table,
                Item={
                    "action_id": {"S": BOOKING_ACTION_ID},
                    "finding_id": {"S": FINDING_ID},
                    "action_kind": {"S": _mod._BOOK_FLEET_SERVICE_KIND},
                    "status": {"S": "executed"},
                },
            )

            # Seed run record so after-run-run-record passes
            run_table = _mod._AGENT_RUNS_TABLE.format(stage=STAGE)
            try:
                ddb_avx.create_table(
                    TableName=run_table,
                    KeySchema=[
                        {"AttributeName": "agent_component", "KeyType": "HASH"},
                        {"AttributeName": "started_at", "KeyType": "RANGE"},
                    ],
                    AttributeDefinitions=[
                        {"AttributeName": "agent_component", "AttributeType": "S"},
                        {"AttributeName": "started_at", "AttributeType": "S"},
                    ],
                    BillingMode="PAY_PER_REQUEST",
                )
            except Exception:  # noqa: BLE001
                pass
            ddb_avx.put_item(
                TableName=run_table,
                Item={
                    "agent_component": {"S": _mod._RECALL_AGENT_COMPONENT},
                    "started_at": {"S": "2026-10-21T07:00:00+00:00"},
                    "status": {"S": "completed"},
                    "artifacts_written": {"N": "1"},
                },
            )

            import datetime as _dt_s9  # noqa: PLC0415
            res_holder: list[Results] = []
            real_rc = _mod.Results

            class _Cap(real_rc):  # type: ignore[misc,valid-type]
                def __init__(self) -> None:
                    super().__init__()
                    res_holder.append(self)

            def _world_client(svc: str, region: str, **_kw: Any) -> Any:
                return w.internal(svc, region=region)

            with (
                patch.object(_mod, "_manifest_path", lambda rid: str(p)),
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_utc_now",
                             lambda: _dt_s9.datetime(2026, 10, 21, 8, 0,
                                                     tzinfo=_dt_s9.timezone.utc)),
                patch.object(_mod, "_athena_query_paged", lambda *a, **kw: []),
                patch.object(_mod, "Results", _Cap),
            ):
                _mod._SESSION = w.make_guarded_session("after-run")
                main(["--stage", STAGE, "--run-id", RUN_ID, "--part", "after-run"])

    assert res_holder, "Results not instantiated"
    labels = {r[0]: r[1] for r in res_holder[-1].rows}
    assert labels.get("after-run-recall-no-booking-actions") == "FAIL", (
        f"S9: after-run must FAIL when recall Finding has a booking Action; "
        f"rows={res_holder[-1].rows}"
    )


def test_s9_issue_refuses_when_corpus_component_name_missing(
    tmp_path: Any,
) -> None:
    """S9 fix: issue refuses when corpus component_name is missing before the POST.

    The manifest may be stale; re-checking the corpus guards against proceeding
    to the investigation POST when the corpus no longer carries the name.
    """
    import json as _json_s9b  # noqa: PLC0415

    RUN_ID = "fi-loop-20261021T130000-s9-cn"
    FAILURE_MODE_ID = "fm-susp-bushing-002"

    manifest_data = {
        "run_id": RUN_ID, "stage": "staging",
        "part": "pre", "account": "123456789012",
        "pattern_id": "pat-s9-cn-001",
        "predicted_failure_mode_id": FAILURE_MODE_ID,  # F6b: use new key
        "safe_failure_modes": {FAILURE_MODE_ID: "opt-recall-001"},  # F6b: required
        "pre_verdict": "passed",
        "expected_vins": ["VIN00000000000001"],
        "records": {},
    }
    p = tmp_path / f"{RUN_ID}.json"
    p.write_text(_json_s9b.dumps(manifest_data))

    approve_calls: list[str] = []

    def _fake_http(url: str, method: str, path: str, token: str,
                   body: dict | None = None) -> tuple[int, dict]:
        if method == "POST":
            approve_calls.append(path)
        return 200, {}

    def _fake_client(svc: str, reg: str, **kw: Any) -> Any:
        m = MagicMock()
        if svc == "cognito-idp":
            m.list_user_pools.return_value = {
                "UserPools": [{"Id": "us-west-2_TEST", "Name": "cms-staging-ui-users"}]
            }
            m.list_user_pool_clients.return_value = {
                "UserPoolClients": [{"ClientId": "cid001"}]
            }
            m.describe_user_pool_client.return_value = {
                "UserPoolClient": {"ExplicitAuthFlows": ["ALLOW_USER_PASSWORD_AUTH"]}
            }
            m.admin_create_user.return_value = {
                "User": {"Username": "sub-uuid-001", "Attributes": []}
            }
        elif svc == "scheduler":
            m.list_schedules.return_value = {"Schedules": []}
        return m

    # Stub _read_ddb_item to return corpus item WITHOUT component_name
    def _corpus_no_name(ddb: Any, table: str, key: dict) -> dict | None:
        if "engineering-corpus" in table:
            return {
                "pk": f"fm#{FAILURE_MODE_ID}",
                "failure_mode_id": FAILURE_MODE_ID,
                # component_name intentionally absent
                "do_not_drive": False,
            }
        return None

    with (
        patch.object(_mod, "_manifest_path", lambda rid: str(p)),
        patch.object(_mod, "_client", _fake_client),
        patch.object(_mod, "_http", _fake_http),
        patch.object(_mod, "_read_ddb_item", _corpus_no_name),
        patch.object(_mod, "_utc_now",
                     lambda: __import__("datetime").datetime(
                         2026, 10, 21, 10, 0, tzinfo=__import__("datetime").timezone.utc)),
        patch.object(_mod, "_check_tier2_code",
                     lambda res, lam, fn: (_mod.check(res, "pre-tier2-code-readers", True, "ok"), True)[1]),
        patch.object(_mod, "_check_recall_table_exists",
                     lambda res, glue, stg: (_mod.check(res, "pre-recall-table", True, "ok"), True)[1]),
        patch.object(_mod, "_check_view_sql_unions_issued",
                     lambda res, glue, stg: (_mod.check(res, "pre-view-sql", True, "ok"), True)[1]),
        patch.object(_mod, "_check_esm_enabled",
                     lambda res, lam, stg, reg: (_mod.check(res, "pre-esm-enabled", True, "ok"), True)[1]),
        patch.object(_mod, "_check_dlq_empty",
                     lambda res, sqs, stg: (_mod.check(res, "pre-dlq-empty", True, "ok"), True)[1]),
        patch.object(_mod, "_check_no_open_livetest",
                     lambda res, idp, stg: (_mod.check(res, "pre-no-open-livetest", True, "ok"), True)[1]),
        patch.object(_mod, "_schedule_guard", lambda *a, **kw: None),
        patch.object(_mod, "_POLL_SLEEP_S", 0.0),
    ):
        res = Results()
        _mod._part_issue(res, stage="staging", run_id=RUN_ID, allow_writes=True)

    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("issue-corpus-component-name") == "FAIL", (
        f"S9: missing corpus component_name must FAIL issue-corpus-component-name; "
        f"rows={res.rows}"
    )
    assert not approve_calls, (
        f"S9: no POST calls when corpus component_name is missing; "
        f"approve_calls={approve_calls!r}"
    )


# ── F4a new tests: P6a, P6b, P7a, P7b shapes (C1 + W1 fix) ───────────────────

def _p6p7_scenario(
    tmp_path: Any,
    *,
    run_id: str,
    steps: list[tuple[bool, Any]],
    cohort_vins: list[str] | None = None,
    step5_timeout_on_run: int | None = None,
    confirmed_safety_recall: bool = False,
    account: str = "123456789012",
) -> dict:
    """Run --part ground N times with P6/P7 scenario knobs.

    steps: list of (view_repair, health_present) per run.
      view_repair=True → Athena stub returns a repair row.
      health_present=True → seed health-faults view with repair_ref.
      health_present=False → seed without repair_ref (fault not repaired).
      health_present=None → don't seed the health-faults view at all
                             (CMS returns health_cache_unavailable).
    cohort_vins: VINs to put in the CMS recall cohort.  If None, uses [VIN].
    step5_timeout_on_run: run number (1-based) on which step-5 POST times out
                          (returns status=0).
    confirmed_safety_recall: if True, add a CONFIRMED safety recall for the VIN.
    account: simulated AWS account id for CMS bucket construction.

    Returns a dict with:
      runs: list of {rc, step5, step9, step5_label, step9_label}
      rts: list of RTS POST log entries {run, step, status, reason}
      manifest_at_end: the manifest records dict after the last run
      open_grounding_at_end: bool
      pick_label_run1: label for ground-finding-pick on run 1
    """
    import datetime as _dt_p6  # noqa: PLC0415
    import json as _jj_p6  # noqa: PLC0415
    import urllib.error as _ue_p6  # noqa: PLC0415
    import urllib.request as _ur_p6  # noqa: PLC0415
    import uuid as _uuid_p6  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_loop_world import cms_fi as _cms_fi_p6  # noqa: PLC0415
    from scripts.tests.fi_loop_world import world as _wmod_p6  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415

    VIN = seed.vin(2)
    FLEET_ID = seed.VIN_FLEET[2]
    FINDING_ID = f"FIND-{_uuid_p6.uuid4()}"
    BOOKING_FINDING_ID = f"FIND-{_uuid_p6.uuid4()}"
    CODE = "P0420"
    STAGE = "staging"
    mf_path = str(tmp_path / f"{run_id}-manifest.json")
    view = {"repair": False}
    rts_log: list[dict] = []

    # Step-9 line sentinel (to distinguish step-5 and step-9 POSTs).
    _STEP9_ANCHOR = "# ── 9. return-to-service accepted"
    _step9_lineno = next(
        i for i, ln in enumerate(open(_mod.__file__).read().splitlines(), 1)
        if _STEP9_ANCHOR in ln)

    def _athena(athena: Any, stage_: str, sql: str, label: str) -> list[dict]:
        if view["repair"]:
            return [{"vin": VIN, "code": CODE, "fleet_id": FLEET_ID,
                     "repair_ref": "RO-P6-1", "repaired_on": "2026-10-22",
                     "status": "cleared"}]
        return []

    def _seed_recall(s3: Any, at: Any, cvins: list[str], with_safety: bool) -> None:
        import gzip as _gz_sr  # noqa: PLC0415
        _cms_fi_p6.seed_recall_cache_s3(
            s3, bucket=_wmod_p6.CMS_ATHENA_BUCKET,
            s3_prefix=_wmod_p6.CMS_ATHENA_PREFIX,
            fleet_id=FLEET_ID, vin_list=cvins,
            computed_at=at.isoformat(),
            campaign_id="MRD-2026-901" if with_safety else None)
        if with_safety:
            pref = f"{_wmod_p6.CMS_ATHENA_PREFIX}_cache/fi-recall-views-v1/"
            for o in s3.list_objects_v2(
                    Bucket=_wmod_p6.CMS_ATHENA_BUCKET, Prefix=pref
            ).get("Contents", []):
                if not o["Key"].endswith(".json.gz"):
                    continue
                b = _jj_p6.loads(_gz_sr.decompress(
                    s3.get_object(Bucket=_wmod_p6.CMS_ATHENA_BUCKET,
                                  Key=o["Key"])["Body"].read()))
                for r in b.get("vehicle_status", []):
                    r["match_basis"] = "CONFIRMED"
                for r in b.get("fleet_summary", []):
                    r.update(confirmed=1, population=1, remedied=0)
                s3.put_object(Bucket=_wmod_p6.CMS_ATHENA_BUCKET, Key=o["Key"],
                              Body=_gz_sr.compress(_jj_p6.dumps(b).encode()))

    cur_run = [0]
    out: dict = {"runs": [], "rts": rts_log}

    with _mock_aws():
        # F6c clock fix: pin world start to a fixed past date so w.clock.now()
        # (used as computed_at when seeding the recall cache) stays consistent
        # with _pinned (2026-10-22T12+Z).  Without this, w.clock.now() returns
        # today's real date; once the real date passes Oct 22 2026, the pinned
        # _utc_now (2026-10-22T12Z) is in the past relative to computed_at, and
        # _ground_pick_recall_check rejects the slice as "more than 5 min in future".
        with FiLoopWorld(
            auto_pump=False,
            start=_dt_p6.datetime(2026, 10, 22, 12, 0, 0,
                                   tzinfo=_dt_p6.timezone.utc),
        ) as w:
            real_http = _mod._http

            def _http_stub(api_url: str, method: str, route: str, token: str,
                           body: Any, **_k: Any) -> tuple[int, dict]:
                if method == "POST" and "return-to-service" in route:
                    import sys as _sys_s  # noqa: PLC0415
                    ln = _sys_s._getframe(1).f_lineno
                    step_n = 5 if ln < _step9_lineno else 9
                    if (step5_timeout_on_run is not None
                            and cur_run[0] == step5_timeout_on_run
                            and step_n == 5):
                        rts_log.append({"run": cur_run[0], "step": 5,
                                        "status": 0, "reason": "timeout"})
                        return 0, {"_error": "TimeoutError: timed out"}
                    try:
                        recs = _jj_p6.loads(
                            open(mf_path).read()).get("records", {})
                    except Exception:  # noqa: BLE001
                        recs = {}
                    url = w.cms_url.rstrip("/") + "/" + route.lstrip("/")
                    req = _ur_p6.Request(
                        url, data=_jj_p6.dumps(body).encode(), method="POST",
                        headers={"Authorization": f"Bearer {token}",
                                 "Content-Type": "application/json"})
                    try:
                        with _ur_p6.urlopen(req) as resp:
                            st, bd = resp.status, _jj_p6.loads(resp.read())
                    except _ue_p6.HTTPError as exc:
                        st, bd = exc.code, _jj_p6.loads(exc.read() or b"{}")
                    rts_log.append({"run": cur_run[0], "step": step_n,
                                    "status": st, "reason": bd.get("reason"),
                                    "neg_ctrl_rec": recs.get("neg_ctrl"),
                                    "neg_ctrl_refused_rec": recs.get("neg_ctrl_refused"),
                                    "returned_rec": recs.get("returned")})
                    return st, bd
                if method == "POST" and "approve" in route:
                    if "book_fleet_service" in str(body):
                        return (200, {"status": "executed",
                                      "action_kind": _mod._BOOK_FLEET_SERVICE_KIND,
                                      "action_id": "act-book-p6"})
                return real_http(api_url, method, route, token, body)

            ddb = w.internal("dynamodb")
            table = _mod._FINDINGS_TABLE.format(stage=STAGE)
            for fid, kind, skey in [
                (FINDING_ID, _mod._GROUND_VEHICLE_KIND, "ground/1"),
                (BOOKING_FINDING_ID, _mod._BOOK_FLEET_SERVICE_KIND, "service/1"),
            ]:
                ddb.put_item(TableName=table, Item={
                    "finding_id": {"S": fid},
                    "finding_kind": {"S": _mod._FLEET_HEALTH_FINDING_KIND},
                    "severity": {"S": "p0"}, "fleet_id": {"S": FLEET_ID},
                    "scope": {"M": {"vin": {"S": VIN}}},
                    "recommended_action": {"M": {
                        "action_kind": {"S": kind},
                        "target_system": {
                            "S": "cms" if kind == _mod._GROUND_VEHICLE_KIND else "dms"},
                        "parameters": {"M": {
                            "vehicle_vin": {"S": VIN},
                            "fault_codes": {"L": [{"S": CODE}]}}}}},
                    "subject_key": {"S": skey},
                    "headline": {"S": f"P6/P7 {run_id}"},
                    "evidence": {"M": {}}})

            # Pre-seed recall cache (before run 1 for all runs).
            cv = cohort_vins if cohort_vins is not None else [VIN]
            _seed_recall(w.internal("s3"), w.clock.now(), cv, confirmed_safety_recall)

            real_rc = _mod.Results
            pick_label_run1 = [None]
            for i, (view_repair, health_present) in enumerate(steps, start=1):
                cur_run[0] = i
                view["repair"] = view_repair
                _pinned = _dt_p6.datetime(2026, 10, 22, 11 + i, 0,
                                         tzinfo=_dt_p6.timezone.utc)
                if health_present is not None:
                    w.seed_health_faults_view(
                        vin=VIN, fault_code=CODE,
                        computed_at=w.clock.now().isoformat(),
                        repair_ref="RO-P6-1" if health_present else None,
                        repaired_on="2026-10-22" if health_present else None,
                        last_seen="2026-10-21" if health_present else None)
                holder: list = []

                class _Cap(real_rc):  # type: ignore[misc,valid-type]
                    def __init__(self) -> None:
                        super().__init__()
                        holder.append(self)

                # Write account into manifest so pick's W1 recall check has it.
                _jj_p6.loads(open(mf_path).read()) if Path(mf_path).exists() else None

                def _ensure_account_in_manifest() -> None:
                    try:
                        m = _jj_p6.loads(open(mf_path).read())
                    except (FileNotFoundError, Exception):  # noqa: BLE001
                        m = {}
                    if "account" not in m:
                        m["account"] = account
                        m.setdefault("stage", STAGE)
                        m.setdefault("run_id", run_id)
                        open(mf_path, "w").write(_jj_p6.dumps(m))
                _ensure_account_in_manifest()

                _mod._SESSION = None
                _mod._SESSION = w.make_guarded_session("ground")
                with (
                    patch.object(_mod, "_utc_now", lambda _i=i: _pinned),
                    patch.object(_mod, "_athena_query_paged", _athena),
                    patch.object(_mod, "_get_avx_api_url", lambda cfn, s: w.avx_url),
                    patch.object(_mod, "_get_cms_api_url", lambda cfn, s: w.cms_url),
                    patch.object(_mod, "_http", _http_stub),
                    patch.object(_mod, "_count_open_fi_bookings",
                                 lambda *a, **k: (1, 1)),
                    patch.object(_mod, "_manifest_path", lambda rid: mf_path),
                    patch.object(_mod, "Results", _Cap),
                ):
                    rc = main(["--stage", STAGE, "--run-id", run_id,
                               "--part", "ground",
                               "--allow-writes", "--allow-managed-writes"])
                labels = {r[0]: r[1] for r in holder[-1].rows} if holder else {}
                if i == 1:
                    pick_label_run1[0] = labels.get("ground-finding-pick")
                out["runs"].append({"rc": rc, "labels": labels,
                                    "step5": labels.get("ground-rts-before-repair"),
                                    "step9": labels.get("ground-rts-after-repair")})
            vid = _mod._resolve_registry_vehicle_id(ddb, STAGE, VIN)
            out["open_grounding_at_end"] = _mod._has_open_grounding(ddb, STAGE, vid)
            try:
                out["manifest_at_end"] = _jj_p6.loads(
                    open(mf_path).read()).get("records", {})
            except Exception:  # noqa: BLE001
                out["manifest_at_end"] = {}
            out["pick_label_run1"] = pick_label_run1[0]
    return out


def test_c7_p6a_health_cache_unavailable_neg_ctrl_not_resent(tmp_path: Any) -> None:
    """C1/P6a: health_cache_unavailable on run 1 → neg_ctrl recorded; step 5 not re-sent.

    P6a scenario (from probe): CMS's health view is absent on run 1 (step 5 gets
    409 health_cache_unavailable).  On run 2 the repair lands.

    With the C1 fix:
    - run 1: neg_ctrl: "sent" recorded before POST; after POST neg_ctrl updated to
             "409:health_cache_unavailable"; step 5 FAIL.  Steps 6-9 run.  Car grounded.
    - run 2: neg_ctrl is in manifest → skip the POST; step 5 FAIL (resume).
             Step 9 POSTs and gets 200 → returned.

    Asserts:
    - Exactly one step-5 POST across all runs (only run 1 sends it).
    - Step 5 is FAIL on every run (first run: bad response; later runs: recorded FAIL).
    - Car is returned (step 9 PASS on run 2).

    Catches g9a: removes `or returned == "true"` from skip → on run 2 step 5 re-sends
    and returns the car prematurely.
    Catches c4-p6d: drops signal hold → the `sent` record is not inside the hold.
    """
    out = _p6p7_scenario(
        tmp_path,
        run_id="fi-loop-20261022T130000-f4a6a001",
        steps=[
            (False, None),    # run 1: health view absent → health_cache_unavailable
            (True, True),     # run 2: repair view + repair health
            (True, True),     # run 3: all resume
        ],
    )
    step5_posts = [e for e in out["rts"] if e["step"] == 5]
    assert len(step5_posts) == 1, (
        f"P6a C1: exactly one step-5 POST across all runs; "
        f"got {len(step5_posts)}: {step5_posts!r}"
    )
    assert step5_posts[0]["run"] == 1, (
        f"P6a C1: the single step-5 POST must be on run 1; "
        f"got run={step5_posts[0]['run']!r}"
    )
    # Step 5 FAIL on all runs (health_cache_unavailable recorded on run 1).
    for i, r in enumerate(out["runs"], start=1):
        assert r["step5"] == "FAIL", (
            f"P6a C1: step 5 must FAIL on all runs (run {i}); "
            f"labels={r['labels']}"
        )
    # Car returned on run 2 or 3.
    returned_runs = [i for i, r in enumerate(out["runs"], start=1)
                     if r["step9"] == "PASS"]
    assert returned_runs, (
        f"P6a C1: car must be returned (step 9 PASS) on at least one run; "
        f"runs={[r['step9'] for r in out['runs']]!r}"
    )
    assert not out["open_grounding_at_end"], (
        f"P6a C1: car must not still be grounded at end; rts={out['rts']!r}"
    )


def test_c7_p6b_timeout_neg_ctrl_not_resent(tmp_path: Any) -> None:
    """C1/P6b: step-5 POST times out on run 1 → neg_ctrl recorded; not re-sent.

    P6b scenario: the step-5 POST times out (returns status=0) on run 1.
    On run 2 the repair lands.

    With the C1 fix:
    - run 1: neg_ctrl: "sent" before POST; after timeout neg_ctrl updated to "0:";
             step 5 FAIL.  Steps 6-9 run.
    - run 2: neg_ctrl in manifest → skip; step 5 FAIL (resume).
             Step 9 POSTs and gets 200.

    Exactly one step-5 POST (timed out on run 1; not sent on run 2+).

    Catches c4-p6d: drops signal hold around the step-5 POST and its record; a
    signal between the sent record and the POST loses the record.  The test
    proves the hold covers the `sent` record: even when the POST returns 0,
    `neg_ctrl` must be in the manifest immediately after the hold exits.
    """
    out = _p6p7_scenario(
        tmp_path,
        run_id="fi-loop-20261022T130000-f4a6b001",
        steps=[
            (False, False),   # run 1: health present but no repair (gives no repair ref)
            (True, True),     # run 2: repair view + health
            (True, True),     # run 3: all resume
        ],
        step5_timeout_on_run=1,
    )
    step5_posts = [e for e in out["rts"] if e["step"] == 5]
    assert len(step5_posts) == 1, (
        f"P6b C1: exactly one step-5 POST across all runs (timed out on run 1); "
        f"got {len(step5_posts)}: {step5_posts!r}"
    )
    assert step5_posts[0]["status"] == 0, (
        f"P6b C1: the step-5 POST must have status 0 (timeout); "
        f"got {step5_posts[0]!r}"
    )
    # Step 5 FAIL on all runs.
    for i, r in enumerate(out["runs"], start=1):
        assert r["step5"] == "FAIL", (
            f"P6b C1: step 5 must FAIL on all runs (run {i}); "
            f"labels={r['labels']}"
        )
    # Car returned.
    assert not out["open_grounding_at_end"], (
        f"P6b C1: car must not still be grounded at end; rts={out['rts']!r}"
    )
    # neg_ctrl is recorded in manifest after run 1.
    assert out["manifest_at_end"].get("neg_ctrl"), (
        f"P6b C1: neg_ctrl must be recorded in manifest; "
        f"manifest_at_end={out['manifest_at_end']!r}"
    )


def test_c7_p7a_vin_outside_recall_cohort_pick_skipped(tmp_path: Any) -> None:
    """W1/P7a: VIN outside CMS recall cohort → pick skips it; no step-5 POST.

    P7a scenario: the VIN is not in the CMS recall cohort (cohort_vins seeds
    a different VIN).  CMS's return_to_service route uses recall_source.blocking_recalls
    which returns None for VINs outside the cohort (fail-closed: unavailable).

    With the W1 fix:
    - The pick reads the recall slice for the candidate VIN; if blocking_recalls
      returns None (VIN not in cohort), the pick skips the VIN.
    - ground-finding-pick FAILs (no eligible VIN found).
    - No step-5 POST is ever sent.

    Catches c4-p7c: ok = True on refused pending retry → returned recorded as "true"
    even when CMS refused. Under c4-p7c, a VIN that was already grounded (step 4)
    would get through the step-9 pending retry and record returned="true" despite
    the grounding still being open.  The pick-skip prevents grounding, so there is
    no step-9 POST at all, and the test confirms no RTS calls.
    """
    out = _p6p7_scenario(
        tmp_path,
        run_id="fi-loop-20261022T130000-f4a7a001",
        steps=[(False, False)],
        cohort_vins=[],   # VIN not in cohort → pick skips it
    )
    step5_posts = [e for e in out["rts"] if e["step"] == 5]
    assert len(step5_posts) == 0, (
        f"P7a W1: no step-5 POST when VIN outside recall cohort; "
        f"got {step5_posts!r}"
    )
    assert out["pick_label_run1"] == "FAIL", (
        f"P7a W1: ground-finding-pick must FAIL when VIN outside cohort; "
        f"pick_label_run1={out['pick_label_run1']!r}"
    )
    assert out["open_grounding_at_end"] is False, (
        f"P7a W1: car must not be grounded (pick prevented it); "
        f"rts={out['rts']!r}"
    )


def test_c7_p7b_blocking_recall_pick_skipped(tmp_path: Any) -> None:
    """W1/P7b: VIN has CONFIRMED safety recall → pick skips it; no step-5 POST.

    P7b scenario: the VIN has an open CONFIRMED safety recall (recall_class=safety,
    match_basis=CONFIRMED).  CMS's blocking_recalls returns [campaign_id].

    With the W1 fix:
    - The pick reads the recall slice; blocking_recalls returns a non-empty list.
    - The pick skips the VIN.
    - ground-finding-pick FAILs.
    - No step-5 POST.

    Catches c4-p7c via the same mechanism as P7a: no step-9 POST to make ok=True on.
    The assertion on pick_label_run1 catches any regression that removes the
    blocking-recall check from the pick ('pick skips the recall-slice check' mutant).
    """
    out = _p6p7_scenario(
        tmp_path,
        run_id="fi-loop-20261022T130000-f4a7b001",
        steps=[(False, False)],
        confirmed_safety_recall=True,
    )
    step5_posts = [e for e in out["rts"] if e["step"] == 5]
    assert len(step5_posts) == 0, (
        f"P7b W1: no step-5 POST when VIN has blocking recall; "
        f"got {step5_posts!r}"
    )
    assert out["pick_label_run1"] == "FAIL", (
        f"P7b W1: ground-finding-pick must FAIL when VIN has blocking recall; "
        f"pick_label_run1={out['pick_label_run1']!r}"
    )
    assert out["open_grounding_at_end"] is False, (
        f"P7b W1: car must not be grounded (pick prevented it); "
        f"rts={out['rts']!r}"
    )


def test_c7_step5_neg_ctrl_sent_recorded_inside_signal_hold(tmp_path: Any) -> None:
    """C1/c4-p6d: _defer_signals_for_restore wraps the step-5 POST and neg_ctrl:'sent'.

    Catches c4-p6d: replacing _defer_signals_for_restore with contextlib.nullcontext
    for the step-5 block.

    The signal-hold property (deferred SIGTERM) is an OS-level guarantee that
    cannot be tested with standard pytest (no real SIGTERM in tests).  This test
    instead checks the structural property via code inspection: the step-5 POST
    and the _record_sub_step("neg_ctrl", "sent") call both appear INSIDE a
    `with _defer_signals_for_restore():` block.

    Specifically: scanning the script source, within the step-5 section there must
    be a `_defer_signals_for_restore` context manager that contains both the
    `_record_sub_step("neg_ctrl", "sent")` record and the step-5 POST call.

    Under c4-p6d (nullcontext replaces the hold), this check fails: the step-5
    block no longer contains a call to `_defer_signals_for_restore`.
    """
    script_src = open(_mod.__file__).read()
    script_lines = script_src.splitlines()

    # Find the step-5 section (between step 5 and step 6 markers).
    step5_start = next(i for i, ln in enumerate(script_lines)
                       if "── 5. negative control" in ln)
    step6_start = next(i for i, ln in enumerate(script_lines)
                       if "── 6. approve book_fleet_service" in ln)
    step5_section = "\n".join(script_lines[step5_start:step6_start])

    # The step-5 section must contain '_defer_signals_for_restore'.
    assert "_defer_signals_for_restore" in step5_section, (
        "c4-p6d: _defer_signals_for_restore must appear in the step-5 section "
        "(between '── 5. negative control' and '── 6. approve book_fleet_service'); "
        "the hold appears to have been replaced (c4-p6d mutant removes it)"
    )

    # The step-5 section must contain 'neg_ctrl', 'sent' and the POST.
    assert '_record_sub_step("neg_ctrl", "sent")' in step5_section, (
        "c4-p6d: _record_sub_step('neg_ctrl', 'sent') must appear in the step-5 section"
    )
    assert '_CMS_RTS_PATH' in step5_section, (
        "c4-p6d: the step-5 RTS POST (_CMS_RTS_PATH) must appear in the section"
    )


def test_c7_p7c_refused_pending_retry_not_recorded_as_returned(tmp_path: Any) -> None:
    """W1/c4-p7c: a refused pending retry (non-fault_not_repaired) is FAIL, not PASS.

    Catches c4-p7c: setting ok = True on the pending retry causes the car to be
    recorded as returned even when CMS refused.

    The scenario:
    - Manifest has returned='pending' (step 9 started but didn't finish).
    - The grounding row is present (car still grounded).
    - Step-9 retry POST gets 409 open_safety_recall (non-fault_not_repaired).

    Under the correct code:
    - ok = False, returned stays 'pending', return_blocked='open_safety_recall'.
    - ground-rts-after-repair is FAIL.

    Under c4-p7c (ok = True):
    - ok = True, returned recorded as 'true', step 9 PASS.
    - return_blocked NOT recorded.
    - Car still grounded (the POST was refused), but test reports PASS.
    """
    import json as _jj  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415
    from scripts.tests.fi_rw_world import seed  # noqa: PLC0415
    import uuid as _uuid  # noqa: PLC0415

    VIN = seed.vin(1)
    FLEET_ID = seed.VIN_FLEET[1]
    FINDING_ID = f"FIND-{_uuid.uuid4()}"
    BOOKING_FINDING_ID = f"FIND-{_uuid.uuid4()}"
    RUN_ID = "fi-loop-20261022T110000-f4c7c001"
    STAGE = "staging"
    FAULT_CODE = "P0420"
    USERNAME = f"livetest-fi-loop-{RUN_ID}-fo@example.invalid"

    # Pre-write manifest with returned:'pending' (step 9 was in-flight).
    mf_path = str(tmp_path / f"{RUN_ID}-manifest.json")
    Path(mf_path).write_text(_jj.dumps({
        "run_id": RUN_ID, "stage": STAGE,
        "records": {
            "user": USERNAME,
            "ground_vin": VIN, "ground_fleet_id": FLEET_ID,
            "ground_finding_id": FINDING_ID, "ground_fault_codes": FAULT_CODE,
            "ground_action_id": "act-g-c7c", "grounded": "true",
            "neg_ctrl_refused": "true",
            "book_action_id": "act-book-c7c", "booked": "true",
            "booking_finding_id": BOOKING_FINDING_ID,
            "repaired": "true",
            "returned": "pending",  # step 9 started but not finished
        },
    }))

    with _mock_aws():
        with FiLoopWorld(auto_pump=False) as w:
            ddb = w.internal("dynamodb")
            # Seed findings so the world validates
            findings_table = _mod._FINDINGS_TABLE.format(stage=STAGE)
            for fid, kind, skey in [
                (FINDING_ID, _mod._GROUND_VEHICLE_KIND, "ground/1"),
                (BOOKING_FINDING_ID, _mod._BOOK_FLEET_SERVICE_KIND, "service/1"),
            ]:
                ddb.put_item(TableName=findings_table, Item={
                    "finding_id": {"S": fid},
                    "finding_kind": {"S": _mod._FLEET_HEALTH_FINDING_KIND},
                    "severity": {"S": "p0"}, "fleet_id": {"S": FLEET_ID},
                    "scope": {"M": {"vin": {"S": VIN}}},
                    "recommended_action": {"M": {
                        "action_kind": {"S": kind},
                        "target_system": {
                            "S": "cms" if kind == _mod._GROUND_VEHICLE_KIND else "dms"},
                        "parameters": {"M": {
                            "vehicle_vin": {"S": VIN},
                            "fault_codes": {"L": [{"S": FAULT_CODE}]}}}}},
                    "subject_key": {"S": skey},
                    "headline": {"S": "c4-p7c test"}, "evidence": {"M": {}}})
            w.seed_recall_cache(fleet_id=FLEET_ID, vin_list=[VIN])
            w.seed_health_faults_view(
                vin=VIN, fault_code=FAULT_CODE,
                computed_at=w.clock.now().isoformat(),
                repair_ref="RO-C7C-1", repaired_on="2026-10-22",
                last_seen="2026-10-21")

            # Create the CMS groundings table and write an open grounding row
            # so _has_open_grounding returns True during the pending-resume retry.
            from scripts.tests.fi_loop_world.cms_fi import GROUNDINGS_TABLE  # noqa: PLC0415
            ddb_cms = w.internal("dynamodb")
            # The world already creates this table; write an open grounding row.
            ddb_cms.put_item(
                TableName=GROUNDINGS_TABLE,
                Item={
                    "vehicleId": {"S": VIN},  # vehicleId PK = vin in the world
                    "actionId": {"S": "act-g-c7c"},  # actionId SK
                    "groundedAt": {"S": "2026-10-22T11:00:00Z"},
                    "vin": {"S": VIN},
                    # no returnedAt → open grounding
                },
            )

            # Step-9 retry POST refuses with open_safety_recall.
            def _http_stub(api_url: str, method: str, route: str,
                           token: str, body: Any, **_kw: Any) -> tuple[int, dict]:
                if method == "POST" and "return-to-service" in route:
                    # Refuse with open_safety_recall (not fault_not_repaired).
                    return 409, {"reason": "open_safety_recall"}
                if method == "POST" and "approve" in route:
                    if "book_fleet_service" in str(body):
                        return 200, {"status": "executed",
                                     "action_kind": _mod._BOOK_FLEET_SERVICE_KIND,
                                     "action_id": "act-book-fake"}
                return 200, {}

            _mod._SESSION = None
            _mod._SESSION = w.make_guarded_session("ground")

            res_holder: list[Results] = []
            real_rc = _mod.Results

            class _Cap(real_rc):  # type: ignore[misc,valid-type]
                def __init__(self) -> None:
                    super().__init__()
                    res_holder.append(self)

            def _world_client(service: str, region: str, **_kw: Any) -> Any:
                if service == "cognito-idp":
                    return w.idp_client()
                return w.internal(service, region=region)

            with (
                patch.object(_mod, "_client", _world_client),
                patch.object(_mod, "_utc_now",
                             lambda: __import__("datetime").datetime(
                                 2026, 10, 22, 11, 0,
                                 tzinfo=__import__("datetime").timezone.utc)),
                patch.object(_mod, "_athena_query_paged",
                             lambda *a, **k: [{"vin": VIN, "code": FAULT_CODE,
                                              "fleet_id": FLEET_ID,
                                              "repair_ref": "RO-C7C-1",
                                              "repaired_on": "2026-10-22",
                                              "status": "cleared"}]),
                patch.object(_mod, "_get_avx_api_url", lambda cfn, s: w.avx_url),
                patch.object(_mod, "_get_cms_api_url", lambda cfn, s: w.cms_url),
                patch.object(_mod, "_http", _http_stub),
                patch.object(_mod, "_count_open_fi_bookings", lambda *a, **k: (1, 1)),
                # Our RO, outside the early-close set (sha256 % 100 = 96): the stand-in
                # step now fails closed without it (2026-10-26 fix).
                patch.object(_mod, "_find_ro_id_for_action", lambda *a, **k: _LIVE_RO_ID),
                patch.object(_mod, "_manifest_path", lambda rid: mf_path),
                patch.object(_mod, "Results", _Cap),
            ):
                main(["--stage", STAGE, "--run-id", RUN_ID,
                      "--part", "ground",
                      "--allow-writes", "--allow-managed-writes"])

    assert res_holder, "Results not instantiated"
    labels = {r[0]: r[1] for r in res_holder[-1].rows}

    assert labels.get("ground-rts-after-repair") == "FAIL", (
        "c4-p7c: step 9 must FAIL when CMS refuses with open_safety_recall (resumed "
        "from pending); under c4-p7c (ok=True), step 9 would PASS incorrectly; "
        f"labels={labels}"
    )

    records = _jj.loads(Path(mf_path).read_text()).get("records", {})
    assert records.get("return_blocked") == "open_safety_recall", (
        "c4-p7c: return_blocked must be recorded when step 9 is refused with "
        "open_safety_recall; under c4-p7c this would be absent (ok=True so no FAIL); "
        f"records={records!r}"
    )
    assert records.get("returned") != "true", (
        "c4-p7c: returned must NOT be 'true' when CMS refused step 9; "
        "under c4-p7c (ok=True) it would be recorded as 'true'; "
        f"records={records!r}"
    )


# ── W8 F4b / S9 F4b ──────────────────────────────────────────────────────────


def test_w8_f4b_decision_only_manifest_wrong_action_id_fails_cleanup(
    tmp_path: Any,
) -> None:
    """W8 F4b (red): decision-only manifest must FAIL when v1 has another action_id.

    When issue stops after the decision approve but before the issue approve, the
    manifest has decision_action_id and thread_versions=[1] but no issue_action_id.
    Cleanup builds the thread condition as "action_id = :dec_aid".
    c4-p1b widens that to "action_id = :dec_aid OR attribute_exists(thread_id)",
    which deletes v1 whatever its action_id.  This test catches c4-p1b.
    """
    import json as _json  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415

    STAGE = "staging"
    ACCOUNT = "123456789012"
    THREAD_ID = "thread-f4b000000000001c"
    RUN_ID = "fi-loop-20261022T120000-c4b8f401"
    DEC_ACTION_ID = "act-dec-w8f4b-001"
    OTHER_ACTION_ID = "act-other-run-w8"
    LAKE_BUCKET = f"adp-{STAGE}-foundation-lake-{ACCOUNT}-us-east-1"

    manifest_data = {
        "run_id": RUN_ID, "stage": STAGE,
        "pattern_id": "pat-w8f4b",
        "records": {
            "users": [],
            "thread_id": THREAD_ID,
            "thread_versions": [1],
            "decision_action_id": DEC_ACTION_ID,
            # No issue_action_id — decision-only (partial issue) state.
            "vin_s3_keys": [f"digital-thread/{STAGE}/{THREAD_ID}/v1/affected-vins.json"],
        },
        "account": ACCOUNT,
        "residue": {},
        "expected_vins": [],
    }

    with _mock_aws():
        with FiLoopWorld(auto_pump=True) as w:
            ddb_adp = w.internal("dynamodb", region="us-east-1")
            dt_table = _mod._DIGITAL_THREAD_TABLE.format(stage=STAGE)
            # v1 belongs to another run.
            ddb_adp.put_item(
                TableName=dt_table,
                Item={
                    "thread_id": {"S": THREAD_ID},
                    "version": {"N": "1"},
                    "status": {"S": "decided"},
                    "action_id": {"S": OTHER_ACTION_ID},  # NOT our dec_action_id
                },
            )
            s3 = w.internal("s3", region="us-east-1")
            try:
                s3.create_bucket(Bucket=LAKE_BUCKET)
            except Exception:  # noqa: BLE001
                pass
            s3.put_object(
                Bucket=LAKE_BUCKET,
                Key=f"curated/engineering/digital_thread/{THREAD_ID}.v1.json",
                Body=b"{}",
            )

            p = tmp_path / f"{RUN_ID}.json"
            p.write_text(_json.dumps(manifest_data))

            res = Results()
            with (
                patch.object(_mod, "_manifest_path", lambda rid: str(p)),
                patch.object(_mod, "_resolve_pool_id", lambda idp: "pool"),
                patch.object(_mod, "_check_residue", lambda *a, **kw: None),
                patch.object(_mod, "_run_reconcile_check", lambda *a, **kw: None),
            ):
                _mod._SESSION = w.make_guarded_session("cleanup")
                _mod._part_cleanup(res, stage=STAGE, run_id=RUN_ID, allow_writes=True)

            # v1's lake object must survive (row refused, lake not deleted).
            lake_keys = [
                o["Key"]
                for o in s3.list_objects_v2(
                    Bucket=LAKE_BUCKET,
                    Prefix=f"curated/engineering/digital_thread/{THREAD_ID}.v",
                ).get("Contents", [])
            ]

    labels = {r[0]: r[1] for r in res.rows}
    assert labels.get("cleanup-thread-rows-deleted") == "FAIL", (
        "W8 F4b: decision-only manifest, v1 with another action_id must FAIL. "
        "c4-p1b widens the condition to always-true, so it would PASS and delete v1. "
        f"labels={labels}"
    )
    assert any(".v1." in k for k in lake_keys), (
        "W8 F4b: v1's lake object must survive when the row delete was refused. "
        f"lake_keys={lake_keys!r}"
    )


def test_s9_f4b_no_action_id_manifest_fails_cleanup(tmp_path: Any) -> None:
    """S9 F4b (red): manifest with thread_id + thread_versions but no action ids must FAIL.

    c4-p1c changes the FAIL check to PASS, so the stamp can be written with rows still
    there.  This test asserts that the "no action_id values" branch FAILs.
    """
    import json as _json  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415

    STAGE = "staging"
    ACCOUNT = "123456789012"
