def test_a5_bad_json_names_step() -> None:
    """S7: valid base64 that isn't JSON → ValueError naming the JSON step."""
    import base64 as _b64  # noqa: PLC0415
    view_text = "/* Presto View: " + _b64.b64encode(b"not json at all").decode() + " */"
    with pytest.raises(ValueError, match="not valid JSON"):
        _mod._decode_presto_view_text(view_text)


@_SKIP_WORLD_E2E
@pytest.mark.parametrize("mode", ["issue-records", "cleanup-recovers", "stop-before-step14"])
def test_f6e_s1_refusal_then_cleanup_removes_everything(tmp_path: Path, mode: str) -> None:
    """A stop after the real decision approve (the S1 draft refusal) leaves a manifest
    cleanup can finish: draft row, thread rows, thread-lake and VIN-list objects,
    Actions, Findings, investigation row and temp user all gone, cleanup rc 0.

    ``issue-records``: issue recorded ``vin_s3_keys`` right after the decision.
    ``cleanup-recovers``: the key is stripped from the manifest (as if issue died
    first); cleanup reads it off the thread rows before deleting them.
    ``stop-before-step14`` (F6f, review cycle 3 W1): issue stops after the decision
    approve because the quality.issue Finding scan finds nothing, so the manifest has
    neither the draft id nor the issue Finding id; cleanup recovers both from this
    run's thread (no S1 flip in this mode).
    Adapted from review cycle 2's probe (`...-f6-rev2-c2-probe-s1.py`).
    """
    import json as _js  # noqa: PLC0415
    import boto3 as _b3  # noqa: PLC0415
    from scripts.tests.fi_loop_world import FiLoopWorld  # noqa: PLC0415

    mf_file = tmp_path / "shared-manifest.json"

    def _manifest_path_hook(rid: str) -> str:  # noqa: ARG001
        return str(mf_file)

    PATTERN_ID = "pat-supp-bushing-001"
    VIN_LIST = ["1MRDNA0A4MA000001", "1MRDNA0A5MA000002"]
    FM_ID = "fm-susp-bushing-001"
    COHORT_VALUE = "SUP-AXLE/LOT-2024-Q3"
    flipped: list[str] = []

    with FiLoopWorld(
        auto_pump=True,
        start=_dt.datetime(2026, 10, 22, 12, 0, 0, tzinfo=_dt.timezone.utc),
    ) as w:
        w.seed_pattern(pattern_id=PATTERN_ID, vin_list=VIN_LIST, failure_mode_id=FM_ID,
                       cohort_dimension="supplier_lot", cohort_value=COHORT_VALUE,
                       component_name="Front Axle Bushing")
        w.athena.con.execute(
            "DELETE FROM adp_staging_engineering.engineering_remedy_options "
            "WHERE remedy_option_id = 'opt-monitor-001'")
        pool_id = w.pool.pool_id
        client_id = w.pool.client_id
        good_zip = _make_zip_with_9_3_code()
        avx_url = w.avx_url

        def _ok(label: str) -> Any:
            def _f(res: Any, *a: Any, **kw: Any) -> bool:
                check(res, label, True, f"{label} (stub)")
                return True
            return _f

        def _vins_stub(res: Any, athena: Any, stage: str, cause_value: str, **_kw: Any) -> list[str]:
            check(res, "pre-expected-vins", True, "stub")
            return list(VIN_LIST)

        def _s3_issued_stub(res: Any, s3: Any, stage: str, account: str, campaign_id: str) -> bool:
            check(res, "issue-s3-key", True, "stub")
            return True

        holder: list = []
        real_results = _mod.Results

        class _Cap(real_results):  # type: ignore[misc,valid-type]
            def __init__(self) -> None:
                super().__init__()
                holder.append(self)

        real_cqif = _mod._check_quality_issue_finding

        def _cqif_then_flip(*a: Any, **kw: Any) -> Any:
            # Make the draft row unsafe after the real writer wrote it, so S1 refuses.
            out = real_cqif(*a, **kw)
            _did = out[2]
            if _did:
                _b3.resource("dynamodb", region_name="us-east-1").Table(
                    "adp-staging-recall-campaigns-issued").update_item(
                    Key={"campaign_id": _did},
                    UpdateExpression="SET do_not_drive = :t, recall_class = :rc",
                    ExpressionAttributeValues={":t": True, ":rc": "safety"})
                flipped.append(_did)
            return out

        def _no_issue_finding(*a: Any, **kw: Any) -> None:
            return None

        common = [
            patch.object(_mod, "_download_code_zip", lambda url: good_zip),
            patch.object(_mod, "_utc_now", _safe_issue_time),
            patch.object(_mod, "_check_esm_enabled", _ok("pre-esm-enabled")),
            patch.object(_mod, "_check_tier2_code", _ok("pre-tier2-code-readers")),
            patch.object(_mod, "_check_recall_table_exists", _ok("pre-recall-table")),
            patch.object(_mod, "_check_view_sql_unions_issued", _ok("pre-view-sql")),
            patch.object(_mod, "_check_dlq_empty", _ok("pre-dlq-empty")),
            patch.object(_mod, "_check_no_open_livetest", _ok("pre-no-open-livetest")),
            patch.object(_mod, "_compute_expected_vins", _vins_stub),
            patch.object(_mod, "_schedule_guard", lambda *a, **kw: None),
            patch.object(_mod, "_manifest_path", _manifest_path_hook),
            patch.object(_mod, "Results", _Cap),
        ]
        with contextlib.ExitStack() as st:
            for p in common:
                st.enter_context(p)
            _mod._SESSION = w.make_guarded_session("pre")
            main(["--stage", "staging", "--part", "pre"])
        pre_fails = [(r[0], r[2]) for r in holder[-1].rows if r[1] == "FAIL"]
        assert not pre_fails, pre_fails
        run_id = _js.loads(mf_file.read_text())["run_id"]

        with contextlib.ExitStack() as st:
            for p in common + [
                patch.object(_mod, "_get_avx_api_url", lambda cfn, stage: avx_url),
                patch.object(_mod, "_resolve_pool_id", lambda idp: pool_id),
                patch.object(_mod, "_password_client", lambda idp, pid: client_id),
                patch.object(_mod, "_check_s3_issued_recall", _s3_issued_stub),
                patch.object(_mod, "_POLL_SLEEP_S", 0.0),
            ] + ([patch.object(_mod, "_find_quality_issue_finding", _no_issue_finding)]
                 if mode == "stop-before-step14" else
                 [patch.object(_mod, "_check_quality_issue_finding", _cqif_then_flip)]):
                st.enter_context(p)
            _mod._SESSION = None
            _mod._SESSION = w.make_guarded_session("issue")
            main(["--stage", "staging", "--part", "issue", "--allow-writes", "--run-id", run_id])
        iss_labels = {r[0]: r[1] for r in holder[-1].rows}
        assert iss_labels.get("issue-decision-approve") == "PASS", holder[-1].rows
        assert "issue-issue-recall-approve" not in iss_labels, holder[-1].rows

        mf = _js.loads(mf_file.read_text())
        records = mf["records"]
        assert records.get("vin_s3_keys"), (
            f"issue must record vin_s3_keys right after the decision; records={sorted(records)}")
        thread_id = records["thread_id"]
        if mode == "stop-before-step14":
            assert not flipped
            assert not records.get("campaign_id") and not records.get("issue_finding_id"), records
            # This run's draft and issue Finding exist although the manifest doesn't name them.
            _drafts = [i for i in _b3.client("dynamodb", region_name="us-east-1").scan(
                TableName="adp-staging-recall-campaigns-issued").get("Items", [])
                if i.get("thread_id", {}).get("S") == thread_id]
            assert len(_drafts) == 1, _drafts
            campaign_id = _drafts[0]["campaign_id"]["S"]
            _issue_fids = [i["finding_id"]["S"] for i in _b3.client(
                "dynamodb", region_name="us-west-2").scan(
                TableName="vsa-staging-avx-findings").get("Items", [])
                if i.get("subject_key", {}).get("S") == f"{thread_id}/issue"]
            assert len(_issue_fids) == 1, _issue_fids
            records = dict(records, issue_finding_id=_issue_fids[0])  # for _state() only
        else:
            assert flipped, "the world never produced a draft row"
            assert iss_labels.get("issue-draft-dnd-safe") == "FAIL", holder[-1].rows
            if mode == "cleanup-recovers":
                mf["records"].pop("vin_s3_keys")
                mf_file.write_text(_js.dumps(mf))
            campaign_id = records["campaign_id"]

        def _state() -> dict:
            ddb = _b3.client("dynamodb", region_name="us-east-1")
            ddbw = _b3.client("dynamodb", region_name="us-west-2")
            s3 = _b3.client("s3", region_name="us-east-1")
            out: dict = {}
            out["draft"] = "Item" in ddb.get_item(
                TableName="adp-staging-recall-campaigns-issued",
                Key={"campaign_id": {"S": campaign_id}}, ConsistentRead=True)
            out["thread_rows"] = [i["version"]["N"] for i in ddb.query(
                TableName="adp-staging-digital-thread",
                KeyConditionExpression="thread_id = :t",
                ExpressionAttributeValues={":t": {"S": thread_id}}).get("Items", [])]
            objs = []
            for b in s3.list_buckets().get("Buckets", []):
                for o in s3.list_objects_v2(Bucket=b["Name"]).get("Contents", []):
                    if thread_id in o["Key"] or campaign_id in o["Key"]:
                        objs.append(f"{b['Name']}/{o['Key']}")
            out["s3"] = sorted(objs)
            out["actions"] = [
                aid for aid in (records.get("decision_action_id"), records.get("issue_action_id"))
                if aid and "Item" in ddbw.get_item(
                    TableName="vsa-staging-avx-actions",
                    Key={"action_id": {"S": aid}}, ConsistentRead=True)]
            out["findings"] = [
                fid for fid in (records.get("investigation_finding_id"),
                                records.get("issue_finding_id"))
                if fid and "Item" in ddbw.get_item(
                    TableName="vsa-staging-avx-findings",
                    Key={"finding_id": {"S": fid}}, ConsistentRead=True)]
            out["inv_row"] = "Item" in ddbw.get_item(
                TableName="vsa-staging-avx-investigations",
                Key={"investigation_id": {"S": records["investigation_id"]}},
                ConsistentRead=True)
            out["users"] = [u["Username"] for u in w.idp_client().list_users(
                UserPoolId=pool_id).get("Users", []) if run_id in str(u)]
            return out

        before = _state()
        assert before["s3"], f"expected objects to clean up; got {before}"

        _mod._SESSION = w.make_guarded_session("cleanup")
        _mod._SIGNAL_STATE.clear()
        with (
            patch.object(_mod, "_manifest_path", _manifest_path_hook),
            patch.object(_mod, "_utc_now", _safe_issue_time),
            patch.object(_mod, "_run_reconcile_check", lambda *a, **kw: None),
            patch.object(_mod, "Results", _Cap),
        ):
            rc_cl = main(["--stage", "staging", "--run-id", run_id,
                          "--part", "cleanup", "--allow-writes"])
        cl_fails = [(r[0], r[2]) for r in holder[-1].rows if r[1] == "FAIL"]
        left = {k: v for k, v in _state().items() if v}
        assert rc_cl == 0 and not cl_fails and not left, (rc_cl, cl_fails, left)
        if mode == "stop-before-step14":
            cl_labels = {r[0]: r[1] for r in holder[-1].rows}
            assert cl_labels.get("cleanup-recover-issue-records") == "PASS", holder[-1].rows


# ── F6f: cleanup recovers the draft and issue Finding ids (review cycle 3 W1) ──


def _f6f_run_recover(records: dict, rows: dict, issue_item: Any, tmp_path: Path) -> tuple:
    mf_path = tmp_path / "m.json"
    manifest = {"records": dict(records)}

    def _read(ddb: Any, tbl: str, key: dict) -> Any:
        assert tbl == "adp-staging-digital-thread"
        return rows.get(int(key["version"]["N"]))

    with (
        patch.object(_mod, "_client", lambda *a, **k: MagicMock()),
        patch.object(_mod, "_read_ddb_item", _read),
        patch.object(_mod, "_find_quality_issue_finding", lambda ddb, stage, tid: issue_item),
    ):
        res = Results()
        out = _mod._recover_issue_records(res, manifest, str(mf_path), "staging")
    labels = {r[0]: r[1] for r in res.rows}
    written = json.loads(mf_path.read_text()) if mf_path.exists() else None
    return out, labels, written


_F6F_TID = "thread-0102030405060708"
_F6F_BASE = {"thread_id": _F6F_TID, "thread_versions": [1], "decision_action_id": "dec-aid"}


def test_f6f_recovers_draft_and_issue_finding_from_this_runs_row(tmp_path: Path) -> None:
    rows = {1: {"thread_id": _F6F_TID, "version": 1, "action_id": "dec-aid",
                "recall_campaign_id": "MRD-2026-680"}}
    out, labels, written = _f6f_run_recover(
        _F6F_BASE, rows, {"finding_id": {"S": "FIND-iss-1"}}, tmp_path)
    assert out["campaign_id"] == "MRD-2026-680" and out["issue_finding_id"] == "FIND-iss-1"
    assert written["records"]["campaign_id"] == "MRD-2026-680"
    assert written["records"]["issue_finding_id"] == "FIND-iss-1"
    assert labels.get("cleanup-recover-issue-records") == "PASS"


def test_f6f_ignores_another_runs_row_and_fails_loud(tmp_path: Path) -> None:
    rows = {1: {"thread_id": _F6F_TID, "version": 1, "action_id": "someone-else",
                "recall_campaign_id": "MRD-2026-681"}}
    out, labels, written = _f6f_run_recover(_F6F_BASE, rows, None, tmp_path)
    assert "campaign_id" not in out and written is None
    assert labels.get("cleanup-recover-campaign-id") == "FAIL", labels


def test_f6f_bad_campaign_shape_not_recorded(tmp_path: Path) -> None:
    rows = {1: {"thread_id": _F6F_TID, "version": 1, "action_id": "dec-aid",
                "recall_campaign_id": "MRD-2026-680'; --"}}
