def test_f6f_noop_when_already_recorded_or_no_decision(tmp_path: Path) -> None:
    rows = {1: {"thread_id": _F6F_TID, "version": 1, "action_id": "dec-aid",
                "recall_campaign_id": "MRD-2026-999"}}
    done = dict(_F6F_BASE, campaign_id="MRD-2026-680", issue_finding_id="FIND-iss-1")
    out, labels, written = _f6f_run_recover(done, rows, {"finding_id": "FIND-x"}, tmp_path)
    assert out["campaign_id"] == "MRD-2026-680" and written is None and not labels
    no_dec = {"thread_id": _F6F_TID, "thread_versions": [1]}
    out, labels, written = _f6f_run_recover(no_dec, rows, None, tmp_path)
    assert "campaign_id" not in out and written is None and not labels


def test_a5_json_not_object_names_step() -> None:
    """Cycle 3 S1: a JSON list payload → ValueError naming the 'not an object' step."""
    import base64 as _b64  # noqa: PLC0415
    view_text = "/* Presto View: " + _b64.b64encode(b"[]").decode() + " */"
