# ── Leg G's first live run (2026-10-26, prompt 124): real DMS booking shapes ──
# Captured live: the book_fleet_service approve answers status `in_progress` with the
# RO id in `target_ref`; the DMS RO stores `avx_action_id` as the bare UUID and the VIN
# as `vehicle_vin` (`vin` null). The stubs above used `executed`, `act-...` ids and
# `vin`, so every one of these three gaps passed the suite and failed live.

_LIVE_BOOK_ACTION_ID = "AVX-ACT-00b97c4d-7c28-36af-bcab-1304aebaac73"
_LIVE_BOOK_BARE = "00b97c4d-7c28-36af-bcab-1304aebaac73"
_LIVE_RO_ID = "94a428c8-3f8e-50e8-a524-cf15b6352c9a"


def _live_dms_ro(*, ro_id: str, avx_action_id: str, vehicle_vin: str, status: str = "Draft",
                 fleet_id: str = "demo-rental-carshare") -> dict:
    """A DMS fleet-health RO item in the shape staging wrote at 15:35:53Z on 2026-10-26."""
    return {
        "ro_id": {"S": ro_id},
        "status": {"S": status},
        "avx_action_id": {"S": avx_action_id},
        "customer_type": {"S": "fleet"},
        "vin": {"NULL": True},
        "vehicle_vin": {"S": vehicle_vin},
        "dealer_id": {"S": "dealer-denver"},
        "fleet_id": {"S": fleet_id},
        "lines": {"L": [{"M": {
            "description": {"S": "P0A0D"}, "labor_op": {"S": "LAB-HVILK-01"},
            "line_no": {"S": "1"}, "need_id": {"S": "fault:P0A0D"},
            "pay_type": {"S": "customer_pay"},
        }}]},
    }


def _dms_table(ddb: Any, stage: str) -> str:
    name = _mod._DMS_RO_TABLE.format(stage=stage)
    ddb.create_table(
        TableName=name,
        KeySchema=[{"AttributeName": "ro_id", "KeyType": "HASH"}],
        AttributeDefinitions=[{"AttributeName": "ro_id", "AttributeType": "S"}],
        BillingMode="PAY_PER_REQUEST",
    )
    return name


def test_ground_book_accepts_the_real_in_progress_answer(tmp_path: Any) -> None:
    """book_fleet_service approved through the real DMS executor answers `in_progress`.

    Step 6 must PASS and record booked, the Action id and the RO id, so a resume never
    re-approves. Under `status == "executed"` it FAILed the first live run.
    """
    run_id = "fi-loop-20261026T153352-2ec5aaaa"
    labels = _ground_stub_result(
        fault_view_rows=[],
        stand_in_counts=(2, 1),  # SKIP the stand-in; this test is about step 6
        run_id=run_id,
        book_response=(200, {
            "status": "in_progress", "decision": "approved",
            "action_kind": _mod._BOOK_FLEET_SERVICE_KIND, "target_system": "dms",
            "action_id": _LIVE_BOOK_ACTION_ID, "target_ref": _LIVE_RO_ID,
        }),
        tmp_path=tmp_path,
    )
    assert labels.get("ground-book-fleet-service") == "PASS", labels
    recs = json.loads((tmp_path / f"{run_id}-manifest.json").read_text())["records"]
    assert recs.get("booked") == "true", recs
    assert recs.get("book_action_id") == _LIVE_BOOK_ACTION_ID, recs
    assert recs.get("book_ro_id") == _LIVE_RO_ID, recs


def test_ground_book_status_set_pinned_to_the_schema(tmp_path: Any) -> None:
    """Every Action status in the schema: exactly in_progress, executed, completed book.

    `completed` is what an idempotent re-approve returns on a resume after the RO reached
    Ready (review W1); `cancelled` (an early close), `failed`, `declined`, `dismissed` and
    `pending_execution` are not bookings and must never record `booked`.
    """
    schema = json.loads((_SCRIPT.parents[1] / "agents" / "tier2" / "schemas"
                         / "action.schema.json").read_text())
    statuses = schema["properties"]["status"]["enum"]
    assert len(statuses) >= 8 and "cancelled" in statuses, statuses
    accepted = {"in_progress", "executed", "completed"}
    assert set(_mod._BOOK_OK_STATUSES) == accepted
    for i, st in enumerate(statuses):
        run_id = f"fi-loop-20261026T153352-0000ab{i:02x}"
        labels = _ground_stub_result(
            fault_view_rows=[], stand_in_counts=(2, 1), run_id=run_id,
            book_response=(200, {"status": st, "action_kind": _mod._BOOK_FLEET_SERVICE_KIND,
                                 "action_id": _LIVE_BOOK_ACTION_ID, "target_ref": _LIVE_RO_ID}),
            tmp_path=tmp_path,
        )
        recs = json.loads((tmp_path / f"{run_id}-manifest.json").read_text())["records"]
        if st in accepted:
            assert labels.get("ground-book-fleet-service") == "PASS", (st, labels)
            assert recs.get("booked") == "true", (st, recs)
        else:
            assert labels.get("ground-book-fleet-service") == "FAIL", (st, labels)
            assert recs.get("booked") != "true", (st, recs)


def test_ours_matches_the_bare_uuid_dms_stores() -> None:
    """`_count_open_fi_bookings` counts our RO as ours by DMS's bare-UUID avx_action_id.

    With the prefixed comparison, ours was 0 and the stand-in never ran (live, 15:36Z).
    Another fleet's open FI booking still counts in total_open and is never ours.
    """
    import boto3 as _boto3  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415

    with _mock_aws():
        ddb = _boto3.client("dynamodb", region_name="us-west-2")
        t = _dms_table(ddb, "staging")
        ddb.put_item(TableName=t, Item=_live_dms_ro(
            ro_id=_LIVE_RO_ID, avx_action_id=_LIVE_BOOK_BARE, vehicle_vin="MRDAZ01S0SR03752W"))
        assert _mod._count_open_fi_bookings(ddb, "staging", _LIVE_BOOK_ACTION_ID) == (1, 1)
        # Nothing recorded yet ("pending" or empty) is never ours.
        assert _mod._count_open_fi_bookings(ddb, "staging", "pending") == (1, 0)
        assert _mod._count_open_fi_bookings(ddb, "staging", "") == (1, 0)
        ddb.put_item(TableName=t, Item=_live_dms_ro(
            ro_id="11111111-2222-3333-4444-555555555555",
            avx_action_id="99999999-8888-7777-6666-555555555555",
            vehicle_vin="MRDAZ01S0SC02FFKW", fleet_id="demo-last-mile-delivery"))
        assert _mod._count_open_fi_bookings(ddb, "staging", _LIVE_BOOK_ACTION_ID) == (2, 1)
        assert _mod._find_ro_id_for_action(ddb, "staging", _LIVE_BOOK_ACTION_ID) == _LIVE_RO_ID
        assert _mod._find_ro_id_for_action(ddb, "staging", "pending") == ""
        assert _mod._find_ro_id_for_action(
            ddb, "staging", "AVX-ACT-12345678-1234-1234-1234-123456789abc") == ""


def test_open_booking_seen_through_vehicle_vin() -> None:
    """DMS fleet ROs carry the VIN as `vehicle_vin` with `vin` null; the pick must see them."""
    import boto3 as _boto3  # noqa: PLC0415
    from moto import mock_aws as _mock_aws  # noqa: PLC0415

    with _mock_aws():
        ddb = _boto3.client("dynamodb", region_name="us-west-2")
        t = _dms_table(ddb, "staging")
        ddb.put_item(TableName=t, Item=_live_dms_ro(
            ro_id=_LIVE_RO_ID, avx_action_id=_LIVE_BOOK_BARE, vehicle_vin="MRDAZ01S0SR03752W"))
        assert _mod._has_open_booking(ddb, "staging", "MRDAZ01S0SR03752W") is True
        assert _mod._has_open_booking(ddb, "staging", "MRDAZ01S0SC02FFKW") is False
        ddb.put_item(TableName=t, Item=_live_dms_ro(
            ro_id=_LIVE_RO_ID, avx_action_id=_LIVE_BOOK_BARE, vehicle_vin="MRDAZ01S0SR03752W",
            status="Invoiced"))
        assert _mod._has_open_booking(ddb, "staging", "MRDAZ01S0SR03752W") is False


def test_stand_in_not_invoked_without_our_ro_id(tmp_path: Any) -> None:
    """Fail closed: our booking counted but its RO id not found -> no invoke, FAIL.

    Before, an empty RO id skipped the early-close check and invoked the stand-in.
    """
    invoked: list = []

    with (
        patch.object(_mod, "_find_ro_id_for_action", lambda *a, **k: ""),
        patch.object(_mod, "_would_early_close", lambda ro_id: invoked.append(("hash", ro_id)) or False),
    ):
        labels = _ground_stub_result(
            fault_view_rows=[], stand_in_counts=(1, 1),
            run_id="fi-loop-20261026T153352-0000f0c1",
            book_response=(200, {"status": "in_progress",
                                 "action_kind": _mod._BOOK_FLEET_SERVICE_KIND,
                                 "action_id": _LIVE_BOOK_ACTION_ID, "target_ref": _LIVE_RO_ID}),
            tmp_path=tmp_path,
        )
    assert labels.get("ground-stand-in") == "FAIL", labels
    recs = json.loads(
        (tmp_path / "fi-loop-20261026T153352-0000f0c1-manifest.json").read_text())["records"]
    assert not any(k.startswith("advanced_") for k in recs), recs
    assert invoked == [], invoked


