def test_book_resume_reapproves_the_recorded_booking_finding(tmp_path: Any) -> None:
    """A resume with book_action_id "pending" re-approves the recorded booking Finding.

    It must not scan for "the" booking Finding again: a later Tier 2 run can write a
    newer service/N for the VIN, and approving that one books a second RO.
    """
    recorded = "FIND-00000000-0000-4000-8000-00000000b00c"
    calls: list = []

    def _no_scan(*_a: Any, **_k: Any) -> Any:
        raise AssertionError("resume must not re-scan for the booking Finding")

    with patch.object(_mod, "_find_booking_finding_for_vin", _no_scan):
        labels = _ground_stub_result(
            fault_view_rows=[], stand_in_counts=(2, 1),
            run_id="fi-loop-20261026T153352-0000f0c3",
            initial_records={"booking_finding_id": recorded, "book_action_id": "pending"},
            book_response=(200, {"status": "in_progress",
                                 "action_kind": _mod._BOOK_FLEET_SERVICE_KIND,
                                 "action_id": _LIVE_BOOK_ACTION_ID, "target_ref": _LIVE_RO_ID}),
            http_calls=calls, tmp_path=tmp_path,
        )
    assert labels.get("ground-book-fleet-service") == "PASS", labels
    book_routes = [r for m, r in calls if m == "POST" and "approve" in r and recorded in r]
    assert book_routes == [f"findings/{recorded}/approve"], calls
